inline long long Pow(long long a, int b) {
	long long s = 1;
	while(b){
		if(b & 1) s = s * a % mod;
		a = a * a % mod, b >>= 1;
	}
	return s;
}
int a[200007], b[200007];
inline long long C(int n, int m) {
	return fac[n] * inv[m] % mod * inv[n - m] % mod;
