inline int add(int x, int y) {return x + y >= mod ? x + y - mod : x + y;}
inline int sub(int x, int y) {return x >= y ? x - y : x - y + mod;}

int n, fac[maxn << 1], ifac[maxn << 1];
int **f, **val, *_f[maxn], *_val[maxn], __f[maxn][maxn], __val[maxn][maxn];

int C(int n, int m)
{
	return (ll)fac[n] * ifac[m] % mod * ifac[n - m] % mod;
}

int main()
{
	n = gi();
	for (int i = 1; i <= 4010; ++i) _f[i] = __f[i] + 2005, _val[i] = __val[i] + 2005;
	f = _f + 2005; val = _val + 2005;

	fac[0] = ifac[0] = ifac[1] = 1;
	for (int i = 1; i <= 8000; ++i) fac[i] = (ll)fac[i - 1] * i % mod;
	for (int i = 2; i <= 8000; ++i) ifac[i] = (ll)(mod - mod / i) * ifac[mod % i] % mod;
	for (int i = 1; i <= 8000; ++i) ifac[i] = (ll)ifac[i - 1] * ifac[i] % mod;

	int ans = 0;
	for (int A, B, i = 1; i <= n; ++i) {
		A = gi(); B = gi();
		++val[A][B]; ++val[-A][-B];
		++f[A][B];
		ans = sub(ans, C((A << 1) + (B << 1), (A << 1)));
	}

	for (int i = 2000; i >= -2000; --i)
		for (int j = 2000; j >= -2000; --j) {
			if (!f[i][j]) continue;
			if (i > -2000) f[i - 1][j] = add(f[i - 1][j], f[i][j]);
			if (j > -2000) f[i][j - 1] = add(f[i][j - 1], f[i][j]);
		}

	for (int i = -1; i >= -2000; --i)
		for (int j = -1; j >= -2000; --j)
			if (val[i][j]) ans = add(ans, (ll)val[i][j] * f[i][j] % mod);
	printf("%lld\n", (ll)ans * (mod + 1) / 2 % mod);

	return 0;
}

