LL Qpow ( LL a, LL b ) {
	LL rec = 1 ;
	for ( ; b ; b >>= 1, (a *= a) %= modd )
		if (b&1) (rec *= a) %= modd ;
	return rec ;
}
void init() {
	LL i ;
