typedef long long ll;
const int MAXN = 1e6 + 10;
const int MM = 4e3 + 10;
const int Mod = 1e9 + 7;
int N;
int A[MAXN], B[MAXN];
ll fac[MM], ifc[MM];
ll f[MM][MM];
ll ans;

inline int fp(int a, int b) {
	int x = 1;
	while(b) {
		if(b & 1) x = 1ll * x * a % Mod;
		a = 1ll * a * a % Mod; b >>= 1;
	}
	return x;
}

inline void init(int n) {
	register int i;
	for(*fac = i = 1; i <= n; ++i) fac[i] = 1ll * fac[i - 1] * i % Mod;
	for(ifc[n] = fp(fac[n], Mod - 2), i = n; i; --i) ifc[i - 1] = 1ll * ifc[i] * i % Mod;
}

inline int C(int n, int k) {
	if(n < 0 || k < 0 || n < k) return 0;
	return 1ll * fac[n] * ifc[k] % Mod * ifc[n - k] % Mod;
}

int main() {
	register int i, j; init(8e3);
	scanf("%d", &N);
	for(i = 1; i <= N; ++i)
		scanf("%d%d", A + i, B + i),
		++f[2001 - A[i]][2001 - B[i]];
	for(i = 1; i <= 4001; ++i)
		for(j = 1; j <= 4001; ++j)
			f[i][j] = ((ll) f[i][j] + f[i - 1][j] + f[i][j - 1]) % Mod;
	for(i = 1; i <= N; ++i)
		ans = ((ll) ans + f[2001 + A[i]][2001 + B[i]]) % Mod;
	for(i = 1; i <= N; ++i)
		ans = ((ll) ans - C(2 * A[i] + 2 * B[i], 2 * A[i]) + Mod) % Mod;
	printf("%lld\n", 1ll * ans * fp(2, Mod - 2) % Mod);
	return 0;
}

