const int N = 2000 + 10 , mod = ( int ) 1e9 + 7 ; 

int n , dp [ ( N << 1 ) + 100 ] [ ( N << 1 ) + 100 ] , comb [ N << 2 ] [ N << 2 ] ; 
vector < pair < int , int > > vec ; 

int pw ( int x , int y ) {
	int ret = 1 ;
	for ( ; y ; y >>= 1 , ( x = 1LL * x * x % mod ) %= mod )
		if ( y & 1 )
			( ret = 1LL * ret * x % mod ) %= mod ; 
	return ret ;
}

int32_t main()
{
	ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);
	cin >> n ;
	for ( int i = 0 ; i < n ; ++i ) {
		int a , b ;
		cin >> a >> b ;
		vec.push_back ( { a , b } ) ; 
		++ dp [ -a + N ] [ -b + N ] ; 
	}
	for ( int i = 0 ; i < ( N << 1 ) + 100 ; ++i ) {
		for ( int j = 0 ; j < ( N << 1 ) + 100 ; ++j ) {
			if ( i )
				dp [ i ] [ j ] += dp [ i - 1 ] [ j ] ;
			if ( dp [ i ] [ j ] >= mod )
				dp [ i ] [ j ] -= mod ; 
			if ( j )
				dp [ i ] [ j ] += dp [ i ] [ j - 1 ] ;
			if ( dp [ i ] [ j ] >= mod )
				dp [ i ] [ j ] -= mod ; 
		}
	}
	for ( int i = 0 ; i < ( N << 2 ) ; ++i ) {
		comb [ i ] [ 0 ] = comb [ i ] [ i ] = 1 ;
		for ( int j = 1 ; j < i ; ++j ) {
			comb [ i ] [ j ] = ( comb [ i - 1 ] [ j ] + comb [ i - 1 ] [ j - 1 ] ) % mod ; 
		}
	}
	int res = 0 ;
	for ( auto pi : vec ) { 
		res += dp [ pi.first + N ] [ pi.second + N ] ; 
		if ( res >= mod ) res -= mod ;
	}
	for ( auto pi : vec ) {
		res -= comb [ 2 * ( pi.first + pi.second ) ] [ 2 * pi.first ] ;
		if ( res < 0 ) res += mod ; 
	}
	( res = 1LL * res * pw ( 2 , mod - 2 ) % mod ) %= mod ;
	cout << res << '\n' ; 
}

