int C(int x, int y) {
    return 1LL * fac[x] * ifac[y] % MOD * ifac[x - y] % MOD;
}

int main() {
    inv[1] = fac[0] = ifac[0] = 1;
    for (int i = 2; i <= M; ++i) inv[i] = 1LL * inv[MOD % i] * (MOD - MOD / i) % MOD;
    for (int i = 1; i <= M; ++i) fac[i] = 1LL * fac[i - 1] * i % MOD;
    for (int i = 1; i <= M; ++i) ifac[i] = 1LL * ifac[i - 1] * inv[i] % MOD;
