int bp(int x, int y){
	int z = 1;
	while(y){
		if(y & 1)
			z = 1LL * z * x % mod;
		x = 1LL * x * x % mod;
		y >>= 1;
	}
	return z;
}

int cnk(int x, int y){
	return 1LL * f[x] * rv[y] % mod * rv[x - y] % mod;
}

