    int k=0;char ch=gt;
    while(ch<'-')ch=gt;
    while(ch>'-')k=k*10+ch-'0',ch=gt;
    return k;
}
const int YL=1e9+7,M=2e7+5,N=1e5+5;
inline int MO(const int &a){return a>=YL?a-YL:a;}
int ksm(int a,int k){int r=1;while(k){if(k&1)r=1ll*r*a%YL;a=1ll*a*a%YL,k>>=1;}return r;}
int fac[M],fnv[M],n,f[M],dp[M],a[N],b[N];
inline int C(int x,int y){return y>x?0:1ll*fac[x]*fnv[y]%YL*fnv[x-y]%YL;}
int main()
{
	n=in();int sum_a=0,sum_b=0;
	for(int i=1;i<=n;++i)sum_a+=a[i]=in(),sum_b+=b[i]=in();
	int T=sum_a+sum_b;fac[0]=fnv[0]=1;
	for(int i=1;i<=T;++i)fac[i]=1ll*fac[i-1]*i%YL;fnv[T]=ksm(fac[T],YL-2);
	for(int i=T;i>=1;--i)fnv[i-1]=1ll*fnv[i]*i%YL;
	int ans=0;
	for(int i=1;i<=n;++i)
	{
		for(int j=1;j<=b[i];++j)ans=(ans+1ll*f [j]*C(a[i]+b[i],a[i]+j))%YL;
		for(int j=0;j<=a[i];++j)ans=(ans+1ll*dp[j]*C(a[i]+b[i],a[i]-j))%YL;
		for(int j=0;j<=b[i];++j)dp[j]=MO(dp[j]+C(a[i]+b[i],a[i]+j));
		for(int j=0;j<=a[i];++j)f [j]=MO(f [j]+C(a[i]+b[i],a[i]-j));
	}
	printf("%d\n",MO(ans+ans));
	return 0;
}

#include <bits/stdc++.h>
