const int MAXN = 2e5 + 100, maxval = 2010, mod = 1e9 + 7;

int n;
int a[MAXN], b[MAXN];
int dp[maxval << 1][maxval << 1];
long long fact[MAXN], invfact[MAXN];
long long ans;

long long pw(long long a, long long b) {
    if (!b)
        return 1LL;
    long long tmp = pw(a, b / 2);

    tmp = tmp * tmp % mod;

    if (b & 1)
        tmp = tmp * a % mod;
    return tmp;
}

inline void sum(int &a, int b) {
    a += b;
    if (a >= mod)
        a -= mod;
    else if (a < 0)
        a += mod;
}

long long comb(int n, int r) {
    return fact[n] * (invfact[r] * invfact[n - r] % mod) % mod;
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
    fact[0] = 1;
    invfact[0] = pw(fact[0], mod - 2);

    for (int i = 1; i < MAXN; i++) {
        fact[i] = fact[i - 1] * i % mod;
        invfact[i] = pw(fact[i], mod - 2);
    }

    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a[i] >> b[i];
        dp[maxval - a[i]][maxval - b[i]]++;
    }

    for (int i = 0; i < maxval * 2 - 2; i++)
        for (int j = 0; j < maxval * 2 - 2; j++) {
            sum(dp[i + 1][j], dp[i][j]);
            sum(dp[i][j + 1], dp[i][j]);
        }

    for (int i = 0; i < n; i++)
        ans = (ans + dp[maxval + a[i]][maxval + b[i]]) % mod;

    for (int i = 0; i < n; i++)
        ans = (ans - comb(2 * a[i] + 2 * b[i], 2 * a[i]) + mod) % mod;

    cout << ans * invfact(2) % mod << '\n';
    return 0;
}

