long long quipow(long long a,long long b)
{
	long long ret=1;
	while(b){
		if(b&1) ret=(ret*a)%Mod;
		b>>=1;
		a=(a*a)%Mod;
	}
	return ret;
}
int main()
{
	fac[0]=fac[1]=1;
	for(int i=2;i<=4000;i++) fac[i]=(fac[i-1]*i)%Mod;
	inv[4000]=quipow(fac[4000],Mod-2);
	for(int i=3999;i>=0;i--)inv[i]=(inv[i+1]*(i+1))%Mod;
	scanf("%lld",&n);
	for(int i=1;i<=n;i++) scanf("%lld%lld",&a[i],&b[i]),f[2001-a[i]][2001-b[i]]++;
    for(int i=1;i<4002;i++) for(int j=1;j<4002;j++) f[i][j]=(f[i][j]+f[i-1][j]+f[i][j-1])%Mod;
    for(int i=1;i<=n;i++) ans=(ans+f[2001+a[i]][2001+b[i]])%Mod;
    for(int i=1;i<=n;i++) ans=(ans-(fac[(a[i]+b[i])<<1]*inv[b[i]<<1]%Mod*inv[((a[i]+b[i])<<1)-(b[i]<<1)]%Mod)+Mod)%Mod;
    ans=(ans*quipow(2,Mod-2))%Mod;
