signed a[MAXN];
signed b[MAXN];
double ab[MAXSIZE];

int binpow(int a, int b, int mo) {
  int ans = 1;
  do {
    if (b & 1) ans = 1ll * ans * a % mo;
    a = 1ll * a * a % mo;
  } while (b >>= 1);
  return ans;
}

const int FACTSIZE = 4040;
int fact[FACTSIZE];
int revfact[FACTSIZE];

int ncr(int n, int r) {
  if (n < r) return 0;
  int rs = fact[n] * revfact[r];
  if (rs >= MOD) rs %= MOD;
  rs *= revfact[n - r];
  if (rs >= MOD) rs %= MOD;
  return rs;
}
void init() {
  fact[0] = 1, revfact[0] = 1;
  for (int i = 1; i < FACTSIZE; ++i) {
    fact[i] = fact[i - 1] * i % MOD;
    revfact[i] = binpow(fact[i], MOD - 2, MOD);
  }
}
signed ip[10000];
double w[(MAXSIZE / 4)];

void convolve2(double *a, signed n) {
  signed s = n + n - 1;  // 畳み込み結果のサイズ
  signed t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  ip[0] = 0;
  cdft(2 * t, 1, a, ip, w);
  for (signed i = 0; i < t; i++) {
    signed addr = 2 * i;
    double tmpa = a[addr];
    a[addr] = a[addr] * a[addr] - a[addr + 1] * a[addr + 1];
    a[addr + 1] = 2 * tmpa * a[addr + 1];
  }
  cdft(2 * t, -1, a, ip, w);
  for (signed j = 0; j < t; j++) {
    a[j * 2] *= 1.0 / t;
    a[j] = a[j * 2];
  }
}

