/*
发现a[i]和b[i]很小,是可以O(n^2)的范围

C(x+y,x)可以看作是(0,0)到(x,y)的方案数,
如果我们要求(0,0)到(x,y)的方案数,
可以令d[i][j]表示(0,0)到(i,j)的方案数,一开始d[0][0]=1.
转移方程为d[i][j]=d[i-1][j]+d[i][j-1].

C(a[i]+a[j]+b[i]+b[j],a[i]+a[j])可以看作:
(0,0)到(a[i]+a[j],b[i]+b[j])的方案数.

枚举i和j是O(n^2)的,显然要优化,
尝试将i和j分开:
将坐标位移一下变为(-a[i],-b[i])到(a[j],b[j])的方案数.
这样i和j就分离了,然后就可以单独计算每个部分的贡献.

观察前面的dp方程,我们一开始令d[0][0]=1,
然后计算出的d[x][y]就是(0,0)到(x,y)的方案数,
那么我们令d[-a[i]][-b[i]]=1,
那么计算出的d[x][y]就是(-a[i],-b[i])到(x,y)的方案数.
这样的话,我们一开始只需要令所有的d[-a[i]][-b[i]]++,
那么计算出来的d[x][y]就是所有数对到达(x,y)的方案数.
因此最后只需要累加d[a[i]][b[i]]即可.
但是存在(-a[i],-b[i])到(a[i],b[i])的方案数,也就是自己和自己匹配,
而题目只需要计算i<j的,因此减掉自己和自己匹配的,方案数为C(2*(a[i]+b[i]),2*a[i]).
最后答案还要再除以2,因为是计算出的是无序的,题目要的是有序的.

参考:
https://www.luogu.com.cn/blog/Ebola-Emperor/solution-at1983
https://www.luogu.com.cn/blog/208529/solution-at1983
*/

#include <cstdio>
#include <algorithm>

using namespace std;

int m = 1000000007;
int a[200000][2];
int dp[4001][4001];
long long inv[8001];
long long fact[8001];
long long invfact[8001];

void calc_inv(int n, int mod) {
    inv[1] = 1;
    for (int i = 2; i <= n; i++) inv[i] = inv[mod % i] * (mod - mod / i) % mod;

    fact[0] = invfact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;
    for (int i = 1; i <= n; i++) invfact[i] = invfact[i - 1] * inv[i] % mod;
}

long long comb(int x, int y) {
    return fact[x] * invfact[y] % m * invfact[x - y] % m;
}

long long mod_inverse(long long a, long long m) {
    long long b = m, x = 1, y = 0;

    while (b) {
        long long t = a / b;

        a -= t * b;
        x -= t * y;

        swap(a, b);
        swap(x, y);
    }

    return (m + x % m) % m;
}

int main() {
    int n, i, j;
    long long ans = 0;

    calc_inv(8000, m);

    scanf("%d", &n);

    for (i = 0; i < n; i++) {
        scanf("%d %d", &a[i][0], &a[i][1]);

        dp[2000 - a[i][0]][2000 - a[i][1]]++;
    }

    for (i = 0; i <= 4000; i++) {
        for (j = 0; j <= 4000; j++) {
            if (dp[i][j] == 0) continue;

            if (i + 1 <= 4000) {
                dp[i + 1][j] += dp[i][j];
                if (dp[i + 1][j] >= m) dp[i + 1][j] -= m;
            }

            if (j + 1 <= 4000) {
                dp[i][j + 1] += dp[i][j];
                if (dp[i][j + 1] >= m) dp[i][j + 1] -= m;
            }
        }
    }

    for (i = 0; i < n; i++) {
        ans += dp[2000 + a[i][0]][2000 + a[i][1]];
        ans += m - comb(a[i][0] * 2 + a[i][1] * 2, a[i][0] * 2);
    }

    printf("%lld\n", ans % m * mod_inverse(2, m) % m);

    return 0;
}

