void FFT(point a[],bool rev)
{
	for(int i=0,j=0;i<sz;i++)
	{
		if(i>j)swap(a[i],a[j]);
		for(int l=sz>>1;(j^=l)<l;l>>=1);
	}
	for(int l=1;l<sz;l<<=1)
	{
		int l2=l<<1;
		for(int i=0;i<sz;i+=l2)
		{
			for(int j=0;j<l;j++)
			{
				point t=a[i+j+l]*w[rev?sz-sz/l2*j:sz/l2*j];
				a[i+j+l]=a[i+j]-t;
				a[i+j]=a[i+j]+t;
			}
		}
	}
	if(rev)for(int i=0;i<sz;i++)a[i]=a[i]/sz;
}
