        if (i < 2*MAX) {
            dp[i][j] += dp[i+1][j];
            dp[i][j] %= MOD;
        }
        if (j < 2*MAX) {
            dp[i][j] += dp[i][j+1];
            dp[i][j] %= MOD;
        }
    }

    get_fractorial(MAX * 2);

    int ans = 0;
    REP (i,n) ans = (ans + dp[MAX-a[i]][MAX-b[i]]) % MOD;
    REP (i,n) ans = (ans - frac[(a[i]+b[i]) * 2] * modinv(frac[a[i]*2] * frac[b[i]*2] % MOD) % MOD + MOD) % MOD;
    ans = ans * modinv(2) % MOD;
    printf("%d\n",ans);
    return 0;
}

