using namespace std;
typedef long long ll;
typedef pair<int, int> P;
typedef vector<int> vi;
ll extgcd(ll a, ll b, ll& x, ll& y) {
	ll d = a;
	if (b != 0) {
		d = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}
ll inverse(ll a,ll m) {
	ll x, y;
	extgcd(a, m, x, y);
	return (m + x%m) % m;
}
ll inv(ll a) {
	ll m = MOD;
	return inverse(a, m);
}
int dp[2001][2001];
ll combination(ll a, ll b) {
	if (b > a / 2)b = a - b;
	if (b < 0)return 0;
	if (b == 0)return 1;
	if (dp[a][b] > 0)return dp[a][b];
	ll ans = 1;
	for (ll i = a; i > a - b; i--) {
		ans *= i;
		ans %= MOD;
	}
	for (ll i = 1; i <= b; i++) {
		ans *= inv(i);
		ans %= MOD;
	}
	dp[a][b] = (ans + MOD) % MOD;
	return (ans+MOD)%MOD;
}

