			x += combination(D[i], A[i] + k);
			y += combination(D[i], A[i] - k);
			x %= MOD;
			y %= MOD;
		}
		ans += (x*y) % MOD;
		ans %= MOD;
	}
	ll same = 0;
	for (int i = 0; i < n; i++) {
		same += combination(2 * D[i], 2 * A[i]);
		same %= MOD;
	}
	ans = (ans - same) % MOD;
	ans += MOD;
	ans %= MOD;
	if (ans % 2 == 0)ans /= 2;
	else ans = (ans + MOD) / 2;
	cout << ans << endl;
}

