const int MAX = 1000 * 2 + 7;

int F[MAX * 4], RF[MAX * 4];
PII A[200007];


int BP(LL a, int n)
{
    LL res = 1;
    while(n)
    {
        if (n & 1)res = (res * a) % MOD;
        a *= a;
        a %= MOD;
        n >>= 1;
    }
    return res;
}

int C(int a, int b)
{
    LL res = F[a];
    res *= RF[b];
    res %= MOD;
    res *= RF[a-b];
    res %= MOD;
    return res;
}

int DP[2 * MAX][2 * MAX];
int get(int x, int y)
{
    //cout << x << " " << y << endl;
    if (DP[x][y] != -1)
    {
        //if (DP[x][y])cout << x << " " << y << " " << DP[x][y] << endl;
        return DP[x][y];
    }
    LL res = 0;
    if (x)res += get(x-1, y);
    if (y)res += get(x, y-1);
    while(res >= MOD)res -= MOD;
    return DP[x][y] = res;
}


