inline int lgput( int x, int n ) {
    if( n == 0 )
        return 1;

    int y = lgput( x, n / 2 );

    y = ( 1LL * y * y ) % MOD;
    if( n % 2 == 1 )
        y = ( 1LL * y * x ) % MOD;

    return y;
}

inline int comb( int n, int k ) {
    return ( ( ( 1LL * fct[n] * inv[k] ) % MOD ) * inv[n - k] ) % MOD;
}

