	{
		for(int j=0;j<SIZE;j++)
		{
			if(i>0) dp[i][j]+=dp[i-1][j];
			if(j>0) dp[i][j]+=dp[i][j-1];
			if(dp[i][j]>=MOD) dp[i][j]-=MOD;
		}
	}
	ll ret=0;
	for(int i=0;i<n;i++)
	{
		ret+=dp[MD+A[i]][MD+B[i]];
		if(ret>=MOD) ret-=MOD;
		ret-=C(2*(A[i]+B[i]),2*A[i]);
		if(ret<0) ret+=MOD;
	}
	ret*=inv[2];
	ret%=MOD;
	printf("%lld\n",ret);
	return 0;
}

