{
	for (int i = Add;i >= -Add;--i)
		for (int j = Add;j >= -Add;--j)
		{
			update(F[i + Add][j + Add], F[(i + 1) + Add][j + Add]);
			update(F[i + Add][j + Add], F[i + Add][(j + 1) + Add]);
		}
}

