inline LL power(LL x, LL to)
{
	LL res = 1;
	while (to)
	{
		if (to & 1)
			res = (res * x) % mod;

		x = (x*x) % mod;
		to >>= 1;
	}
	return res;
}

LL solve()
{
	//C(2a, 2b);
	LL res = 0, add;

	FOR(i, 0, n)
	{
		add = (fact[a[i] * 2 + b[i] * 2]) * revFact[a[i] * 2] % mod;
		add *= revFact[b[i] * 2];
		add %= mod;
		res += add;
	}

	res %= mod;
	return res;
}

LL calculate()
{
	DP1.assign(MAXN, VLL(MAXN, 0));
	DP2.assign(MAXN, VLL(MAXN, 0));
	FOR(i, 0, n)
		DP1[a[i] + MAXK][b[i] + MAXK]++, DP2[MAXK - a[i]][MAXK - b[i]]++;

	RFOR(i, MAXN - 1, 0)
		RFOR(j, MAXN - 1, 0)
		DP1[i][j] = (DP1[i][j] + DP1[i + 1][j] + DP1[i][j + 1]) % mod;

	LL ans = 0;

	FOR(i, 0, MAXN)
		FOR(j, 0, MAXN)
		ans = (ans + DP1[i][j] * DP2[i][j]) % mod;

	ans %= mod;
	return ans;
}

