using namespace std;
using modulo = modint<1000000007>;
int main() {
	int N;
	cin >> N;
	vector<int> A(N), B(N);
	int la = 0, lb = 0;
	for (int i = 0; i < N; ++i) {
		cin >> A[i] >> B[i];
		la = max(la, A[i]);
		lb = max(lb, B[i]);
	}
	vector<vector<modulo> > dp(la + 1, vector<modulo>(lb + 1)), comb(la * 2 + 1, vector<modulo>(lb * 2 + 1));
	comb[0][0] = 1;
	for (int i = 0; i <= la * 2; ++i) {
		for (int j = 0; j <= lb * 2; ++j) {
			if (i >= 1) comb[i][j] += comb[i - 1][j];
			if (j >= 1) comb[i][j] += comb[i][j - 1];
		}
	}
	for (int i = 0; i < N; ++i) {
		dp[A[i]][B[i]] += 1;
	}
	for (int i = la; i >= 1; --i) {
		for (int j = lb; j >= 1; --j) {
			dp[i - 1][j] += dp[i][j];
			dp[i][j - 1] += dp[i][j];
		}
	}
	modulo ans = 0;
	for (int i = 1; i <= la; ++i) {
		for (int j = 1; j <= la; ++j) {
			ans += dp[i][0] * dp[j][0];
		}
	}
	for (int i = 1; i <= lb; ++i) {
		for (int j = 1; j <= lb; ++j) {
			ans += dp[0][i] * dp[0][j];
		}
	}
	for (int i = 1; i <= la; ++i) {
		for (int j = 1; j <= lb; ++j) {
			ans += dp[i][0] * dp[0][j] * comb[i][j] * 2;
		}
	}
	for (int i = 0; i < N; ++i) {
		ans -= comb[A[i] * 2][B[i] * 2];
	}
	ans *= modulo(2).inv();
	cout << ans.get() << endl;
	return 0;
}

