    int i, j, n, a, b, ans=0;
    for(i=0; i<2*N; i++) bn[i][0]=1;
    for(i=1; i<2*N; i++) for(j=1; j<=i; j++) {
        bn[i][j]=bn[i-1][j]+bn[i-1][j-1];
