        scanf("%d%d", &a, &b);
        ans=(ans+P-bn[2*a+2*b][2*b])%P;
        for(j=0; j<=a+b; j++)
            t[N-a+j]+=bn[a+b][j];
    }
    for(i=-N+1; i<N; i++) t[N+i]%=P;
    for(i=-N+1; i<N; i++)
        ans=(ans+t[i+N]*t[-i+N])%P;
    printf("%lld\n",ans*PH%P);
    return 0;
}

