#include <bits/stdc++.h>
using namespace std;

const long long mod = 1e9 + 7;

long long modpow(long long a, long long b) {
	if (b == 0) return 1;
	return modpow(a * a % mod, b / 2) * (b & 1 ? a : 1) % mod;
}

long long modinv(long long a) {
	return modpow(a, mod - 2);
}

vector<long long> fact, inv_fact;

void init_fact(int n) {
	fact.resize(n);
	fact[0] = 1;
	for (int i = 1; i < n; i++) {
		fact[i] = i * fact[i - 1] % mod;
	}
	inv_fact.resize(n);
	inv_fact[n - 1] = modinv(fact[n - 1]);
	for (int i = n - 2; i >= 0; i--) {
		inv_fact[i] = (i + 1) * inv_fact[i + 1] % mod;
	}
}

long long nPr(int n, int r) {
	if (n < r || n < 0 || r < 0) return 0;
	return fact[n] * inv_fact[n - r] % mod;
}

long long nCr(int n, int r) {
	if (n < r || n < 0 || r < 0) return 0;
	return fact[n] * inv_fact[r] % mod * inv_fact[n - r] % mod;
}

long long nHr(int n, int r) {
	if (n == 0 && r == 0) return 1;
	return nCr(n + r - 1, r);
}

int main() {
	init_fact(101010);

	int n;
	cin >> n;

	vector<int> a(n), b(n);
	static long long dp[4400][4400];
	for (int i = 0; i < n; i++) {
		scanf("%d %d", &a[i], &b[i]);
		dp[2010 - a[i]][2010 - b[i]]++;
	}

	for (int i = 0; i < 4200; i++) {
		for (int j = 0; j < 4200; j++) {
			(dp[i + 1][j] += dp[i][j]) %= mod;
			(dp[i][j + 1] += dp[i][j]) %= mod;
		}
	}

	long long ans = 0;
	for (int i = 0; i < n; i++) {
		(ans += dp[2010 + a[i]][2010 + b[i]]) %= mod;
		(ans += mod - nCr(a[i] * 2 + b[i] * 2, a[i] * 2)) %= mod;
	}
	ans = ans * modinv(2) % mod;
	cout << ans << endl;
}

