	REP (i, n) dec (ans, binom (2 * x[i] + 2 * y[i], 2 * x[i]));//, printf ("!%d %d\n", i, binom (2 * x[i] + 2 * y[i], 2 * x[i]));
	//printf ("!%d\n", ans);
