void fft2(vector<C>& a,vector<C>& b){
   vector<C> c(sz); rep(i,0,sz)c[i]=C(a[i].x,b[i].x);
   fft(c);
   rep(i,0,sz){
      int idx=sz-1-i;
      a[i]=(c[i]+~c[idx])*C(0.5,0);
      b[i]=(c[i]-~c[idx])*C(0,-0.5);
   }
}
void ifft2(vector<C>& a,vector<C>& b){
   vector<C> c(sz); rep(i,0,sz)c[i]=a[i]+b[i]*C(0,1);
   fft(c,1);
   rep(i,0,sz){a[i].x=c[i].x; b[i].x=c[i].y;}
}
void fft2d(bool inv=0){
   for(int i=0;i<sz;i+=2){
      if(inv){fft(buf[i],1); fft(buf[i+1],1);}
      else fft2(buf[i],buf[i+1]);
   }
   rep(i,0,sz)rep(j,0,i)swap(buf[i][j],buf[j][i]);
   for(int i=0;i<sz;i+=2){
      if(inv) ifft2(buf[i],buf[i+1]);
      else{fft(buf[i]); fft(buf[i+1]);}
   }
   if(inv)rep(i,0,sz)rep(j,0,sz)buf[i][j].x/=sz*sz;
}

