using namespace std;

const long MODN = 1000000007;
const int MAXN = 2005;

vector<long> prime;

long combans[8011][4011];

void Init() {
    bool isp[4 * MAXN];
    memset(isp, true, sizeof(isp));
    for (int i = 2; i < 4 * MAXN; i++) {
        if (isp[i]) {
            prime.push_back(i);
            for (int j = i * i; j < 4 * MAXN; j += i) { isp[j] = false; }
        }
    }
}

int Calce(int x, int p) {
    long ans = 0;
    int q = p;
    while(x >= q) {
        ans += x/q;
        q *= p;
    }
    return ans;
}

long Pow(long x, int k) {
    long ans = 1;
    while (k) {
        if (k & 1) { ans = (ans * x) % MODN; }
        x = (x * x) % MODN;
        k >>= 1;
    }
    return ans;
}

long Combination(int a, int b) {
    long ans = 1;
    int exp_num;
    for (int i = 0; i < prime.size(); i++) {
        exp_num = Calce(a, prime[i])
                - Calce(b, prime[i])
                - Calce(a - b, prime[i]);
        ans = (ans * Pow(prime[i], exp_num)) % MODN;
    }
    return ans;
}

int main() {
    Init();
    long ans = 0;
    int n, l1, l2;
    int a[200010], b[200010];
    scanf("%d", &n);
    for (int i = 0 ; i < n; i++) {
        scanf("%d %d", &l1, &l2);
        a[i] = l1;
        b[i] = l2;
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            int big = a[i] + a[j] + b[i] + b[j];
            int small = a[i] + a[j];
            if (big - small < small) { small = big - small; }
            ans += Combination(big, small);
        }
    }

    printf("%ld\n", ans);

    return 0;
}

