ll qpow(ll a, ll b) {
	ll res = 1;
	for (; b; b >>= 1, a = a * a % MOD)
		if (b & 1) res = res * a % MOD;
	return res;
}

void init() {
	fra[0] = 1;
	for (ll i = 1; i <= 8000; i++) fra[i] = fra[i - 1] * i % MOD;
	inv[8000] = qpow(fra[8000], MOD - 2);
	for (ll i = 7999; i > 0; i--) inv[i] = inv[i + 1] * (i + 1) % MOD;
}

ll C(ll n, ll m) {
	if (m > n) return 0;
	return fra[n] * inv[n - m] % MOD * inv[m] % MOD;
}

