void fft(vector<base> &a, bool inv){
    int sz = a.size(),i,len,j;

    for (i=0; i<sz; i++)
        if (i<rev(i,lg)) swap(a[i],a[rev(i,lg)]);

    for (len=2; len<=sz; len<<=1){
        double ang = 2*pi/len * (inv ? -1 : 1);
        base wlen(cos(ang),sin(ang));
        for (i=0; i<sz; i+=len){
            base w(1,0);
            for (j=0; j<len/2; j++){
                base u = a[i+j], v = w*a[i+len/2+j];
                a[i+j] = u + v;
                a[i+len/2+j] = u - v;

                w*=wlen;
            }
        }
    }

    if (inv)
        for (i=0; i<sz; i++)
            a[i]/=sz;
}

void fft2d(carray2d &a, bool inv){
    int i,j;
    for (i=0; i<sz; i++)
        fft(a[i],inv);

    for (i=0; i<sz; i++){
        vector<base> cr;
        for (j=0; j<sz; j++)
            cr.pb(a[j][i]);

        fft(cr,inv);
        for (j=0; j<sz; j++)
            a[j][i]=cr[j];
    }
}

