ll f[4 * MAXV], _f[4 * MAXV];

int cnt[2 * MAXV][2 * MAXV];

ll pow_mod(ll a, ll st){
	ll ans = 1ll;
	for(; st; st >>= 1){
		if (st & 1){
			ans = (ans * a) % MOD;
		}
		a = (a * a) % MOD;
	}
	return ans;
}

void solve(){
	int n;
	scanf("%d", &n);
	REP(i, 0, n){
		scanf("%d%d", &a[i], &b[i]);
	}

	f[0] = 1;
	REP(i, 1, 4 * MAXV){
		f[i] = (f[i - 1] * i) % MOD;
	}

	_f[4 * MAXV - 1] = pow_mod(f[4 * MAXV - 1], MOD - 2);
	for(int i = 4 * MAXV - 2; i >= 0; i--){
		_f[i] = (_f[i + 1] * (i + 1)) % MOD;
	}

	int offset = 2000;
	REP(i, 0, n){
		cnt[offset - a[i]][offset - b[i]]++;
	}
	ll ans = 0ll;
	REP(i, 0, 2 * MAXV){
		REP(j, 0, 2 * MAXV){
			if (i){
				dp[i][j] = dp[i - 1][j];
			}
			if (j){
				dp[i][j] += dp[i][j - 1];
			}
			dp[i][j] += cnt[i][j];
			if (dp[i][j] >= MOD){
				dp[i][j] -= MOD;
				if (dp[i][j] >= MOD){
					dp[i][j] -= MOD;
				}
			}
