				if (2 * offset - i >= 0 && 2 * offset - j >= 0){
					ans = (ans + (ll)cnt[2 * offset - i][2 * offset - j] * (ll)dp[i][j]) % MOD;
				}
			}
		}
	}

	REP(i, 0, n){
		ll c = (f[a[i] + a[i] + b[i] + b[i]] * _f[a[i] + a[i]]) % MOD;
