		//cout << a[i] + a[i] + b[i] + b[i] << " " << a[i] + a[i] << " " << c << endl;
		ans = (ans + MOD - c) % MOD;
	}
	ll tmp = (MOD + 1) / 2;
	ans = (ans * tmp) % MOD;
	cout << ans << endl;
}	

