	rep (i, 1, n) (ans += dp[2000 + a[i]][2000 + b[i]]) %= Mod;
	rep (i, 1, n) (ans += Mod - C(2 * (a[i] + b[i]), 2 * a[i])) %= Mod;

	cout << ans * 1ll * invFac[2] % Mod << endl;
}

