#include <bits/stdc++.h>
#define LL long long
using namespace std;

const LL Mod = 1000000007;
LL n, A[ 200010 ], B[ 200010 ], F[ 4010 ][ 4010 ], Rec1[ 4010 ], Rec2[ 4010 ];
LL Inv[ 4010 ], Fact[ 4010 ];
LL Ans;

void Exgcd( LL a, LL b, LL &x, LL &y ) {
    if( b == 0 ) {
        x = 1; y = 0; return;
    }
    Exgcd( b, a % b, y, x );
    y -= a / b * x;
    return;
}

LL inv( LL a ) {
    LL b = Mod;
    LL x, y;
    Exgcd( a, b, x, y );
    if( x < 0 ) return x + Mod; else return x;
}

LL C( LL n, LL m ) {
    return Fact[ m ] * Inv[ n ] % Mod * Inv[ m - n ] % Mod;
}

int main() {
    Fact[ 0 ] = 1;
    for( LL i = 1; i <= 4000; ++i ) Fact[ i ] = ( Fact[ i - 1 ] * i ) % Mod;
    Inv[ 4000 ] = inv( Fact[ 4000 ] );
    for( LL i = 3999; i >= 0; --i ) Inv[ i ] = ( Inv[ i + 1 ] * ( i + 1 ) ) % Mod;
    scanf( "%lld", &n );
    for( LL i = 1; i <= n; ++i ) scanf( "%lld%lld", &A[ i ], &B[ i ] );
    for( LL i = 1; i <= n; ++i )
        F[ 2000 - A[ i ] ][ 2000 - B[ i ] ]++;
    for( LL i = 0; i <= 4000; ++i )
        for( LL j = 0; j <= 4000; ++j ) 
            F[ i ][ j ] = ( F[ i - 1 ][ j ] + F[ i ][ j - 1 ] + F[ i ][ j ] ) % Mod;
    for( LL i = 1; i <= n; ++i ) 
        Ans = ( Ans + F[ 2000 + A[ i ] ][ 2000 + B[ i ] ] ) % Mod;
    for( LL i = 1;i <= n; ++i ) 
        Ans = ( ( Ans - C( 2 * A[ i ], 2 * A[ i ] + 2 * B[ i ] ) ) % Mod + Mod ) % Mod;
    Ans = Ans * inv( 2 ) % Mod;
    printf( "%lld\n", Ans );
    return 0;
}

