Vec gauss_jordan(const MAT& A,const Vec&b){
	int n  = A.size();
	MAT B (n,Vec(n+1));
	rep(i,n)rep(j,n)B[i][j]=A[i][j];
	rep(i,n)B[i][n]=b[i];

	rep(i,n){
		int pivot = i;
		for(int j= i;j<n;j++){
			if(abs(B[j][i])>abs(B[pivot][i]))pivot = j;
		}

		swap(B[i],B[pivot]);
		if(abs(B[i][i])<eps)return Vec();
    //B_i_i成分が0であるつまり階数が
		for(int j =i +1 ;j<=n;j++)B[i][j]/=B[i][i];
		rep(j,n){
			if(i!=j)
				for(int k = i+1;k<=n;k++){
					B[j][k] -=B[j][i]*B[i][k];
				}
		}
	}
	Vec x(n);
	for(int i =0;i<n;i++){
		x[i]= B[i][n];
	}
	return x;


