double det(const MAT& A){
	int n = A.size();
	MAT B (n,Vec(n));
	rep(i,n)rep(j,n)B[i][j]=A[i][j];
	double ans = 1;
	rep(i,n){
		int pivot = i;
		for(int j=i;j<n;j++){
			if(abs(B[j][i])>abs(B[pivot][i]))pivot = j;
		}
		if(i!=pivot)ans *= -1;
		swap(B[i],B[pivot]);
		if(abs(B[i][i])<eps)
			return 0;
		ans *= B[i][i];
		for(int j =i +1 ;j<n;j++)B[i][j]/=B[i][i];
		rep(j,n){
			if(i!=j)
				for(int k = i+1;k<n;k++){
					B[j][k] -=B[j][i]*B[i][k];
				}
		}
	}
	return ans;

}
int  rank(const MAT& A){
	int n = A.size();
