		int pivot = i;
		for(int j=i;j<n;j++){
			if(abs(B[j][i])>abs(B[pivot][i]))pivot = j;
		}
		swap(B[i],B[pivot]);
		if(abs(B[i][i])<eps)return i;
		for(int j =i +1 ;j<n;j++)B[i][j]/=B[i][i];
