	rep(i,n)rep(j,n)rep(k,n){
		C[i][j]+=A[i][k]*B[k][j] %m;
		C[i][j]%=m;
	}
	return C;
}
mat pow_mat(mat A,lli p,lli mod){
	int n= A.size();
	mat B = mat(n,vec(n));
	while(p>0){
		if(p&1){
			B=mul_mat_mod(A,B,mod);
		}
		A = mul_mat_mod(A,A,mod);
		p>>=1;
	}
	return B;
}
lli comb(lli a,lli b ){
	lli ans =1;
	rep(i,b){
		ans = ans %MOD* (a-i)%MOD*inv(b-i)%MOD;
	}
	return ans ;
}


