void generate_combination() {
	for (std::uint64_t o = 0; o < MaxOfOniku; o++) {
		combination.at(o) = 1;
	}
	for (std::uint64_t t = 0; t < MaxOfYasai; t++) {
		combination.at(t * MaxOfOniku) = 1;
	}
	for (std::uint64_t t = 1; t < MaxOfYasai; t++) {
		for (std::uint64_t o = 1; o < MaxOfOniku; o++) {
			combination.at(t * MaxOfOniku + o) = (combination.at(t * MaxOfOniku + o - 1)
												+ combination.at(t * MaxOfOniku + o - MaxOfOniku)
												) % mod;
		}
	}
}

