void chuli()
{
	for(int i=2;i<=N;i++)
	{
		if(!vi[i])
		{
			tot++;
			prime[tot]=i;
			minn[i]=tot;
		}
		for(int j=1;j<=tot&&i*prime[j]<=N;j++)
		{
			vi[i*prime[j]]=true;
			minn[i*prime[j]]=j;
			if(i%prime[j]==0)
			break;
		}
	}
}
void co(int num)
{
	memset(cnt,0,sizeof(cnt));
	int x=min(a[num],b[num]),y=max(a[num],b[num]),z;
	for(int i=1;i<=x;i++)
	c[i]=y+i;
	for(int i=2;i<=x;i++)
	{
		z=i;
		while(z>1)
		{
			cnt[minn[z]]++;
			z/=prime[minn[z]];
		}
	}
	for(int i=1;i<=tot;i++)
	{
		if(cnt[i])
		{
			x=c[1]/prime[i];
			if(prime[i]*x<c[1])
			x++;
			z=prime[i]*x-y;
			while(cnt[i])
			{
				while(c[z]%prime[i]==0&&cnt[i])
				{
					c[z]/=prime[i];
					cnt[i]--;
				}
				y+=prime[i];
			}
		}
	}
	x=min(a[num],b[num]);
	step[num]=1;
	for(int i=1;i<=x;i++)
	step[num]=((long long)step[num]*(c[i]%p))%p;
}
void cheng()
{
	int x=p-2,now=2;
	tot=1;
	while(x)
	{
		if(x&1)
			tot=((long long)now*tot)%p;
		x>>=1;
		now=((long long)now*now)%p;
	}
}
