const int Maxn = 200009, Maxc = 2009, Mod = (int)1e9 + 7;
int n, a[Maxn], b[Maxn], fac[Maxc * 2], invFac[Maxc * 2];
int dp[Maxc * 2][Maxc * 2];
inline pair<int, int> getPos(int x, int y) { return make_pair(x + 2000, y + 2000); }

int fpm(int base, int tims) {
	int r = 1;
	while (tims) {
		if (tims & 1) r = 1ll * r * base % Mod;
		base = 1ll * base * base % Mod;
		tims >>= 1;
	}
	return r;
}

void init() {
	n = read();
	rep (i, 1, n) a[i] = read(), b[i] = read();
	rep (i, 1, n) {
		pair <int, int> s = getPos(-a[i], -b[i]);
		dp[s.first][s.second] += 1;
	}

	fac[0] = 1;
	rep (i, 1, 2 * Maxc - 2) fac[i] = fac[i - 1] * 1ll * i % Mod;
	invFac[2 * Maxc - 2] = fpm(fac[2 * Maxc - 2], Mod - 2);
	drep (i, 2 * Maxc - 3, 0) invFac[i] = invFac[i + 1] * (i + 1ll) % Mod;
}

int C(int n, int m) {
	if (n < m) return 0;
	return fac[n] * 1ll * invFac[m] % Mod * invFac[n - m] % Mod;
}

void solve() {
	rep (i, 0, 4000)
		rep (j, 0, 4000)
			dp[i][j] += ((i > 0 ? dp[i - 1][j] : 0) + (j > 0 ? dp[i][j - 1] : 0)) % Mod;

