ll fac[N], inv[N];

ll Power(ll p, ll q) {
	ll cur = 1;
	while (q) {
		if (q & 1) cur = cur * p % Mod;
		p = p * p % Mod;
		q >>= 1;
	}
	return cur;
}

void Pre() {
	fac[0] = 1; for (int i = 1; i <= N - 10; ++ i) fac[i] = fac[i - 1] * i % Mod;
	inv[N - 10] = Power(fac[N - 10], Mod - 2);
	for (int i = N - 11; i >= 0; -- i) inv[i] = inv[i + 1] * (i + 1) % Mod;
}

ll Calc(int x, int y) {
	return fac[x] * inv[y] % Mod * inv[x - y] % Mod;
}

