ll pw(ll a, ll b)
{
	if (!b) return 1ll;
	ll x = pw(a, b / 2);
	x = (x * x) % mod;
	if (b % 2) x = (x * a) % mod;
	return x;
}

ll sel(ll a, ll b)
{
	ll x = 1ll;
	x = (x * fac[a]) % mod;
	x = (x * pw(fac[b], mod - 2)) % mod;
	x = (x * pw(fac[a-b], mod - 2)) % mod;
	return x;
}




