ll powmod(ll a, ll k){
    ll ap=a, ans=1;
    while(k>0){
        if(k%2==1){
            ans*=ap;
            ans%=MOD;
        }
        ap=ap*ap;
        ap%=MOD;
        k/=2;
    }
    return ans;
}
ll inv(ll a){
	return powmod(a, MOD-2);
}
ll f[8001];
ll invf[8001];
void fact(){
  f[0]=1;
  for(ll i=1; i<=8000; i++) f[i]=f[i-1]*i%MOD;
  invf[8000]=inv(f[8000]);
  for(ll i=7999; i>=0; i--) invf[i]=invf[i+1]*(i+1)%MOD;
}
ll cb[4001][4001];
ll comb(int a, int b){
  return f[a]*invf[b]%MOD*invf[a-b]%MOD;
}
void combcalc(){
  for(int i=0; i<=4000; i++){
    for(int j=0; j<=i; j++){
      cb[i][j]=comb(i, j);
