typedef long long ll;

ll MOD = 1e9 + 7;

ll add(ll a, ll b) {
    ll res = a + b;
    if (res >= MOD) {
        res -= MOD;
    }
    return res;
}

ll sub(ll a, ll b) {
    ll res = a - b;
    if (res < 0) {
        res += MOD;
    }
    return res;
}

ll mul(ll a, ll b) {
    return (a * b) % MOD;
}

ll rev(ll a, ll m = MOD) {
    if (a == 1) {
        return 1;
    }
    return (1 - rev(m % a, a) * m) / a + m;
}

ll divv(ll a, ll b) {
    return (a * rev(b)) % MOD;
}

