		debug() << imie(x) imie(y) imie(vec[i]);
		answer = (answer + (ll) vec[i] % mod * bin(x + y, x)) % mod;
	}
	for(pair<int,int> p : in) {
		//~ cerr << dp[2*(p.first+p.second)][2*p.first] << "\n";
		answer = (answer + mod - bin(2*(p.first+p.second), 2 * p.first)) % mod;
	}
	printf("%d\n", my_div(answer, 2));
}

