const int MOD=1e9+7;
const int maxn=2e5+5;
const int K=2e3+3;
int C[K][K];
int fac[K<<2],inv[K<<2],ifac[K<<2];
void predo()
{
    REP(i,K) C[i][0]=1;
    REP1(i,1,K-1) REP1(j,1,i)
        C[i][j]=(C[i-1][j-1]+C[i-1][j])%MOD;

    fac[0]=1;
    REP1(i,1,4*K-1) fac[i]=1LL*fac[i-1]*i%MOD;
    inv[1]=1;
    REP1(i,2,4*K-1) inv[i]=1LL*inv[MOD%i]*(MOD-MOD/i)%MOD;
    ifac[0]=1;
    REP1(i,1,4*K-1) ifac[i]=1LL*ifac[i-1]*inv[i]%MOD;
}
int n,a[maxn],b[maxn];
void read()
{
    RI(n);
    vector<pii> v(n);
    REP(i,n) RI(v[i].F,v[i].S);
    sort(ALL(v));
    REP(i,n) a[i]=v[i].F,b[i]=v[i].S;
}
ll _[K*4],*dp=_+K*2;
void build()
{
    REP(i,n) a[i]--;
    for(int k=a[n-1];k>=0;k--)
    {
        int up=lower_bound(a,a+n,k)-a;
        REP1(i,up,n-1) dp[b[i]-k]+=C[a[i]][a[i]-k];
        for(int i=K;i>=-K;i--) dp[i]=(dp[i]+dp[i+1])%MOD;
    }
    REP(i,n) a[i]++;
}
void sol()
{
    ll ans=0,sum=0;
    REP1(i,-K,K)
    {
        sum=(sum+dp[-i])%MOD;
        ans=(ans+sum*dp[i])%MOD;
    }

    REP(i,n)
    {
        ll cur=fac[a[i]+b[i]+a[i]+b[i]];
        cur=cur*ifac[a[i]<<1]%MOD;
        cur=cur*ifac[b[i]<<1]%MOD;
        ans=(ans-cur)%MOD;
    }

    ans=ans*inv[2]%MOD;
    if(ans<0) ans+=MOD;
    PL(ans);
}
int main()
{
    predo();
    read();
    build();    
    sol();
    return 0;
}




































