    C operator+(const C& c)const{return {x+c.x,y+c.y};}
    C operator-(const C& c)const{return {x-c.x,y-c.y};}
    C operator*(const C& c)const{return {x*c.x-y*c.y,x*c.y+y*c.x};}
};
