    if (a >= mod)
        a -= mod;
}
void sub (int &a, int b)
{
    a -= b;
    if (a < 0)
        a += mod;
}
int mult (int a, int b)
{
    return (ll)a * b % mod;
}

void solve (int n)
{
    vi a(n), b(n);
    for (int i = 0; i < n; i++)
        cin >> a[i] >> b[i];

    const int bound = 2 * *max_element(ALL(a)) + 2 * *max_element(ALL(b)) + 2;
    vi fact(bound, 1), invfact(bound, 1), inv(bound, 1);
    for (int i = 2; i < bound; i++)
    {
        fact[i] = mult(fact[i - 1], i);
        inv[i] = mult(inv[mod % i], mod / i);
        inv[i] = mod - inv[i];
        assert(mult(inv[i], i) == 1);
        invfact[i] = mult(invfact[i - 1], inv[i]);
        assert(mult(fact[i], invfact[i]) == 1);
    }

    const int D = max(*max_element(ALL(a)), *max_element(ALL(b)));
    const int C = 2 * D + 5;
    int dp[C + 1][C + 1];
    memset(dp, 0, sizeof dp);
    int cnt_f[C][C];
    memset(cnt_f, 0, sizeof cnt_f);

    for (int i = 0; i < n; i++)
    {
        dp[D - a[i]][D - b[i]]++;
        cnt_f[D + a[i]][D + b[i]]++;
    }

    int ans = 0;

    for (int i = 0; i < C; i++)
    for (int j = 0; j < C; j++)
    {
        add(ans, mult(cnt_f[i][j], dp[i][j]));
        add(dp[i + 1][j], dp[i][j]);
        add(dp[i][j + 1], dp[i][j]);
    }

//    cerr << ans << endl;

    for (int i = 0; i < n; i++)
    {
        int from = 2 * (a[i] + b[i]);
        int what = 2 * a[i];
        int cur = mult(fact[from], invfact[what]);
        cur = mult(cur, invfact[from - what]);
        sub(ans, cur);
    }

 //   cerr << ans << endl;

    const int inv2 = (mod + 1) / 2;
    ans = mult(ans, inv2);
    cout << ans << endl;
}

