void dft(vector<complex<double>>& f, bool inv) {
	ll d = f.size();
	if (d == 1) { return; }

	bool b = 1;
	rep(i, d) { if (f[i] != 0.0) { b = 0; } }
	if (b) { return; }

	vector<complex<double>> ga, gb;

	rep(i, d / 2) {
		ga.push_back(f[2 * i]);
		gb.push_back(f[2 * i + 1]);
	}

	dft(ga, inv);
	dft(gb, inv);

	complex<double> now, zeta;
	now = 1;
	if (inv) { zeta = polar(1.0, 2.0 * acos(-1) / (double)d); }
	else { zeta = polar(1.0, -2.0 * acos(-1) / (double)d); }

	rep(i, d) {
		f[i] = ga[i % (d / 2)] + now * gb[i % (d / 2)];
		now *= zeta;
	}
}

template<typename T>
vector<double> multiply(vector<T> f, vector<T> g) {
	vector<complex<double>> nf, ng;
	ll sz = 1;
	while (sz < f.size() + g.size())sz *= 2;
	nf.assign(sz, 0); ng.assign(sz, 0);

	rep(i, f.size()) { nf[i] = f[i]; }
	rep(i, g.size()) { ng[i] = g[i]; }

	dft(nf, 1);
	dft(ng, 1);
	rep(i, sz)nf[i] *= ng[i];
	dft(nf, 0);
	vector<double> res;
	rep(i, sz)res.push_back(nf[i].real() / (double)sz);
	return res;
}

