#include <bits/stdc++.h>
using namespace std;

typedef long long int ll;
const int MAX_N = 2000;
const ll MOD = 1000000007;

int cnt[MAX_N + 1][MAX_N + 1];
ll frac[MAX_N * 2 + 1], inv[MAX_N * 2 + 1];

ll power(ll a, int n) {
    ll ans = 1;
    while (n > 0) {
        if (n % 2 == 1)
            ans = (ans * a) % MOD;
        a = a * a % MOD;
        n /= 2;
    }
    return ans;
}
inline ll binom(int a, int b) {
    return frac[a + b] * inv[a] % MOD * inv[b] % MOD;
}

int main() {
    frac[0] = inv[0] = 1;
    for (int i = 1; i <= 2 * MAX_N; i++)
        frac[i] = (frac[i - 1] * i) % MOD, inv[i] = (inv[i - 1] * power(i, MOD - 2)) % MOD;
    for (int i = 0; i <= MAX_N; i++)
        for (int j = 0; j <= MAX_N; j++)
            cnt[i][j] = 0;

    ll ans = 0;
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int a, b;
        cin >> a >> b;
        ans = (ans - binom(2 * a, 2 * b) + MOD) % MOD;
        cnt[a][b]++;
    }
    for (int i = MAX_N; i > 0; i--)
        for (int j = MAX_N; j > 0; j--) {
            if (cnt[i][j] == 0)
                continue;
            ll tmp = binom(2 * i, 2 * j) - (binom(2 * (i - 1), 2 * j) + 2 * binom(2 * i - 1, 2 * j - 1) + binom(2 * i, 2 * (j - 1))) % MOD;
            tmp = (tmp + MOD) % MOD;
            ans = (ans + tmp * cnt[i][j]) % MOD;
            cnt[i - 1][j] = (cnt[i - 1][j] + cnt[i][j]) % MOD;
            cnt[i][j - 1] = (cnt[i][j - 1] + cnt[i][j]) % MOD;
        }
    ll mycnt = 0;
    for (int i = 1; i <= MAX_N; i++)
        mycnt = (mycnt + cnt[i][0]) % MOD;
    ans = (ans + mycnt * mycnt) % MOD;
    mycnt = 0;
    for (int j = 1; j <= MAX_N; j++)
        mycnt = (mycnt + cnt[0][j]) % MOD;
    ans = (ans + mycnt * mycnt) % MOD;
    for (int i = 1; i <= MAX_N; i++)
        for (int j = 1; j <= MAX_N; j++)
            ans = (ans + 2 * cnt[i][0] * cnt[0][j] % MOD * binom(i, j)) % MOD;
    ans = ans * power(2, MOD - 2) % MOD;
    cout << ans << "\n";
}

