typedef long long LL;
const int Mod = 1000000007, Inv2 = (Mod + 1) / 2;
const int MN = 200005, C = 2000, O = C + 1, MS = O + C + 1;

inline int qPow(int b, int e) {
	int a = 1;
	for (; e; e >>= 1, b = (LL)b * b % Mod)
		if (e & 1) a = (LL)a * b % Mod;
	return a;
}

int N, A[MN], B[MN];
int Fac[MS * 2], iFac[MS * 2];
int S[MS][MS];
int Ans;

int main() {
	scanf("%d", &N);
	Fac[0] = 1;
	for (int i = 1; i <= 4 * C; ++i) Fac[i] = (LL)Fac[i - 1] * i % Mod;
	iFac[4 * C] = qPow(Fac[4 * C], Mod - 2);
	for (int i = 4 * C; i >= 1; --i) iFac[i - 1] = (LL)iFac[i] * i % Mod;
	for (int i = 1; i <= N; ++i) {
		scanf("%d%d", &A[i], &B[i]);
		++S[O - A[i]][O - B[i]];
		Ans = (Ans - (LL)Fac[2 * (A[i] + B[i])] * iFac[2 * A[i]] % Mod * iFac[2 * B[i]]) % Mod;
	}
	for (int i = O - C; i <= O + C; ++i)
		for (int j = O - C; j <= O + C; ++j)
			S[i][j] = (S[i][j] + S[i - 1][j] + S[i][j - 1]) % Mod;
	for (int i = 1; i <= N; ++i)
		Ans = (Ans + S[O + A[i]][O + B[i]]) % Mod;
	Ans = (LL)Ans * Inv2 % Mod;
	printf("%d\n", (Ans + Mod) % Mod);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 10, M = 2e3 + 10, mod = 1e9 + 7;

namespace {
  inline int add(int x, int y) { return (x += y) >= mod ? x - mod : x; }
  inline int sub(int x, int y) { return (x -= y) < 0 ? x + mod : x; }
  inline int mul(int x, int y) { return 1LL * x * y % mod; }
}

int n, f[M << 1 | 1][M << 1 | 1], a[N], b[N], fac[N], ifac[N], inv[N];

int binom(int x, int y) {
  if(x < y) {
    return 0;
  }
  return mul(fac[x], mul(ifac[y], ifac[x - y]));
}

int main(void) {
  scanf("%d", &n);
  for(int i = 1; i <= n; i++) {
    scanf("%d%d", &a[i], &b[i]);
    f[M - a[i]][M - b[i]]++;
  }
  for(int i = 1; i < M << 1; i++) {
    for(int j = 1; j < M << 1; j++) {
      f[i][j] = add(f[i][j], add(f[i - 1][j], f[i][j - 1]));
    }
  }

  fac[0] = fac[1] = ifac[0] = ifac[1] = inv[1] = 1;
  for(int i = 2; i < M << 4; i++) {
    fac[i] = mul(fac[i - 1], i);
    inv[i] = mul(mod - mod / i, inv[mod % i]);
    ifac[i] = mul(ifac[i - 1], inv[i]);
  }

  int ans = 0;
  for(int i = 1; i <= n; i++) {
    ans = sub(ans, binom(2 * (a[i] + b[i]), 2 * a[i]));
  }
  for(int i = 1; i <= n; i++) {
    ans = add(ans, f[M + a[i]][M + b[i]]);
  }
  ans = mul(ans, mod + 1 >> 1);
  cout << ans << endl;
  return 0;
}

