        na[i].resize(sz),nb[i].resize(sz);

        for (j=0; j<sz; j++)
            na[i][j]=a[i][j],nb[i][j]=b[i][j];
    }

    fft2d(na,0); fft2d(nb,0);

    for (i=0; i<sz; i++)
        for (j=0; j<sz; j++)
            na[i][j]*=nb[i][j];

    fft2d(na,1);

    res.resize(sz);
    for (i=0; i<sz; i++){
        res[i].resize(sz);
        for (j=0; j<sz; j++)
            res[i][j]=round(na[i][j].real());
    }

    return res;
}

