}

int sub(int a, int b) {
  return (a -= b) < 0 ? a + Mod : a;
}

int mul(int a, int b) {
  return 1ll * a * b % Mod;
}

int fast_pow(int a, int b) {
  int res = 1;
  for (; b; b >>= 1, a = mul(a, a)) {
    if (b & 1) {
      res = mul(res, a);
    }
  }
  return res;
}

int C(int a, int b) {
  return mul(fac[a], mul(inv[b], inv[a - b]));
}

