  for (int i = 1; i <= n; i++) {
    fac[i] = mul(fac[i - 1], i);
  }
  inv[n] = fast_pow(fac[n], Mod - 2);
  for (int i = n - 1; i >= 1; i--) {
    inv[i] = mul(inv[i + 1], i + 1);
  }
}

