int comb[4 * N][2 * N];

void precalc_comb() {
    for (int i = 0; i < 4 * N; ++ i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i && j < 2 * N; ++ j) {
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            if (comb[i][j] >= MOD)
                comb[i][j] -= MOD;
        }
    }
}

