		C[i][0] = C[i][i] = 1;
	for (int i = 1; i < MAXS << 1; i++)
		for (int j = 1; j < i; j++)
			C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
}

int pw(int a, int b) {
	int res = 1;
	while (b) {
		if (b & 1)
			res = (1LL * a * res) % mod;
		a = (1LL * a * a) % mod;
		b >>= 1;
	}
	return res;
}

