int mul(int x , int y) {
        return 1LL * x * y % MOD ;
}

int sum(int x , int y) {
        x += y;
        if (x < 0)
                x += MOD;
        else if (x >= MOD)
                x -= MOD;
        return x;
}

int pw(ll x , ll y) {
        ll res = 1 ;
        while (y) {
                if (y & 1) res = mul(res, x);
                x = mul(x, x);
                y >>= 1 ;
        }
        return res;
}

