                FactRev[i] = pw(Fact[i] , MOD - 2) ;
}

int C(int x , int y) {
        if (y > x || y < 0)
                return 0 ;
        return mul((mul(Fact[x] , FactRev[y])) , FactRev[x - y]) ;
}

