ll factorial(int const& n, int const& k){
  if(factdb[n][k]!=0) return factdb[n][k];
  double result=1;
  for(int i=0;i<k;i++){
    result *= (double)(n-i)/(k-i);
  }
  return factdb[n][k] = (ll)result;
}

