// Cooley–Tukey FFT algorithm O(N log N) 配列ver
void fft(complex<double> *a, int n, bool inverse = false) {
  int h = 0;  // h = log_2(n)
  for (int i = 0; 1 << i < n; i++) h++;
  // バタフライ演算用の配置入れ替え
  for (int i = 0; i < n; i++) {
    int j = 0;
    for (int k = 0; k < h; k++) j |= (i >> k & 1) << (h - 1 - k);
    if (i < j) swap(a[i], a[j]);
  }
  // バタフライ演算
  for (int b = 1; b < n; b *= 2) {
    // 第 log_2(b) + 1 段
    // ブロックサイズ = b * 2
    for (int j = 0; j < b; j++) {
      // ブロック内 j 個目
      // 重み w = (1 の原始 2b 乗根の j 乗)
      complex<double> w = polar(1.0, (2 * M_PI) / (2 * b) * j * (inverse ? 1 : -1));
      for (int k = 0; k < n; k += b * 2) {
        // k を先頭とするブロック
        complex<double> s = a[j + k];          // 前
        complex<double> t = a[j + k + b] * w;  // 後
        a[j + k] = s + t;                      // 前の更新
        a[j + k + b] = s - t;                  // 後の更新
      }
    }
  }
  // 逆変換時にサイズで割る調整
  if (inverse)
    for (int i = 0; i < n; i++) a[i] /= n;
}
// Cooley–Tukey FFT algorithm O(N log N)
void fft(double *a, complex<double> *a_complex, int n, bool inverse = false) {
  for (int i = 0; i < n; i++) a_complex[i] = complex<double>(a[i], 0);
  fft(a_complex, n, inverse);
}

// FFT による畳み込み O(N log N)
complex<double> fftA[MAXSIZE];
complex<double> fftB[MAXSIZE];

void convolve(double *a, int m, double *b, int n) {
  int s = m + n - 1;  // 畳み込み結果のサイズ
  int t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  fft(a, fftA, t);
  fft(b, fftB, t);
  for (int i = 0; i < t; i++) {
    fftA[i] *= fftB[i];  // 畳み込み結果の FFT 結果を得る
  }
  fft(fftA, t, true);                                 // IFFT で畳み込み結果を得る
  for (int i = 0; i < s; i++) a[i] = fftA[i].real();  // 実部が答え
}

void convolve2(double *a, int n) {
  int s = n + n - 1;  // 畳み込み結果のサイズ
  int t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  fft(a, fftA, t);
  //  PRINTARR(fftA, fftA + t);
  for (int i = 0; i < t; i++) {
    fftA[i] *= fftA[i];  // 畳み込み結果の FFT 結果を得る
  }
  fft(fftA, t, true);                                 // IFFT で畳み込み結果を得る
  for (int i = 0; i < s; i++) a[i] = fftA[i].real();  // 実部が答え*/
}

