	for(int i = 0; i < MAXM; i++)
		for(int j = 0; j < MAXM; j++)
		{
			if(i) C[i][j] += C[i - 1][j];
			if(C[i][j] >= mod) C[i][j] -= mod;
			if(j) C[i][j] += C[i][j - 1];
			if(C[i][j] >= mod) C[i][j] -= mod;
		}

	int answer = 0;
	for(int i = 0; i < n; i++)
	{
		answer = answer + mod - C[2 * b[i]][2 * a[i]];
