	rep( i, 1, n ) Ans += dp[m + A[i]][m + B[i]], Ans %= P ;
	rep( i, 1, n ) Ans -= C( 2 * A[i], ( A[i] + B[i] ) * 2 ), Ans = ( Ans + P ) % P ;
