namespace WoZhenTaMaShiGeLaJi
{
	const int N=2050,MOD=1000000007;
	template<typename T>inline void check_max(T a,T &b){if(a>b)b=a;}
	template<typename T>inline void inc(T a,T &b){b=((b+a)%MOD+MOD)%MOD;}
	typedef long long ll;
	ll qpow(ll a,ll b){ll c=1;for(;b;b>>=1,a=a*a%MOD)if(b&1)c=c*a%MOD;return c;}
	ll inv(ll x){return qpow(x,MOD-2);}
	ll t1[N*2][N*2],*t2[N*2],**f;
	ll fact[N*4];
	int A[N],B[N];
	int n,mx,my;
	ll ans;
	ll C(int a,int b){return fact[a]*inv(fact[b])%MOD*inv(fact[a-b])%MOD;}
	void initialize()
	{
		for(int i=0;i<N*2;i++)t2[i]=t1[i]+N;f=t2+N;
		fact[0]=1;for(int i=1;i<N*4;i++)fact[i]=fact[i-1]*i%MOD;

		scanf("%d",&n);
		mx=my=0;
		for(int i=1;i<=n;i++)
		{
			scanf("%d%d",A+i,B+i);
			f[-A[i]][-B[i]]++;
			check_max(A[i],mx);
			check_max(B[i],my);
		}
	}
	void solve()
	{
		initialize();
		for(int i=-mx;i<=mx;i++)
			for(int j=-my;j<=my;j++)
			{
//				printf("f[%d][%d] = %lld\n",i,j,f[i][j]);
				inc(f[i][j],f[i+1][j]);
				inc(f[i][j],f[i][j+1]);
			}
		ans=0;
		for(int i=1;i<=n;i++)
			inc(f[A[i]][B[i]],ans);
		for(int i=1;i<=n;i++)
			inc(-C(A[i]+B[i]+A[i]+B[i],A[i]+A[i]),ans);
		ans=(ans*inv(2)%MOD+MOD)%MOD;
		printf("%lld\n",ans);
	}
}
int main()
{
