int x[N], y[N], dp[X][X], fact[N], factRev[N], n, ans;

int sum(int a, int b) {
    return ((1LL * a + b) % mod + mod) % mod;
}

int mul(int a, int b) {
    return ((1LL * a * b) % mod + mod) % mod;
}

int pw(int a, int b) {
    int res = 1, tmp = a;
    while (b) {
        if (b & 1)
            res = mul(res, tmp);
        tmp = mul(tmp, tmp);
        b >>= 1;
    }
    return res;
}

int c(int a, int b) {
    return mul(fact[a], mul(factRev[b], factRev[a - b]));
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
