typedef long long ll;


ll getFactorial(const int n) {
	ll result = n;
	for (int i = n-1; i >= 2; i--) {
		result *= i;
	}
	return result;
}


inline ll getCombination(const int a, const int b) {
	return getFactorial(a + b) / getFactorial(a) / getFactorial(b);
}


int main() {

	int N;
	scanf("%d\n", &N);

	vector<int> A, B;
	for (int i = 1; i <= N; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		A.push_back(a);
		B.push_back(b);
	}

	ll result = 0;

	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j < N; j++) {
			result += getCombination(A[i]+A[j], B[i]+B[j]);
		}
	}

	printf("%lld\n", result % MOD);

	return 0;
}

