inline LL nCr(LL n, LL r) {
	return fact[n] * gyaku[n - r]%p * gyaku[r]%p;
}
inline LL twin(LL a1, LL b1, LL a2, LL b2) {
	return nCr(a1 + b1 + a2 + b2, a1 + a2);
}
LL modpow(LL n, LL r) {
	if (r == 0) return 1;
	LL ans = modpow(n*n%p, r / 2);
	if (r % 2) ans *= n;
	return ans % p;
}
LL rev(LL x) {
	return modpow(x, p - 2);
}
LL solve() {
	cin >> N;
	fact[0] = 1;
	gyaku[0] = 1;
	EFOR(i, 1, SIZE2 * 4) fact[i] = fact[i - 1] * i%p;
	EFOR(i, 1, SIZE2*4) gyaku[i] = gyaku[i - 1] * rev(i)%p;
	REP(i, N) {
		cin >> A[i] >> B[i];
		times[A[i]][B[i]]++;
	}
	LL ans = 0;
	RFOR(i,0,SIZE2) {
	//	cout << i << endl;
		REP(a, i) {
			LL b = i - a;
//			if (times[a][b]) cout << a << " " << b << " " << times[a][b] << endl;
			if (a == 0 or b == 0) continue;
			//if (times[a][b]) cout << a << " " << b << endl;
			times[a-1][b] += times[a][b];
			times[a][b - 1] += times[a][b];
			ans -= twin(a, b - 1, a - 1, b)*times[a][b]%p;
			ans += p;
			times[a][b] = 0;
			ans %= p;
		}
	}
	LL ansc = 0;
	REP(i, SIZE2) REP(j, SIZE2) {
		if (i == j) continue;
		LL resa = twin(i, 0, j, 0);
		LL resb = twin(i, 0, 0, j);
		ansc += resa*times[i][0]%p*times[j][0]%p;
		ansc += resb*times[i][0]%p*times[0][j]%p;
		ansc += resb*times[0][i]%p*times[j][0]%p;
		ansc += resa*times[0][i]%p*times[0][j]%p;
		ansc %= p;
	}
	ans += gyaku[2] % p*ansc;
//	cout << "OK" << endl;
	REP(i, SIZE2){
		ans += gyaku[2]%p*twin(i, 0, i, 0) % p*times[i][0] % p*(times[i][0]-1) % p;
		ans += gyaku[2] % p*twin(0, i, 0, i) % p*times[0][i] % p*(times[0][i]-1) % p;
		ans += gyaku[2] % p*twin(i, 0, 0, i) % p*times[i][0] % p*(times[0][i]) % p;
		ans += gyaku[2] % p*twin(0,i, i,0) % p*times[0][i] % p*(times[i][0]) % p;

		ans += 2 * p;
		ans %= p;
	}
	cout << ans << endl;
	return 0;
}




