    for (int i = 0; i < 2 * N; ++ i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i && j < N; ++ j) {
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            if (comb[i][j] >= MOD)
                comb[i][j] -= MOD;
        }
    }
}

