const int N = 2 * 100 * 1000 + 10;
const int M = 10;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
pair <int, int> prr[N];
int dp[(M << 1) + 10][(M << 1) + 10];
int C[(M << 2) + 10][(M << 2) + 10];

void input() {
    cin >> n;

    for (int i = 0; i < n; i++)
        cin >> prr[i].X >> prr[i].Y;
    return;
}

long long pw(long long x ,long long y) {
    long long res = 1;
    for (; y; y /= 2, x = (x * x) % MOD)
        if (y & 1)
            res = (res * x) % MOD;
    return res;
}

void PrePros() {
    for (int i = 0; i < 4 * M; i++)
        C[i][0] = 1;

    for (int i = 1; i < 4 * M; i++)
        for (int j = 1; j <= i; j++)
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
    return;
}

void solve() {
    PrePros();

    for (int i = 0; i < n; i++)
        dp[M - prr[i].X][M - prr[i].Y] += 1;

    for (int i = 0; i < 2 * M; i++)
        for (int j = 0; j < 2 * M; j++)
            dp[i][j] = (dp[i][j] + dp[i - 1][j] + dp[i][j - 1]) % MOD;
    return;
}

void output() {
    long long ans = 0;

    for (int i = 0; i < n; i++) {
        ans = (ans + dp[M + prr[i].X][M + prr[i].Y]) % MOD;
        ans = (ans - C[2 * (prr[i].X + prr[i].Y)][2 * prr[i].X] + MOD) % MOD;
    }

    cout << (1LL * ans * pw(2, MOD - 2)) % MOD << endl;
    return;
}

int main() {
    input();
    solve();
    output();
    return 0;
}

