int qpow(int a, int b) {
	int res = 1;
	for (; b; b >>= 1, a = (long long) a * a % MOD)
		if (b & 1) res = (long long) res * a % MOD;
	return res;
}

void init() {
	fra[0] = 1;
	for (int i = 1; i <= 8000; i++) fra[i] = (long long) fra[i - 1] * i % MOD;
	inv[8000] = qpow(fra[8000], MOD - 2);
	for (int i = 7999; i; i--) inv[i] = (long long) inv[i + 1] * (i + 1) % MOD;
}

int C(int n, int m) {
	if (m > n) return 0;
	return (long long)fra[n] * inv[n - m] % MOD * inv[m] % MOD;
}

