const int MOD = 1e9 + 7;
const int N = 8000+50;
const int offset = 2000 + 10;

int quick_inverse(LL n) {
	LL ret = 1;
	int exponent = MOD - 2;
	for (int i = exponent; i; i >>= 1, n = n * n % MOD) {
		if (i & 1) {
			ret = ret * n % MOD;
		}
	}
	return ret;
}

LL invf[N], factor[N];
void get_factorial_inverse(int n) {
	factor[0] = 1;
	for (int i = 1; i <= n; ++i) {
		factor[i] = i * factor[i - 1] % MOD;
	}
	invf[n] = quick_inverse(factor[n]);
	for (int i = n-1; i >= 0; --i) {
		invf[i] = invf[i + 1] * (i + 1) % MOD;
	}
}

int A[N], B[N];

int Map[offset*2+10][offset*2+10];
bool vis[offset*2+10][offset*2+10];

int calc_x(int n)
{
    LL ans = 0;
    int max_range = 0;
    for (int i=1; i<=n; i++)
    {
        Map[offset + A[i]][offset + B[i]]++;
        Map[offset - A[i]][offset - B[i]]++;
        max_range = max(max_range, A[i]);
        max_range = max(max_range, B[i]);
    }
    queue<pii> q;
    q.push(pii(offset + max_range, offset + max_range));
    vis[offset + max_range][offset + max_range] = true;
    while(!q.empty())
    {
        pii node = q.front(); q.pop();
        int x = node.first, y = node.second;
        if (x < offset && y < offset && Map[x][y])
        {
            int times = Map[x][y];
            Map[x][y] = (Map[x+1][y] + Map[x][y+1]) % MOD;
            ans += (times * Map[x][y]) % MOD;
        }
        else
        {
            Map[x][y] += Map[x+1][y] + Map[x][y+1];
            Map[x][y] %= MOD;
        }
        if (x > offset - max_range && y > 0 && !vis[x-1][y])
            q.push(pii(x-1,y)), vis[x-1][y] = true;
        if (y > offset - max_range && x > 0 && !vis[x][y-1])
            q.push(pii(x,y-1)), vis[x][y-1] = true;
    }
    return ans;
}

int f(int x, int y)
{
    return (((factor[x+y] * invf[x]) % MOD) * invf[y]) % MOD;
}

int calc_t(int n)
{
    LL ans = 0;
    for (int i=1; i<=n; i++)
        ans = (ans + f(2*A[i], 2*B[i])) % MOD;
    return ans;
}

