    for (int i=1; i<=n; i++)
    {
        scanf("%d%d", A+i, B+i);
    }
    LL ans = 0;
    ans += calc_x(n);
    ans -= calc_t(n);
    ans = (ans + MOD) % MOD;
    ans *= invf[2];
    ans %= MOD;
    printf("%d", (int)ans);
}

