        cnt[a[i] * BASE + b[i]].b += 1;
    }
    //cerr << 1.0 * clock() / CLOCKS_PER_SEC << endl;
    fft(cnt, SZ, false);
    for (int i = 0; i < SZ; ++i) {
        cnt[i] = cnt[i] * cnt[i];
    }
    fft(cnt, SZ, true);
    //cerr << 1.0 * clock() / CLOCKS_PER_SEC << endl;
