// Cooley–Tukey FFT algorithm O(N log N) 配列ver
void fft(double *a0, double *a1, int n, bool inverse = false) {
  int h = 0;  // h = log_2(n)
  for (int i = 0; 1 << i < n; i++) h++;
  // バタフライ演算用の配置入れ替え
  for (int i = 0; i < n; i++) {
    int j = 0;
    for (int k = 0; k < h; k++) j |= (i >> k & 1) << (h - 1 - k);
    if (i < j) {
      swap(a0[i], a0[j]);
      swap(a1[i], a1[j]);
    }
  }
  // バタフライ演算
  for (int b = 1; b < n; b *= 2) {
    // 第 log_2(b) + 1 段
    // ブロックサイズ = b * 2
    for (int j = 0; j < b; j++) {
      // ブロック内 j 個目
      // 重み w = (1 の原始 2b 乗根の j 乗)
      double theta = (2 * M_PI) / (2 * b) * j * (inverse ? 1 : -1);
      double w0 = cos(theta);
      double w1 = sin(theta);

      for (int k = 0; k < n; k += b * 2) {
        // k を先頭とするブロック
        double s0 = a0[j + k];                                // 前
        double s1 = a1[j + k];                                // 前
        double t0 = a0[j + k + b] * w0 - a1[j + k + b] * w1;  // 後
        double t1 = a0[j + k + b] * w1 + a1[j + k + b] * w0;  // 後
        a0[j + k] = s0 + t0;                                  // 前の更新
        a1[j + k] = s1 + t1;                                  // 前の更新
        a0[j + k + b] = s0 - t0;                              // 後の更新
        a1[j + k + b] = s1 - t1;                              // 後の更新
      }
    }
  }
  // 逆変換時にサイズで割る調整
  if (inverse)
    for (int i = 0; i < n; i++) a0[i] /= n, a1[i] /= n;
}

// FFT による畳み込み O(N log N)
double fftA[MAXSIZE];
double fftB[MAXSIZE];
void convolve2(double *a, int n) {
  int s = n + n - 1;  // 畳み込み結果のサイズ
  int t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  fill(fftA, fftA + t, 0);
  fft(a, fftA, t);
  //  PRINTARR(fftA, fftA + t);
  for (int i = 0; i < t; i++) {
    double tmpa = a[i];
    a[i] = a[i] * a[i] - fftA[i] * fftA[i];  // 畳み込み結果の FFT 結果を得る
    fftA[i] = 2 * tmpa * fftA[i];
  }
  fft(a, fftA, t, true);  // IFFT で畳み込み結果を得る
}

void convolve(double *a, int m, double *b, int n) {  // a!=b
  if (a == b) {
    convolve2(a, n);
    return;
  }
  int s = m + n - 1;  // 畳み込み結果のサイズ
  int t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  fill(fftA, fftA + t, 0);
  fill(fftB, fftB + t, 0);
  fft(a, fftA, t);
  fft(b, fftB, t);
  for (int i = 0; i < t; i++) {
    double tmpa = a[i];
    a[i] = a[i] * a[i] - fftA[i] * fftA[i];  // 畳み込み結果の FFT 結果を得る
    fftA[i] = tmpa * fftA[i] + tmpa * fftA[i];
  }
  fft(a, fftA, t, true);  // IFFT で畳み込み結果を得る
}

