	if(k < 0)
		k += mod;
	if(k >= mod)
		k -= mod;
	return k;
}

ll pw(int a, int b) {
	if(!b)
		return 1;
	ll ans = pw(a, b / 2);
	ans *= ans;
	ans %= mod;
	if(b & 1)
		ans *= a;
	ans %= mod;
	return ans;
}

int a[N], b[N], dp[L][L];
ll fact[N], rev[N];

void prep() {
	fact[0] = 1;
	for (int i = 1; i < N; i++)
		fact[i] = (fact[i - 1] * i) % mod;
	rev[N - 1] = pw(fact[N - 1], mod - 2);
	for (int i = N - 2; ~i; i--)
		rev[i] = (rev[i + 1] * (i + 1)) % mod;
}

ll c(int n, int k) {
	if(k > n)
		return 0;
	ll ans = fact[n] * rev[k];
	ans %= mod;
	ans *= rev[n - k];
	return ans % mod;
}

