const int MOD = 1000000007;
int n;
int a[200000], b[200000];
int comb[8001][4001];

int hcnt[4001];

typedef long long ll;

ll modpow(ll a, ll n, ll mod) {
	ll ret = 1;
	while (n) {
		if (n % 2)
			ret = (ret * a) % mod;
		a = (a * a) % mod;
		n /= 2;
	}
	return ret;
}

ll modinv(ll r) {
	return modpow(r, MOD - 2, MOD);
}

void proc() {
	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &a[i], &b[i]);
		hcnt[a[i] + b[i]] += 1;
	}

	comb[0][0] = 1;
	for (int i = 1; i <= 8000; ++i) {
		comb[i][0] = 1;
		if (i <= 4000) {
			comb[i][i] = 1;
		}
		for (int j = 1; j < i; ++j) {
			if (j > 4000) {
				break;
			}
			comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
		}
	}

	long long ans = 0;
	for (int i = 0; i < n; ++i) {
		int h0 = a[i] + b[i];

		for (int hj = 1; hj <= 4000; ++hj) {
			if (hcnt[hj] == 0) {
				continue;
			}

			int cnt = hcnt[hj];
			if (hj == h0) {
				--cnt;
			}

			ans = (ans + ((long long)cnt * comb[hj + h0][h0] % MOD)) % MOD;
		}
	}
	printf("%lld", (long long)ans * modinv(2) % MOD);
}

