constexpr uint64_t INF  =   2000000000;
constexpr uint64_t MODULO = 1000000007;

map<uint64_t, uint64_t> pows;
map<uint64_t, uint64_t> mods;

uint64_t pow_mod(uint64_t x, int a)
{
    if(pows.count(x))
        return pows[x];
    uint64_t tmp = x;
    uint64_t ret = 1;
    while(a > 0)
    {
        if(a & 1 == 1)
            ret = (ret * tmp) % MODULO;
        a >>= 1;
        tmp = (tmp * tmp) % MODULO;
    }
    return pows[x] = ret;
}

uint64_t kai(uint64_t n)
{
    if(mods.count(n))
        return mods[n]; 
    uint64_t ret = n;
    RFOR(i, n, 1)
    {
        ret = (ret * i) % MODULO;
    }
    return mods[n] = ret;
}

uint64_t com(uint64_t n, uint64_t k)
{
    uint64_t a = kai(n);
    uint64_t b = kai(k);
    uint64_t c = kai(n+k);
    a = pow_mod(a, MODULO -2);
    b = pow_mod(b, MODULO - 2);


    c = (c * b) % MODULO;
    c = (c * a) % MODULO;
    return c;
}

