i64 get(i64 a, i64 p = MOD - 2)
{
	if (p == 0) return 1;
	i64 tmp = get(a, p / 2);
	tmp = tmp * tmp % MOD;
	if (p % 2 == 1) tmp = tmp * a % MOD;
	return tmp;
}

