int ksm(int x,int y){
	int base=1;
	while(y){
		if(y&1)base=(1ll*base*x)%mod;
		x=(1ll*x*x)%mod;
		y>>=1;
	}return base;
}
int C(int n,int m){
	return (1ll*fac[n]*ksm((1ll*fac[m]*fac[n-m]%mod),mod-2))%mod;
}
