#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 10;
const int M = 2005;
const int mod = 1e9 + 7;

int a[N], b[N];
int dp[M << 1][M << 1], p[N], inv[N];

int mod_pow(int x, int n){
	int ret = 1;
	while (n){
		if (n & 1) ret = 1LL * ret * x % mod;
		x = 1LL * x * x % mod;
		n >>= 1;
	}
	return ret;
}

int C(int x, int y){
	if (x < y) return 0;
	return 1LL * p[x] * inv[y] % mod * inv[x - y] % mod;
}

int main(){
	p[0] = 1; inv[0] = 1;
	for (int i = 1; i < N; i++) p[i] = 1LL * p[i - 1] * i % mod;
	for (int i = 1; i < N; i++) inv[i] = mod_pow(p[i], mod - 2);
	int n, k, ans;
	scanf("%d",&n);
	for (int i = 1; i <= n; i++) scanf("%d %d",&a[i],&b[i]);
	for (int i = 1; i <= n; i++) dp[M - a[i]][M - b[i]]++;
	for (int i = 2; i <= M * 4 - 2; i++){
		for (int j = 1; j < i; j++){
			k = i - j;
			if (max(j, k) > M * 2 - 1) continue;
			if (j > 0){
				dp[j][k] += dp[j - 1][k];
				dp[j][k] %= mod;
			}
			if (k > 0){
				dp[j][k] += dp[j][k - 1];
				dp[j][k] %= mod;
			}
		}
	}
	ans = 0;
	for (int i = 1; i <= n; i++){
		ans += dp[M + a[i]][M + b[i]];
		ans %= mod;
	}
	for (int i = 1; i <= n; i++) ans = (ans - C((a[i] + b[i]) * 2, a[i] * 2) + mod) % mod;
	ans = 1LL * ans * mod_pow(2, mod - 2) % mod;
	printf("%d\n", ans);
	return 0;
}

