typedef long long LL;
typedef vector<LL> VI;
typedef pair<int, LL> PII;

const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL)INF;
const int MOD = 1000 * 1000 * 1000 + 7;

const int MAX = 1000 * 2 + 7;

int F[MAX * 2], RF[MAX * 2];
PII A[200007];


int BP(LL a, int n)
{
    LL res = 1;
    while(n)
    {
        if (n & 1)res = (res * a) % MOD;
        a *= a;
        a %= MOD;
        n >>= 1;
    }
    return res;
}

int C(int a, int b)
{
    LL res = F[a];
    res *= RF[b];
    res %= MOD;
    res *= RF[a-b];
    res %= MOD;
    return res;
}

int DP[2 * MAX][2 * MAX];
int get(int x, int y)
{
    //cout << x << " " << y << endl;
    if (DP[x][y] != -1)
    {
        //if (DP[x][y])cout << x << " " << y << " " << DP[x][y] << endl;
        return DP[x][y];
    }
    LL res = 0;
    if (x)res += get(x-1, y);
    if (y)res += get(x, y-1);
    while(res >= MOD)res -= MOD;
    return DP[x][y] = res;
}


int main()
{
    //cout << f(2, 1) << endl;
    //freopen("input.txt", "r", stdin);
    //ios::sync_with_stdio(false);cin.tie(NULL);
    int n;
    scanf("%d", &n);

   FILL(DP, -1);

    RF[0] = F[0] = 1;
    FOR(i, 1, 2 * MAX)
    {
        F[i] = F[i-1] * 1LL * i % MOD;
        RF[i] = BP(F[i], MOD - 2);
    }

    int tot = 0;
    FOR(i, 0,  n)
    {
        scanf("%d%d", &A[i].first, &A[i].second);
        int aa = -A[i].first + MAX;
        int bb = -A[i].second + MAX;
    //    if (DP[aa][bb] == -1)DP[aa][bb] = 0;
  //      DP[aa][bb]++;
        tot += C(2 * A[i].first + 2 * A[i].second, 2 * A[i].first);
        if (tot >= MOD)tot -= MOD;
        A[i].first = -A[i].first;
        A[i].second = -A[i].second;
    }
    LL ans = 0;

    sort(A, A + n);
    FOR(i, 0, n)
    {
    //   cout << A[i].first << " " << A[i].second << endl;
        int aa = A[i].first + MAX, bb = A[i].second + MAX;
        get(aa, bb);
        DP[aa][bb]++;
        if (DP[aa][bb] >= MOD)
            DP[aa][bb] -= MOD;
   //     cout << DP[A[i].first + MAX][A[i].second + MAX] << endl;
    }

    FOR(i, 0, n)
    {
        ans += get(-A[i].first + MAX, -A[i].second + MAX);
        if (ans >= MOD)ans -= MOD;
    }

    ans -= tot;
    if (ans < 0)ans += MOD;
    ans *= BP(2, MOD-2);
    ans %= MOD;

    printf("%lld\n", ans);
    return 0;
}

