	}
	for(int i = 1; i < maxn; i++) inv[i] = inv[i-1]*1ll*inv[i]%mod;
}
int nck(int n, int k) {
	if(n < 0 || k > n) return 0;
	int t = fact[n]*1ll*inv[k]%mod;
	return t*1ll*inv[n-k]%mod;
}
void add(int &a, int b) {
