//高速べき乗
LL Power(LL N, LL t){	
	N%=MOD;
	LL ret = 1;
	while(t){
		if(t&1) ret*=N, ret%=MOD;
		N*=N;
		N%=MOD;
		t/=2;
	}
	return ret;	
}

//MODの中での割り算(MODは素数であること
//(a/b)mod(MOD=p) を求める
LL mod_frac(LL a,LL b){
	return (a* Power(b,MOD-2))%MOD;
}


LL calc(LL n, LL k) {
	return kaijo[n] * mod_frac(1, kaijo[k]) % MOD * mod_frac(1, kaijo[n-k]) % MOD;

}



