  }

  fft2D();
  for (auto&& v : c) for (auto&& e : v) {
    e = e * e;
  }
  fft2D(true);

  map< pair<int, int>, int > mp;
  for (int i = 0; i < n; ++i) {
    ++mp[{a[i], b[i]}];
  }
  if (mp.size() <= 1e4) {
    Mint res;
    for (const auto & e0 : mp) for (const auto& e1 : mp) {
      res += (lint)e0.second * e1.second * comb(
        e0.first.first + e1.first.first + e0.first.second + e1.first.second,
        e0.first.first + e1.first.first
      );
    }
    for (int i = 0; i < n; ++i) {
      res -= comb(2 * (a[i] + b[i]), 2 * a[i]);
    }
    res /= 2;
    return cout << res << '\n', 0;
  }

  Mint res;
  for (int x = 1; x <= 4000; ++x) for (int y = 1; y <= 4000; ++y) {
    lint cnt = c[x][y].x + 0.5;
    res += cnt * comb(x + y, x);
  }
  for (int i = 0; i < n; ++i) {
    res -= comb(2 * (a[i] + b[i]), 2 * a[i]);
  }
  res /= 2;
  cout << res << '\n';
}

