    }
    P &operator -=(T x){
        if(this->size()==0)this->resize(1,T(0));
        (*dynamic_cast<P*>(this))[0]-=x;
        return (*dynamic_cast<P*>(this));
    }
    P &operator *=(T x){
        for(int i=0;i<(int)this->size();++i){
            (*dynamic_cast<P*>(this))[0]*=x;
        }
        return (*dynamic_cast<P*>(this));
    }
    P &operator /=(T x){
        for(int i=0;i<(int)this->size();++i){
            (*dynamic_cast<P*>(this))[0]/=x;
        }
        return (*dynamic_cast<P*>(this));
    }
    P &operator <<=(int x){
        P ret(x,T(0));
        ret.insert(ret.end(),begin(*dynamic_cast<P*>(this)),end(*dynamic_cast<P*>(this)));
        return (*dynamic_cast<P*>(this))=ret;
    }
    P &operator >>=(int x){
        P ret;
        ret.insert(ret.end(),begin(*dynamic_cast<P*>(this))+x,end(*dynamic_cast<P*>(this)));
        return (*dynamic_cast<P*>(this))=ret;
    }
    P &operator +=(P x){
        if(this->size()<x.size())this->resize(x.size(),T(0));
        for(int i=0;i<(int)x.size();++i){
            (*dynamic_cast<P*>(this))[i]+=x[i];
        }
        return (*dynamic_cast<P*>(this));
    }
    P &operator -=(P x){
        if(this->size()<x.size())this->resize(x.size(),T(0));
        for(int i=0;i<(int)x.size();++i){
            (*dynamic_cast<P*>(this))[i]-=x[i];
        }
        return (*dynamic_cast<P*>(this));
    }
    P &operator *=(P x){
        return (*dynamic_cast<P*>(this))=mul((*dynamic_cast<P*>(this)),x);
    }
    P &operator /=(P x){
        if(this->size()<x.size()) {
            this->clear();
            return (*dynamic_cast<P*>(this));
        }
        const int n=x.size()-this->size()+1;
        return (*dynamic_cast<P*>(this)) = (rev().pre(n)*x.rev().inv(n)).pre(n).rev(n);
    }
    P &operator %=(P x){
        return (*dynamic_cast<P*>(this))-(*dynamic_cast<P*>(this))/x*x;
    }
    P& shrink(){while((*dynamic_cast<P*>(this)).back()==0)(*dynamic_cast<P*>(this)).pop_back();return (*dynamic_cast<P*>(this));}
    P pre(int sz)const{
        return P(begin(*this),begin(*this)+min((int)this->size(),sz));
    }
    P rev(int deg=-1){
        P ret(*dynamic_cast<P*>(this));
        if(deg!=-1)ret.resize(deg,T(0));
        reverse(begin(ret),end(ret));
        return ret;
    }
    P inv(int deg=-1){
        assert((*dynamic_cast<P*>(this))[0]!=T(0));
        const int n=deg==-1?this->size():deg;
        P ret({T(1)/(*this)[0]});
        for(int i=1;i<n;i<<=1){
            ret=ret*(-ret*pre(i<<1)+2).pre(i<<1);
        }
        return ret.pre(n);
    }
    P dot(P x){
        P ret(*dynamic_cast<P*>(this));
        for(int i=0;i<int(min(this->size(),x.size()));++i){
            ret[i]*=x[i];
        }
        return ret;
    }
    P diff(){
        P ret(*dynamic_cast<P*>(this));
        for(int i=0;i<(int)ret.size();i++){
            ret[i]*=i;
        }
        return ret>>1;
    }
    P integral(){
        P ret(*dynamic_cast<P*>(this));
        for(int i=0;i<(int)ret.size();i++){
            ret[i]/=i+1;
        }
        return ret<<1;
    }
    P log(int deg=-1){
        assert((*this)[0]==T(1));
        const int n=deg==-1?this->size():deg;
        return (diff()*inv(n)).pre(n-1).integral();
    }
    P exp(int deg=-1){
        assert((*this)[0]==T(0));
        const int n=deg==-1?this->size():deg;
        P ret({T(1)});
        for(int i=1;i<n;i<<=1){
            ret=ret*(pre(i<<1)+1-ret.log(i<<1)).pre(i<<1);
        }
        return ret.pre(n);
    }
    P sqrt(int deg=-1){
        const int n=deg==-1?this->size():deg;
        if((*this)[0]==T(0)) {
            for(int i=1;i<(int)this->size();i++) {
                if((*this)[i]!=T(0)) {
                    if(i&1)return{};
                    if(n-i/2<=0)break;
                    auto ret=(*this>>i).sqrt(n-i/2)<<(i/2);
                    if((int)ret.size()<n)ret.resize(n,T(0));
                    return ret;
                }
            }
            return P(n,0);
        }
        P ret({T(1)});
        for(int i=1;i<n;i<<=1){
            ret=(ret+pre(i<<1)*ret.inv(i<<1)).pre(i<<1)/T(2);
        }
        return ret.pre(n);
    }
    virtual P mul(P s,P t)=0;
};

template<typename Mint>
struct fps1:FPS_BASE<Mint,fps1<Mint>>{
    class mint_fps;
    using FPS_BASE<Mint,fps1<Mint>>::FPS_BASE;
    using P=fps1<Mint>;
    P mul(P s,P t)override{
        lint n=s.size()+t.size()-1;
        lint h=1;
        while((1<<h)<n)h++;
        vector<mint_fps>a(1<<h,mint_fps(0)),b(1<<h,mint_fps(0));
        for(int i=0;i<(int)s.size();i++){
            a[i]=s[i].value();
        }
        for(int i=0;i<(int)t.size();i++){
            b[i]=t[i].value();
        }
        auto c=ntt(a,h,0);
        auto d=ntt(b,h,0);
        for(int i=0;i<(1<<h);i++){
            c[i]*=d[i];
        }
        auto tmp=ntt(c,h,1);
        P res(n);
        for(int i=0;i<n;i++)res[i]=tmp[i].value();
        return res.pre(n);
    }
    vector<mint_fps> ntt(vector<mint_fps> v,const int& h,const bool& inv){
		int n=v.size(),mask=n-1;
		vector<mint_fps> tmp(n);
        vector<mint_fps> table(n,1);
        mint_fps theta=mint_fps(3).base(h);
        if(inv)theta=theta.inv();
        for(int i=1;i<n;++i)table[i]=table[i-1]*theta;
        for(int j=n>>1,t=h-1;j>=1;j>>=1,--t){
            for(int k=0;k<n;++k){
                int s=k&(j-1);
                int i=k>>t;
                tmp[k]=v[((i<<(t+1))|s)&mask]+table[i*j]*v[((i<<(t+1))|j|s)&mask];
            }
            swap(v,tmp);
        }
        if(inv)for(int i=0;i<n;++i)v[i]/=n;
        return v;
	}
    class mint_fps{
        using u64 = std::uint_fast64_t;
        u64 mods[3]={1224736769,1045430273,1007681537};
        public:
        u64 a[3];
        constexpr mint_fps(const long long x = 0){
            for(int i=0;i<3;i++){
                a[i]=x>=0?x%get_mod():get_mod()-(-x)%get_mod();
            }
        }
        constexpr u64 value() noexcept {
            return garner();
        }
        constexpr mint_fps operator+(const mint_fps rhs)const noexcept{return mint_fps(*this) += rhs;}
        constexpr mint_fps operator-(const mint_fps rhs)const noexcept{return mint_fps(*this)-=rhs;}
        constexpr mint_fps operator*(const mint_fps rhs) const noexcept {return mint_fps(*this) *= rhs;}
        constexpr mint_fps operator/(const mint_fps rhs) const noexcept {return mint_fps(*this) /= rhs;}
        constexpr mint_fps &operator+=(const mint_fps rhs) noexcept {
            for(int i=0;i<3;++i){
                a[i]+=rhs.a[i];
                if (a[i]>=mods[i])a[i]-=mods[i];
            }
            return *this;
        }
        constexpr bool operator==(mint_fps x) noexcept {
            return a==x.a;
        }
        constexpr bool operator!=(mint_fps x) noexcept {
            return a!=x.a;
        }
        constexpr mint_fps &operator-=(const mint_fps rhs) noexcept {
            for(int i=0;i<3;++i){
                a[i]-=rhs.a[i];
                if (a[i]>=mods[i])a[i]-=mods[i];
            }
            return *this;
        }
        constexpr mint_fps &operator*=(const mint_fps rhs) noexcept {
            for(int i=0;i<3;++i){
                a[i]=a[i]*rhs.a[i]%mods[i];
            }
            return *this;
        }
        constexpr mint_fps &operator/=(mint_fps rhs)noexcept{
            for(int i=0;i<3;i++){
                u64 ret =rhs.a[i];
                u64 exp=mods[i]-2;
                while (exp) {
                    if (exp %2) {
                        (a[i]*=ret)%=mods[i];
                    }
                    (ret *= ret)%=mods[i];
                    exp /= 2;
                }
            }
            return *this;
        }
        constexpr mint_fps operator++(int n) noexcept {
            return *this+=1;
        }
        constexpr mint_fps operator--(int n) noexcept {
            return *this-=1;
        }
        constexpr mint_fps base(int h)noexcept{
            for(int i=0;i<3;i++){
                u64 ret =3;
                a[i]=1;
                u64 exp=((mods[i]-1)>>h);
                while (exp) {
                    if (exp %2) {
                        (a[i]*=ret)%=mods[i];
                    }
                    (ret *= ret)%=mods[i];
                    exp /= 2;
                }
            }
            return *this;
        }
        constexpr mint_fps inv(){
            return mint_fps(1)/(*this);
        }
        constexpr static u64 get_mod(){return MOD;}
        constexpr u64 garner(){
            const int sz=3;
            using u64 = long long;
            const u64 mods[4]={1224736769,1045430273,1007681537,get_mod()};
            u64 coeffs[sz+1]={1,1,1,1};
            u64 constants[sz+1]={};
            auto modinv=[](u64 x,u64 mod){
                u64 y=mod-2;
                u64 ret=1;
                while(y>0) {
                    if(y&1)(ret*=x)%=mod;
                    (x*=x)%=mod;
                    y>>=1;
                }
                return ret;
            };
            for(int i=0;i<sz;i++) {
                u64 v=(mods[i]+a[i]-constants[i])%mods[i]*modinv(coeffs[i],mods[i])%mods[i];
                for(int j=i+1;j<sz+1;j++) {
                    constants[j]=(constants[j]+coeffs[j]*v)%mods[j];
                    coeffs[j]=(coeffs[j]*mods[i])%mods[j];
                }
            }
            return constants[3];
        }
    };
};

class mint {
  using u64 = std::uint_fast64_t;
    public:
    u64 a;
    constexpr mint(const long long x = 0)noexcept:a(x>=0?x%get_mod():get_mod()-(-x)%get_mod()){}
    constexpr u64 &value()noexcept{return a;}
    constexpr const u64 &value() const noexcept {return a;}
    constexpr mint operator+(const mint rhs)const noexcept{return mint(*this) += rhs;}
    constexpr mint operator-(const mint rhs)const noexcept{return mint(*this)-=rhs;}
    constexpr mint operator*(const mint rhs) const noexcept {return mint(*this) *= rhs;}
    constexpr mint operator/(const mint rhs) const noexcept {return mint(*this) /= rhs;}
    constexpr mint &operator+=(const mint rhs) noexcept {
        a += rhs.a;
        if (a >= get_mod())a -= get_mod();
        return *this;
    }
    constexpr mint &operator-=(const mint rhs) noexcept {
        if (a<rhs.a)a += get_mod();
        a -= rhs.a;
        return *this;
    }
    constexpr mint &operator*=(const mint rhs) noexcept {
        a = a * rhs.a % get_mod();
        return *this;
    }
    constexpr mint operator++(int n) noexcept {
        a += 1;
        if (a >= get_mod())a -= get_mod();
        return *this;
    }
    constexpr mint operator--(int n) noexcept {
        if (a<1)a += get_mod();
        a -= 1;
        return *this;
    }
    constexpr bool operator==(mint x) noexcept {
        return a==x.a;
    }
    constexpr bool operator!=(mint x) noexcept {
        return a!=x.a;
    }
    constexpr mint &operator/=(mint rhs) noexcept {
        u64 exp=get_mod()-2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }
    constexpr static int root(){
        mint root = 2;
        while(root.pow((get_mod()-1)>>1).a==1)root++;
        return root.a;
    }
    constexpr mint pow(long long n){
        long long x=a;
        mint ret = 1;
        while(n>0) {
            if(n&1)(ret*=x);
            (x*=x)%=get_mod();
            n>>=1;
        }
        return ret;
    }
    constexpr mint inv(){
        return pow(get_mod()-2);
    }
    mint comb(lint b){
        using lint=long long;
        static bool init=1;
        static lint fac[3000001],ifac[3000001];
        if(init){
            init=0;
            fac[0]=1;
            ifac[0]=1;
            auto mod_pow=[&](lint x,lint n){
                lint ans = 1;
                while(n != 0){
                    if(n&1)ans=ans*x%get_mod();
                    x=x*x%get_mod();
                    n=n>>1;
                }
                return ans;
            };
            for(int i=0;i<3000000;i++){
                fac[i+1]=fac[i]*(i+1)%get_mod();
                ifac[i+1]=ifac[i]*mod_pow(i+1, get_mod()-2)%get_mod();
            }
        }
        if(a==0&&b==0)return 1;
        if((lint)a<b||a<0)return 0;
        lint tmp=ifac[a-b]*ifac[b]%get_mod();
        return tmp*fac[a]%get_mod();
    }

    friend ostream& operator<<(ostream& lhs, const mint& rhs) noexcept {
        lhs << rhs.a;
        return lhs;
    }
    friend istream& operator>>(istream& lhs,mint& rhs) noexcept {
        lhs >> rhs.a;
        return lhs;
    }
    constexpr static u64 get_mod(){return MOD;}
};
inline mint fact(lint a){return a?fact(a-1)*a:1;}

