#include <bits/stdc++.h>

class MyComplex
{
public:
  double real;
  double imag;

  MyComplex(){ real = 0, imag = 0; };
  MyComplex(double _real, double _imag){ real = _real; imag = _imag; }
  MyComplex(const MyComplex &my_complex){ real = my_complex.real; imag = my_complex.imag; }

  MyComplex operator+(const MyComplex &my_complex) const{
    return MyComplex(real + my_complex.real, imag + my_complex.imag);
  }
  void operator+=(const MyComplex &my_complex){
    real = real + my_complex.real;
    imag = imag + my_complex.imag;
  }
  MyComplex operator-(const MyComplex &my_complex) const{
    return MyComplex(real - my_complex.real, imag - my_complex.imag);
  }
  void operator-=(const MyComplex &my_complex){
    real = real - my_complex.real;
    imag = imag - my_complex.imag;
  }
  MyComplex operator*(const MyComplex &my_complex) const{
    double r = real * my_complex.real - imag * my_complex.imag;
    double i = real * my_complex.imag + imag * my_complex.real;
    return MyComplex(r, i);
  }
  void operator*=(const MyComplex &my_complex){
    double r = real * my_complex.real - imag * my_complex.imag;
    double i = real * my_complex.imag + imag * my_complex.real;
    real = r;
    imag = i;
  }
  MyComplex operator*(const double &d) const{
    return MyComplex(real * d, imag * d);
  }
  void operator*=(const double &d){
    real *= d;
    imag *= d;
  }
  MyComplex operator/(const double &d) const{
    return MyComplex(real / d, imag / d);
  }
  void operator/=(const double &d){
    real /= d;
    imag /= d;
  }
  friend std::ostream &operator<<(std::ostream &stream, const MyComplex &my_complex){
    stream << "(" << my_complex.real << ", " << my_complex.imag << ")";
    return stream;
  }
};

std::vector<MyComplex> fftMakeOmega(int n)
{
  if(__builtin_popcountll(n) != 1) std::cout << "error : " << __LINE__ << std::endl;
  double pi = acos(-1);
  std::vector<MyComplex> omega((unsigned int) n);
  for(int i = 0; i < n; i++){
    double angle = pi * 2.0 * i / n;
    omega[i].real = cos(-angle);
    omega[i].imag = sin(-angle);
  }
  return omega;
}

void fft(std::vector<MyComplex> &a, std::vector<MyComplex> &omega, bool inverse)
{
  int n = (int) a.size();
  if(__builtin_popcountll(n) != 1) std::cout << "error : " << __LINE__ << std::endl;

  if(inverse){
    for(int index = 0; index < n; index++){
      a[index].imag = -a[index].imag;
    }
  }

  {
    int bit_num = 0;
    while((1 << bit_num) < n) bit_num++;

    MyComplex *dat = new MyComplex[n];

    for(int index = 0; index < n; index++){
      dat[index] = a[index];
    }
    for(int index = 0; index < n; index++){
      int dest = 0;
      for(int b = 1, rev = n >> 1; b < n; b <<= 1, rev >>= 1){
        if(index & b) dest |= rev;
      }
      a[dest] = dat[index];
    }

    delete [] dat;
  }

  for(int range = 2; range <= n; range <<= 1){
    int omega_increment = n / range;
    int half_range = range >> 1;
    for(int align = 0; align < n; align += range){
      for(int pos = align; pos < align + half_range; pos++){
        MyComplex c0 = a[pos];
        MyComplex c1 = a[pos + half_range];
        MyComplex o = omega[omega_increment * (pos - align)];
        double c1_omega_real = c1.real * o.real - c1.imag * o.imag;
        double c1_omega_imag = c1.real * o.imag + c1.imag * o.real;
        a[pos] = c0 + MyComplex(c1_omega_real, c1_omega_imag);
        a[pos + half_range] = c0 + MyComplex(-c1_omega_real, -c1_omega_imag);
      }
    }
  }

  if(inverse){
    double n_inv = 1.0 / n;
    for(int index = 0; index < n; index++){
      a[index].real =  n_inv * a[index].real;
      a[index].imag = -n_inv * a[index].imag;
    }
  }
}

void fft2D_Y(std::vector<std::vector<MyComplex> > &a, long long int n, long long int m, bool reverse)
{
  std::vector<MyComplex> row((unsigned int) m);
  std::vector<MyComplex> omega = fftMakeOmega((unsigned int) m);
  for(int x = 0; x < n; x++){
    for(int y = 0; y < m; y++){
      row[y] = a[x][y];
    }
    fft(row, omega, reverse);
    for(int y = 0; y < m; y++){
      a[x][y] = row[y];
    }
  }
}

void fft2D_X(std::vector<std::vector<MyComplex> > &a, long long int n, long long int m, bool reverse)
{
  std::vector<MyComplex> col((unsigned int) n);
  std::vector<MyComplex> omega = fftMakeOmega((unsigned int) n);
  for(int y = 0; y < m; y++){
    for(int x = 0; x < n; x++){
      col[x] = a[x][y];
    }
    fft(col, omega, reverse);
    for(int x = 0; x < n; x++){
      a[x][y] = col[x];
    }
  }
}

void fft2D(std::vector<std::vector<MyComplex> > &a, bool reverse)
{
  int n = (int) a.size();
  int m = (int) a[0].size();
  if(__builtin_popcount(n) != 1) std::cout << "error : " << __LINE__ << std::endl;
  if(__builtin_popcount(m) != 1) std::cout << "error : " << __LINE__ << std::endl;


  if(!reverse){
    fft2D_X(a, n, m, reverse);
    fft2D_Y(a, n, m, reverse);
  }else{
    fft2D_Y(a, n, m, reverse);
    fft2D_X(a, n, m, reverse);
  }
}







