  for (int i = 1; i < N; ++i) {
    int w = N >> 1;
    while (j >= w) j -= w, w >>= 1;
    j += w;
    if (i < j) swap(a[i], a[j]);
  }
  static VV<C> xi;
  for (int k = 0; 1 << k < N; ++k) if (k >= (int)xi.size()) {
    xi.emplace_back(1 << k);
    for (int i = 0; i < 1 << k; ++i) {
      xi[k][i] = C(i * pi / (1 << k));
    }
  }
  for (int k = 0; 1 << k < N; ++k) {
    const int w = 1 << k;
    for (int s = 0; s < N; s += 2 * w) {
      for (int i = s; i < s + w; ++i) {
        C p = a[i], q = a[i + w] * (inv ? ~xi[k][i - s] : xi[k][i - s]);
        a[i] = p + q, a[i + w] = p - q;
      }
    }
  }
}
void fftR2(array<C, N>& a, array<C, N>& b) {
  array<C, N> c;
  for (int i = 0; i < N; ++i) {
    c[i] = {a[i].x, b[i].x};
  }
  fft(c);
  for (int i = 0; i < N; ++i) {
    a[i] = (c[i] + ~c[-i & N - 1]) * C(0.5, 0);
    b[i] = (c[i] - ~c[-i & N - 1]) * C(0, -0.5);
  }
}
void ifftR2(array<C, N>& a, array<C, N>& b) {
  array<C, N> c;
  for (int i = 0; i < N; ++i) {
    c[i] = a[i] + C(0, 1) * b[i];
  }
  fft(c, true);
  for (int i = 0; i < N; ++i) {
    a[i].x = c[i].x;
    b[i].x = c[i].y;
  }
}

