const int maxn = 8010, mod = 1e9 + 7;
int n, t[maxn][2], fact[maxn], inv[maxn];
void pre() {
	for(int i = 0; i < maxn; i++) {
		if(i < 2) fact[i] = inv[i] = 1;
		else fact[i] = fact[i-1]*1ll*i%mod, inv[i] = mod - (mod/i)*1ll*inv[mod%i]%mod;
	}
	for(int i = 1; i < maxn; i++) inv[i] = inv[i-1]*1ll*inv[i]%mod;
}
int nck(int n, int k) {
	if(n < 0 || k > n) return 0;
	int t = fact[n]*1ll*inv[k]%mod;
	return t*1ll*inv[n-k]%mod;
}
void add(int &a, int b) {
	a += b;
	if(a >= mod) a -= mod;
}
int main() {
	cin.tie(0)->sync_with_stdio(0);
	pre();
	cin >> n;
	int ans = 0;
	for(int a, b, i = 1; i <= n; i++) {
		cin >> a >> b;

		for(int pa = 1; pa <= 2000; pa++) {
			if(t[pa][1]) {
				int p = pa + a;
				add(ans, nck(b+p, p)*1ll*t[pa][0]%mod);
			}
		}
		for(int pb = 1; pb <= 2000; pb++) {
			if(t[pb][1]) {
				int p = pb + b;
				add(ans, nck(a+p, p)*1ll*t[pb][1]%mod);
			}
		}

		for(int pa = 1; pa <= a; pa++)
			add(t[pa][0], nck(a+b-pa-1, b-1));
		for(int pb = 1; pb <= b; pb++)
			add(t[pb][1], nck(a+b-pb-1, a-1)); 
	}
	cout << ans;
}

