//Πary modq
ll mod_multi(vector<int> ary, int q) {
	ll ret = 1;
	for (int i = 0; i < ary.size(); i++) {
		ret = ret*ary[i] % q;
	}
	return ret;
}

//aCb modq
ll mod_combination(int a, int b, int q) {
	if (b == 0) return 1;
	else {
		vector<int> numerator;
		vector<int> denominator;
		for (int i = a; i > a - b; i--) numerator.push_back(i);
		for (int i = b; i > 0; i--) denominator.push_back(i);
		for (int i = 0; i < denominator.size(); i++) {
			int j = 1;
			while (denominator[i] > 1) {
				j++;
				while (denominator[i] % j == 0) {
					denominator[i] /= j;
					for (int k = 0; k < numerator.size(); k++) {
						if (numerator[k] % j == 0) {
							numerator[k] /= j;
							break;
						}
					}
				}
			}
		}
		return mod_multi(numerator, q);
	}
}

int main() {
	int n;
