	cin >> n;
	ll ret = 0;
	Loop(i, n) {
		int a, b;
		cin >> A[i] >> B[i];
	}
	Loop(i, n) {
		for (int j = i + 1;j < n;j++) {
			ret += mod_combination(A[i] + A[j] + B[i] + B[j], A[i] + A[j], mod);
		}
	}
	cout << ret << endl;
	return 0;
}

