#define MOD 1000000007
#define lim 4000
#define off 4005
typedef long long ll;
inline int quick_pow(int a, int n)
{
	int res = 1;
	while (n)
	{
		if (n & 1)
			res = (ll)res * a % MOD;
		a = (ll)a * a % MOD;
		n >>= 1;
	}
	return res;
}
int dp[off << 1][off << 1], fact[20000005], inv[20000005], a[200005], b[200005], seq[200005];
inline int C(int n, int m) { return (ll)fact[n] * inv[m] % MOD * inv[n - m] % MOD; }
inline int calc(int x1, int y1, int x2, int y2) { return x1 > x2 || y1 > y2 ? 0 : C(x2 - x1 + y2 - y1, x2 - x1); }
inline void upd(int &x, int y) { (x += y) >= MOD ? x -= MOD : 0; }
inline void trans(int stp)
{
	for (int sum = stp; sum <= lim; sum++)
	{
		int mx = std::min(lim, sum + lim);
		for (int i = std::max(-lim, sum - lim); i <= mx; i++)
		{
			int j = sum - i;
			upd(dp[i + off][j + off], dp[i - 1 + off][j + off]);
			upd(dp[i + off][j + off], dp[i + off][j - 1 + off]);
		}
	}
}
int main()
{
	// freopen("gift.in", "r", stdin);
	// freopen("gift.out", "wt", stdout);
	do
	{
		const int mx = 2e7;
		fact[0] = 1;
		for (int i = 1; i <= mx; i++)
			fact[i] = (ll)fact[i - 1] * i % MOD;
		inv[mx] = quick_pow(fact[mx], MOD - 2);
		for (int i = mx; i; i--)
			inv[i - 1] = (ll)inv[i] * i % MOD;
	}
	while (false);
	int n, cnt = 0, ans = 0;
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", a + i, b + i);
		if (a[i] + b[i] > lim)
			seq[cnt++] = i;
	}
	for (int i = 0; i < cnt; i++)
	{
		for (int j = -lim; j <= lim; j++)
			upd(dp[j + off][-j + off], calc(-a[i], -b[i], j, -j));
	}
	trans(0);
	for (int i = 0; i < n; i++)
	{
		if (a[i] + b[i] <= lim)
			upd(ans, dp[a[i] + off][b[i] + off]);
	}
	upd(ans, ans);
	memset(dp, 0, sizeof(dp));
	for (int i = 0; i < n; i++)
	{
		if (a[i] + b[i] <= lim)
			upd(dp[-a[i] + off][-b[i] + off], 1);
	}
	trans(-lim);
	for (int i = 0; i < n; i++)
	{
		if (a[i] + b[i] <= lim)
			upd(ans, dp[a[i] + off][b[i] + off]);
	}
	for (int i = 0; i < cnt; i++)
	{
		for (int j = 0; j < cnt; j++)
			upd(ans, calc(-a[i], -b[i], a[j], b[j]));
	}
	for (int i = 0; i < n; i++)
	{
		int x = calc(-a[i], -b[i], a[i], b[i]);
		if (x)
			upd(ans, MOD - x);
	}
	printf("%d\n", ans);
	return 0;
}

#include <bits/stdc++.h>
#define LL long long
using namespace std;

const LL Mod = 1000000007;
const LL Maxn = 200010;
const LL AlphaSize = 2001;
LL N, A[ Maxn ], B[ Maxn ], Fact[ AlphaSize + 10 << 2 ], INV[ AlphaSize + 10 << 2 ];
LL F[ AlphaSize + 10 << 1 ][ AlphaSize + 10 << 1 ];

void Exgcd( LL a, LL b, LL &x, LL &y ) {
    if( b == 0 ) {
        x = 1; y = 0;
        return;
    }
    Exgcd( b, a % b, y, x );
    y -= a / b * x;
    return;
}

LL Inv( LL a ) {
    LL x, y;
    Exgcd( a, Mod, x, y );
    if( x < 0 ) x += Mod;
    return x;
}

LL C( LL n, LL m ) {
    return Fact[ m ] * INV[ n ] % Mod * INV[ m - n ] % Mod;
}

int main() {
    Fact[ 0 ] = 1;
    for( LL i = 1; i <= AlphaSize << 2; ++i ) Fact[ i ] = Fact[ i - 1 ] * i % Mod;
    INV[ AlphaSize << 2 ] = Inv( Fact[ AlphaSize << 2 ] );
    for( LL i = ( AlphaSize << 2 ) - 1; i >= 0; --i ) INV[ i ] = INV[ i + 1 ] * ( i + 1 ) % Mod;
    scanf( "%lld", &N );
    for( LL i = 1; i <= N; ++i ) scanf( "%lld%lld", &A[ i ], &B[ i ] );
    for( LL i = 1; i <= N; ++i ) ++F[ AlphaSize - A[ i ] ][ AlphaSize - B[ i ] ];
    for( LL i = 1; i <= AlphaSize << 1; ++i )
        for( LL j = 1; j <= AlphaSize << 1; ++j )
            F[ i ][ j ] = ( F[ i ][ j ] + F[ i - 1 ][ j ] + F[ i ][ j - 1 ] ) % Mod;
    LL Ans = 0;
    for( LL i = 1; i <= N; ++i ) Ans = ( Ans + F[ AlphaSize + A[ i ] ][ AlphaSize + B[ i ] ] ) % Mod;
    for( LL i = 1; i <= N; ++i ) Ans = ( ( Ans - C( A[ i ] * 2, A[ i ] * 2 + B[ i ] * 2 ) ) % Mod + Mod ) % Mod;
    printf( "%lld\n", Ans * Inv( 2 ) % Mod );
    return 0;
}

