inline int add(const int &A, const int &B){
    if(A + B >= MOD) return A + B - MOD;
    return A + B;
}

inline int mul(const int &A, const int &B){
    return (ll)A * B % MOD;
}

int a[N], b[N], n, dod[N], ch[M][M], sol;

void precompute(){
    for(int i = 0;i<M;i++) ch[i][0] = 1, ch[i][i] = 1;
    for(int i = 1;i<M;i++)
        for(int j = 1;j<i;j++)
            ch[i][j] = add(ch[i - 1][j - 1], ch[i - 1][j]);
}

int main(){
    precompute();
    scanf("%d", &n);
    for(int i = 0;i<n;i++){
        scanf("%d%d", a + i, b + i);
        a[i] += b[i];
        for(int k = -(a[i] - b[i]);k<=b[i];k++){
            sol = add(sol, mul(dod[M + k], ch[a[i]][b[i] - k]));
        }
        for(int k = 0;k<=a[i];k++){
            dod[M + k - b[i]] = add(dod[M + k - b[i]], ch[a[i]][k]);
        }
    }
    printf("%d\n", sol);
    return 0;
}

