#define mod 1000000007
#define C 2001

int n, a[200005], b[200005];
int grid[4005][4005], dp[4005][4005], ans;

int po(int A, int B){
	int c = 1, d = A;
	while(B){
		if(B & 1) c = 1LL * c * d % mod;
		d = 1LL * d * d % mod;
		B >>= 1;
	}
	return c;
}

int ncr(int N, int R){
	int res = 1;
	FI(i, 1, R){
		res = 1LL * res * (N + 1 - i) % mod;
		res = 1LL * res * po(i, mod - 2) % mod;
	}
	return res;
}

int main(){
	scanf("%d", &n);
	FI(i, 1, n){
		scanf("%d %d", &a[i], &b[i]);
		grid[C - a[i]][C - b[i]]--;
		grid[C + a[i]][C + b[i]]++;
	}
	FI(i, 1, 4002) FI(j, 1, 4002){
		dp[i][j] = (dp[i - 1][j] + dp[i][j - 1]) % mod;
		if(grid[i][j] < 0){
			dp[i][j] = (dp[i][j] - grid[i][j]) % mod;
		}
		if(grid[i][j] > 0){
			ans = (ans + 1LL * grid[i][j] * dp[i][j]) % mod;
		}
	}
	FI(i, 1, n) ans = (ans - ncr(2 * (a[i] + b[i]), 2 * b[i])) % mod;
	ans = 1LL * ans * po(2, mod - 2) % mod;
	printf("%d\n", (ans + mod) % mod);
	return 0;
}

