#include <iostream>
using namespace std;

#define X first
#define Y second

const long long N = 2 * 100 * 1000 + 10;
const long long M = 2 * 1000;
const long long MOD = 1000 * 1000 * 1000 + 7;

long long n;
pair <long long, long long> prr[N];
long long dp[(M << 1) + 10][(M << 1) + 10];
long long fact[N], rev[N];

void input() {
    cin >> n;

    for (long long i = 0; i < n; i++)
        cin >> prr[i].X >> prr[i].Y;
    return;
}

long long pw(long long x ,long long y) {
    long long res = 1;
    for (; y; y /= 2, x = (x * x) % MOD)
        if (y & 1)
            res = (res * x) % MOD;
    return res;
}

long long C(long long a, long long b) {
    long long res = fact[a];
    res = (res * rev[b]) % MOD;
    res = (res * rev[a - b]) % MOD;
    return res;
}

void PrePros() {
    fact[0] = 1;
    for (long long i = 1; i < N; i++)
        fact[i] = (fact[i - 1] * i) % MOD;

    rev[N - 1] = pw(fact[N - 1], MOD - 2);
    for (long long i = N - 2; i >= 0; i--)
        rev[i] = (rev[i + 1] * (i + 1)) % MOD;
    return;
}

void solve() {
    PrePros();

    for (long long i = 0; i < n; i++)
        dp[M - prr[i].X][M - prr[i].Y] += 1;

    for (long long i = 0; i < 2 * M; i++)
        for (long long j = 0; j < 2 * M; j++)
            dp[i][j] = (dp[i][j] + dp[i - 1][j] + dp[i][j - 1]) % MOD;
    return;
}

void output() {
    long long ans = 0;

    for (long long i = 0; i < n; i++) {
        ans = (ans + dp[M + prr[i].X][M + prr[i].Y]) % MOD;
        ans = (ans - C(2 * (prr[i].X + prr[i].Y), 2 * prr[i].X) + MOD) % MOD;
    }

    cout << (1LL * ans * pw(2, MOD - 2)) % MOD << endl;
    return;
}

int main() {
    input();
    solve();
    output();
    return 0;
}

