signed a[MAXN];
signed b[MAXN];
double ab[MAXSIZE];

int binpow(int a, int b, int mo) {
  int ans = 1;
  do {
    if (b & 1) ans = 1ll * ans * a % mo;
    a = 1ll * a * a % mo;
  } while (b >>= 1);
  return ans;
}

const int FACTSIZE = 10100;
int fact[FACTSIZE];
int revfact[FACTSIZE];

int ncr(int n, int r) {
  if (n < r) return 0;
  int rs = fact[n] * revfact[r];
  if (rs >= MOD) rs %= MOD;
  rs *= revfact[n - r];
  if (rs >= MOD) rs %= MOD;
  return rs;
}
void init() {
  fact[0] = 1, revfact[0] = 1;
  for (int i = 1; i < FACTSIZE; ++i) {
    fact[i] = fact[i - 1] * i % MOD;
    revfact[i] = binpow(fact[i], MOD - 2, MOD);
  }
}
signed ip[10000];
double w[(MAXSIZE / 4)];

void convolve2(double *a, signed n) {
  signed s = n + n - 1;  // 畳み込み結果のサイズ
  signed t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  ip[0] = 0;
  cdft(2 * t, 1, a, ip, w);
  for (signed i = 0; i < t; i++) {
    signed addr = 2 * i;
    double tmpa = a[addr];
    a[addr] = a[addr] * a[addr] - a[addr + 1] * a[addr + 1];
    a[addr + 1] = 2 * tmpa * a[addr + 1];
  }
  cdft(2 * t, -1, a, ip, w);
  for (signed j = 0; j < t; j++) {
    a[j * 2] *= 1.0 / t;
    a[j] = a[j * 2];
  }
}

signed N;
signed main() {
  init();
  cin.tie(0), ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int N;
  cin >> N;

  signed maxV = 0;
  REP(i, N) {
    cin >> a[i] >> b[i];
    chmax(maxV, a[i]);
    chmax(maxV, b[i]);
  }
  maxV *= 2;
  maxV += 1;

  int maxAB = 0;
  REP(i, N) {
    int val = a[i] * maxV + b[i];
    ab[2 * val]++;
    chmax(maxAB, val);
  }
  maxAB++;
  convolve2(ab, maxAB);
  int res = 0;
  REP(i, maxAB) {
    int i0 = i / maxV;
    int i1 = i % maxV;
    int val = round(ab[i]);
    res += val * ncr(i0 + i1, i0);
    res %= MOD;
  }
  int tmp = 0;
  REP(i, N) {
    tmp += ncr(2 * a[i] + 2 * b[i], 2 * a[i]);
    tmp %= MOD;
  }
  res = (res - tmp + MOD) % MOD;
  res *= revfact[2];
  res %= MOD;
  print(res);
}

#include <cstdio>
#include <algorithm>
using namespace std;
typedef long long ll;
inline int read() {
    char ch = getchar(); int x = 0;
    while(ch < '0' || ch > '9') ch = getchar();
    while(ch >= '0' && ch <= '9') x = x*10+ch-'0', ch = getchar();
    return x;
}

const int N = 2e5+5;
const int M = 4005;
const int mod = 1e9+7;

int n, m, a[N], b[N];
ll fac[N], inv[N];
struct Map {
    int val[M][M];
    int &operator ()(int x, int y) {
        return val[x+m][y+m];
    }
} dp;

ll quickpow(ll x, int k) {
    ll ret = 1;
    for(; k; k >>= 1, (x *= x) %= mod)
        if(k & 1) (ret *= x) %= mod;
    return ret;
}

void update(int &x, int y) {
    x += y;
    if(x >= mod) x -= mod;
    if(x < 0) x += mod;
}

int combine(int n, int m) {
    ll ret = fac[n];
    (ret *= inv[m]) %= mod;
    (ret *= inv[n-m]) %= mod;
    return ret;
}


int main() {
    n = 1e4;
    fac[0] = 1;
    for(int i = 1; i <= n; ++i) fac[i] = fac[i-1] * i % mod;
    inv[n] = quickpow(fac[n], mod-2);
    for(int i = n-1; ~i; --i) inv[i] = inv[i+1] * (i+1) % mod;

    n = read();
    for(int i = 1; i <= n; ++i) {
        a[i] = read(), b[i] = read();
        m = max(m, a[i]);
        m = max(m, b[i]);
    }

    for(int i = 1; i <= n; ++i) ++dp(-a[i], -b[i]);
    for(int i = -m; i <= m; ++i)
    for(int j = -m; j <= m; ++j)
        update(dp(i+1, j), dp(i, j)),
        update(dp(i, j+1), dp(i, j));

    int ans = 0;
    for(int i = 1; i <= n; ++i)
        update(ans, dp(a[i], b[i]));
    for(int i = 1; i <= n; ++i)
        update(ans, -combine(2*(a[i]+b[i]), a[i]+a[i]));
    ans = 1LL * ans * quickpow(2, mod-2) % mod;
    update(ans, mod);
    printf("%d\n", ans);
    return 0;
}

