typedef long long ll;
const ll N=4005,M=8000;
ll Z=2001;
const ll mod=1e9+7;
const ll inv2=5e8+4;
ll n;
ll a[N+5],b[N+5];
ll d[N+5][N+5];
ll fact[M+5],inv[M+5];
void Init(){
    fact[0]=1;
    for(ll i=1;i<=M;i++)
        fact[i]=(1ll*fact[i-1]*i)%mod;
    inv[1]=1;
    for(ll i=2;i<=M;i++)
        inv[i]=1ll*(mod-mod/i)*inv[mod%i]%mod;
    inv[0]=1;
    for(ll i=1;i<=M;i++)
        inv[i]=1ll*inv[i]*inv[i-1]%mod;
}
ll C(ll x,ll y){
    return 1ll*fact[x]*inv[y]%mod*inv[x-y]%mod;
}
int main()
{
    Init();
    scanf("%lld",&n);
    for(ll i=1;i<=n;i++){
        scanf("%lld%lld",&a[i],&b[i]);
        d[Z-a[i]][Z-b[i]]++;
    }
    for(ll i=1;i<N;i++)
        for(ll j=1;j<N;j++)
            d[i][j]=((d[i][j]+d[i][j-1])%mod+d[i-1][j])%mod;
    ll ans=0;
    for(ll i=1;i<=n;i++){
        ans+=d[Z+a[i]][Z+b[i]];
        ans%=mod;
        ans-=C(a[i]*2+b[i]*2,a[i]*2);
        ans=(ans%mod+mod)%mod;
    }
    ans=1ll*ans*inv2%mod;
    printf("%lld\n",ans);
}

