using namespace std;
const int p=1000000007;
const int N=2000;
long long f[N*2+2][N*2+2],prime[1005],minn[2005],x,y,ans,step[N+2],inv[2005];
long long n,a[N+2],b[N+2],amax,bmax,cnt[1005],tot,c[2002],d[2005],finv[2005];
bool vi[2005];
void cou(int num)
{
	int x=max(a[num],b[num]),y=min(a[num],b[num]);
	step[num]=1;
	for(int i=1;i<=y;i++)
	{
		step[num]=((long long)step[num]*(x+i))%p;
		step[num]=((long long)step[num]*inv[i])%p;
	}
}
int cheng(int a,int b)
{
	int now=a,ans=1;
	while(b)
	{
		if(b&1)
			ans=((long long)now*ans)%p;
		b>>=1;
		now=((long long)now*now)%p;
	}
	return ans;
}
void chuli()
{
	d[1]=1;
	for(int i=2;i<=N;i++)
		d[i]=((long long)d[i-1]*i)%p;
	finv[N]=cheng(d[N],p-2);
	for(int i=N-1;i>=1;i--)
		finv[i]=((long long)finv[i+1]*(i+1))%p;
	inv[1]=finv[1];
	for(int i=2;i<=N;i++)
	{
		inv[i]=((long long)finv[i]*d[i-1])%p;
	//	printf("inv[%d]=%d\n",i,inv[i]);
	}
}
int main()
{
//	freopen("1.out","w",stdout);
	scanf("%lld",&n);
	chuli();
	for(int i=1;i<=n;i++)
	{
		scanf("%lld %lld",&a[i],&b[i]);
		a[i]*=2;b[i]*=2;
		cou(i);
	//	printf("step[%d]=%d\n",i,step[i]);
		a[i]/=2;b[i]/=2;
		amax=max(amax,a[i]);
		bmax=max(bmax,b[i]);
//		printf("step[%d]=%d\n",i,step[i]);
	}
	for(int i=1;i<=n;i++)
	{
		f[amax-a[i]][bmax-b[i]]++;
//		printf("f[%d][%d]++\n",amax-a[i],bmax-b[i]);
		a[i]=amax+a[i];
		b[i]=bmax+b[i];
//		printf("a[%d]=%d b[%d]=%d\n",i,a[i],i,b[i]);
	}
	x=2*amax;y=2*bmax;
	for(int i=0;i<=x;i++)
	{
		for(int j=0;j<=y;j++)
		{
			if(i>0)
			f[i][j]+=f[i-1][j];
			if(j>0)
			f[i][j]+=f[i][j-1];
			f[i][j]%=p;
		}
	}
	for(int i=1;i<=n;i++)
	{
		ans+=f[a[i]][b[i]]-step[i];
		ans%=p;
	}
	tot=cheng(2,p-2);
//	printf("tot=%d\n",tot);
	ans=((long long)ans*tot)%p;
	printf("%lld",ans);
	return 0;
}

