ll extgcd(ll a, ll b, ll& x, ll& y) {
	ll d = a;
	if (b != 0) {
		d = extgcd(b, a%b, y, x);
		y -= (a / b)*x;
	}
	else {
		x = 1; y = 0;
	}
	return d;
}
ll inverse(ll a,ll m) {
	ll x, y;
	extgcd(a, m, x, y);
	return (m + x%m) % m;
}
ll inv(ll a) {
	ll m = MOD;
	return inverse(a, m);
}
