ll com[2001][2001];
void setcombi() {
	for (int i = 1; i <= 2000; i++) {
		com[i][1] = i;
	}
	for (int i = 1; i <= 2000; i++) {
		for (int j = 2; j <= i; j++) {
			ll a = com[i][j-1];
			a = (a*(i - j + 1)) % MOD;
