#include <iostream>
using namespace std;

#define X first
#define Y second

const int N = 2 * 100 * 1000 + 10;
const int M = 2 * 1000;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
pair <int, int> prr[N];
int dp[(M << 1) + 10][(M << 1) + 10];
long long fact[N], rev[N];

void input() {
    cin >> n;

    for (int i = 0; i < n; i++)
        cin >> prr[i].X >> prr[i].Y;
    return;
}

long long pw(long long x ,long long y) {
    long long res = 1;
    for (; y; y /= 2, x = (x * x) % MOD)
        if (y & 1)
            res = (res * x) % MOD;
    return res;
}

long long C(int a, int b) {
    long long res = fact[a];
    res = (res * rev[b]) % MOD;
    res = (res * rev[a - b]) % MOD;
    return res;
}

void PrePros() {
    fact[0] = 1;
    for (int i = 1; i < N; i++)
        fact[i] = (fact[i - 1] * i) % MOD;

    rev[N - 1] = pw(fact[N - 1], MOD - 2);
    for (int i = N - 2; i >= 0; i--)
        rev[i] = (rev[i + 1] * (i + 1)) % MOD;
    return;
}

void solve() {
    PrePros();

    for (int i = 0; i < n; i++)
        dp[M - prr[i].X][M - prr[i].Y] += 1;

    for (int i = 0; i < 2 * M; i++)
        for (int j = 0; j < 2 * M; j++)
            dp[i][j] = (dp[i][j] + dp[i - 1][j] + dp[i][j - 1]) % MOD;
    return;
}

void output() {
    long long ans = 0;

    for (int i = 0; i < n; i++) {
        ans = (ans + dp[M + prr[i].X][M + prr[i].Y]) % MOD;
        ans = (ans - C(2 * (prr[i].X + prr[i].Y), 2 * prr[i].X) + MOD) % MOD;
    }

    cout << (1LL * ans * pw(2, MOD - 2)) % MOD << endl;
    return;
}

int main() {
    input();
    solve();
    output();
    return 0;
}

