const int N = 2e5 + 10;
const int M = 8010;
const int L = 4010;
const int mod = 1e9 + 7;

typedef long long LL;

LL F[M], R[M];
int dp[L][L];
int X[N], Y[N];

inline void add(int &x, int y){
	x += y;
	if(x >= mod)	x -= mod;
}

LL pow_mod(LL x, int p){
	LL s = 1;
	while(p){
		if(p & 1)	s = s * x % mod;
		x = x * x % mod;
		p >>= 1;
	}
	return s;
}

LL C(int n, int m){
	return F[n] * R[m] % mod * R[n-m] % mod;
}

int main(){
	F[0] = R[0] = 1;
	for(int i=1; i<M; i++){
		F[i] = F[i-1] * i % mod;
		R[i] = pow_mod(F[i], mod-2);
	}
	int n;
	while(~scanf("%d", &n)){
		memset(dp, 0, sizeof(dp));
		for(int i=0; i<n; i++){
			scanf("%d %d", X+i, Y+i);
			dp[2000-X[i]][2000-Y[i]]++;
		}
        for(int i=0; i<L; i++){
			for(int j=0; j<L; j++){
				if(i==0 && j==0){
					continue;
				} else if(i == 0){
					add(dp[i][j], dp[i][j-1]);
				} else if(j == 0){
					add(dp[i][j], dp[i-1][j]);
				} else{
					add(dp[i][j], dp[i][j-1]);
					add(dp[i][j], dp[i-1][j]);
				}
			}
        }
        LL ans = 0;
        for(int i=0; i<n; i++){
            ans = ans + dp[2000+X[i]][2000+Y[i]] - C(X[i]+Y[i]<<1, X[i]<<1);
            ans = (ans % mod + mod) % mod;
        }
        printf("%lld\n", ans * pow_mod(2, mod-2) % mod);
	}
	return 0;
}

