const int MOD = 1e9 + 7;

inline void ModSum(int& x, int y) {
    x += y;
    if (x >= MOD) {
        x -= MOD;
    }
    if (x < 0) {
        x += MOD;
    }
}

inline int GetModSum(int x, int y) {
    ModSum(x, y);
    return x;
}

inline void ModMul(int& x, int y) {
    x = (1LL * x * y) % MOD;
}

inline int GetModMul(int x, int y) {
    ModMul(x, y);
    return x;
}

int GetBinaryPow(int x, int pw) {
    int result = 1;
    while (pw > 0) {
        if (pw & 1) {
            ModMul(result, x);
        }
        ModMul(x, x);
        pw >>= 1;
    }
    return result;
}

int GetInv(int x) {
    return GetBinaryPow(x, MOD - 2);
}

