	inv[0]=1;
	for(int i=n-1;i>=1;--i)
		inv[i]=inv[i+1]*(i+1)%mod;
}

inline long long c(long long n,long long m)
{
	return fac[n]*inv[m]%mod*inv[n-m]%mod;
}

