int fac_inv[maxA << 2];
int f[maxA << 1][maxA << 1];
inline int add(int x) {
	return x >= mod ? x - mod : x;
}
inline int dec(int x) {
	return x < 0 ? x + mod : x;
}
ll power(ll x, ll y) {
	ll re = 1;
	while(y) {
		if(y & 1) re = re * x % mod;
		x = x * x % mod;
		y >>= 1;
	}
	return re;
}
inline ll C(int x, int y) {
	return (ll)fac[x] * fac_inv[y] % mod * fac_inv[x - y] % mod;
}
void init(int n) {
	fac[0] = 1;
	for(int i = 1; i <= n; ++i) {
		fac[i] = (ll)fac[i - 1] * i % mod;
	}
	fac_inv[n] = inver(fac[n]);
	for(int i = n; i >= 1; --i) {
		fac_inv[i - 1] = (ll)fac_inv[i] * i % mod;
	}
}
int solve() {
	init(8000);
	for(int i = 1; i <= n; ++i) {
		++f[W - A[i]][H - B[i]];
	}
	for(int i = 1; i <= (W << 1); ++i) {
		for(int j = 1; j <= (H << 1); ++j) {
			f[i][j] = add(f[i][j] + add(f[i - 1][j] + f[i][j - 1]));
		}
	}
	int an = 0;
	for(int i = 1; i <= n; ++i) {
		an = add(an + f[W + A[i]][H + B[i]]);
		an = dec(an - C((A[i] << 1) + (B[i] << 1), A[i] << 1));
	}
	return an >> 1;
}
int main() {
	read(n);
	for(int i = 1; i <= n; ++i) {
		read(A[i]), read(B[i]);
		W = max(W, A[i] + 1);
		H = max(H, B[i] + 1);
	}
	printf("%d\n", solve());
	return 0;
}

