lli euler(lli m){
	vector<int> p;
	lli M = m;
	for(int i = 2;i<=m;i++){
		if(m%i==0){
			p.push_back(i);
			while(m%i==0)m/=i;
		}
		if(M<i*i&&p.size()==0){
			p.push_back(M);
			break;
		}

	}
	lli ans = M;
	rep(i,p.size()){
		//cout << p[i]<<endl;
		ans = ans * (p[i]-1)/p[i];
	}
	return ans;
}
lli powm(lli a,lli p,lli mod){
	lli ans =1;
	while(p>0){
		if(p&1)ans=(ans*a) % mod;
		a=(a*a)%mod;
		p >>=1;
	}
	return ans%mod;
}
