		for (int j=1; j<i; j++) C[i][j]=(C[i-1][j] + C[i-1][j-1])%mod;
	}
	for (int i=1; i<=n; i++){
		ans=(ans + dp[MAXN+X[i]][MAXN+Y[i]])%mod;
		ans=(ans - C[X[i]*2+Y[i]*2][X[i]*2])%mod;
	}
	//debug(ans)
	ans=1ll*ans*(mod+1)/2%mod;
	if (ans<0) ans+=mod;
	cout<<ans<<'\n';

	return 0;
}

