ll qow(ll a, ll b)
{
	ll ans = 1;
	for (; b; b >>= 1)
	{
		if (b & 1)
			ans = ans * a % mod;
		a = a * a % mod;
	}
	return ans;
}
ll f(ll i, ll j)
{
	return fac[i + j] * inv[i] % mod * inv[j] % mod;
}
ll& upd(ll &a, ll b)
{
	a = a + b < mod ? a + b : a + b - mod;
	return a;
}
int main()
{
	fac[0] = 1;
	for (ll i = 1; i < 8001; i++)
		fac[i] = fac[i - 1] * i % mod;
	inv[8000] = qow(fac[8000], mod - 2);
	for (ll i = 7999; i >= 0; i--)
		inv[i] = inv[i + 1] * (i + 1) % mod;
	scanf("%lld", &n);
