const int MAXN = 2e3 + 10;
const int MOD = 1e9 + 7;

int n, dp[2 * MAXN][2 * MAXN], go[2 * MAXN][2 * MAXN];
int fac[4 * MAXN];

long long po(long long v, long long u)
{
	return u ? (po(v * v % MOD, u >> 1) * (u & 1 ? v : 1) % MOD) : 1;
}

int ente(int i, int j) {
	return (((fac[j] * po(fac[i], MOD - 2)) % MOD) * po(fac[j - i], MOD - 2)) % MOD;
}

int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	fac[0] = 1;
	for (int i = 1; i < 4 * MAXN; i++)
		fac[i] = (1ll * fac[i - 1] * i) % MOD;
	cin >> n;
	long long res = 0;
	for (int i = 0; i < n; i++)
	{
		int a, b;
		cin >> a >> b;
		dp[MAXN - a][MAXN - b]++;
		go[MAXN + a][MAXN + b]++;
		res = (res - ente(2 * a , 2 * (a + b)) + MOD) % MOD;
	}
	for (int i = 1; i < 2 * MAXN; i++)
	{
		for (int j = 1; j < 2 * MAXN; j++)
		{
			dp[i][j] += dp[i - 1][j] + dp[i][j - 1];
			dp[i][j] %= MOD;
			res += 1ll * go[i][j] * dp[i][j];
			res %= MOD;
		}
	}
	cout << (res * (MOD / 2 + 1)) % MOD << endl;
	return 0;
}

