const int MOD = 1e9 + 7, MAX = 2007, MAXN = 200007;
int add(int a, int b) { a += b; if (a >= MOD) a -= MOD; return a; }
int sub(int a, int b) { a -= b; if (a < 0) a += MOD; return a; }
int mul(int a, int b) { return (long long) a * b % MOD; }

int F[MAX << 1][MAX << 1], G[MAX][MAX], N, A[MAXN], B[MAXN];

#define FOR(i, a, b) for (int i = a; i <= b; ++i)

int main()
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> N;
	FOR(i, 0, N-1) cin >> A[i] >> B[i];

    FOR(i, 0, (MAX << 1) - 1) F[i][0] = F[0][i] = 1;
    FOR(i, 1, (MAX << 1) - 1) FOR(j, 1, (MAX << 1) - 1) {
        F[i][j] = add(F[i-1][j], F[i][j-1]);
    }

    FOR(i, 0, N-1) G[0][0] = add(G[0][0], F[A[i]][B[i]]);
    FOR(a, 1, MAX-1) FOR(i, 0, N-1) G[a][0] = add(G[a][0], F[A[i] + a][B[i]]);
    FOR(b, 1, MAX-1) FOR(i, 0, N-1) G[0][b] = add(G[0][b], F[A[i]][B[i] + b]);

    FOR(a, 1, MAX-1) FOR(b, 1, MAX-1) G[a][b] = add(G[a-1][b], G[a][b-1]);

    int ans = 0;
    FOR(i, 0, N-1) {
        ans = sub(ans, F[A[i] + A[i]][B[i] + B[i]]);
        ans = add(ans, G[A[i]][B[i]]);
    }

    cout << mul(ans, (MOD + 1) >> 1) << endl;
}

