    a[x][y]++;
    ans -= COM(2 * x + 2 * y , 2 * x);
  } 

  constexpr int D = 2000;
  FPS f(2 * D + 5);
  for(int k = D * 2 ; k > 0 ; k--){
    FPS g(2 * D + 5);
    for(int i = 1 ; i <= D ; i++){
      if(k - i < 0 || k - i > D) continue;
      if(a[i][k - i] != 0)
        g[D - i] += a[i][k - i];
    }
    f += g;
    mul_simple(f , 1 , 1 , 1);
  }
