    LL ret = 1;
    for (; exp; exp >>= 1, x = x * x % mod)
      if (exp & 1) ret = ret * x % mod;
    return ret;
  }
  inline void pre() {
    for (int i = fac[0] = 1; i < K; i ++) fac[i] = fac[i - 1] * i % mod;
    inv[K - 1] = pow(fac[K - 1], mod - 2);
