        if(b & 1) {
            res = (res * a) % mod;
        }
        a = (a * a) % mod;
        b /= 2;
    }
    return res;
}

inline ll c(ll a , ll b) {
    ll res = (fac[a] * inv[b]) % mod;
    res = (res * inv[a - b]) % mod;
    return res; 
