int choose(int a, int b)
{
	if(a < b) return 0;
	if(dp[a][b] != -1) return dp[a][b];
	if(b == 0) return 1;
	if(b == 1) return a;
	dp[a][b] = (choose(a - 1, b) + choose(a - 1, b - 1))%MOD;
	return dp[a][b];
}

