typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 30;
const int MOD = 1e9 + 7;
const int M = 2e3 + 10;
int dp[M << 1][M << 1];
int target[M << 1][M << 1];
int F[M << 1];

int64 power_mod(int64 a, int n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % MOD;
    a = a * a % MOD;
  }
  return ret;
}

int64 inv_mod(int64 a) {
  return power_mod(a, MOD - 2);
}

int comb(int n, int m) {
  return (int64)F[n] * inv_mod(F[m]) % MOD * inv_mod(F[n - m]) % MOD;
}

int main() {
  F[0] = 1;
  for (int i = 1; i < (M << 1); ++i) {
    F[i] = (int64)F[i - 1] * i % MOD;
  }
  int n, ret = 0;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    int x, y;
    scanf("%d%d", &x, &y);
    dp[M - x][M - y] += 1;
    target[M + x][M + y] += 1;
    ret = (ret + MOD - comb((x + y) << 1, x << 1)) % MOD;
  }
  for (int i = 0; i < (M << 1); ++i) {
    for (int j = 0; j < (M << 1); ++j) {
      if (i - 1 >= 0) {
        dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD;
      }
      if (j - 1 >= 0) {
        dp[i][j] = (dp[i][j] + dp[i][j - 1]) % MOD;
      }
      if (target[i][j]) {
        ret = (ret + (int64)target[i][j] * dp[i][j]) % MOD;
      }
    }
  }
  printf("%lld\n", ret * inv_mod(2) % MOD);
  return 0;
}

