void precompute () {
    for (int i=0; i<LIM*2; i++) {
        nck[i][0] = nck[i][i] = 1;
        for (int j = 1; j < i; j++) {
            nck[i][j] = (nck[i-1][j] + nck[i-1][j-1]) % MOD;
