#include <bits/stdc++.h>

using namespace std;

#define ll long long

const ll MOD = 1000000007LL;
ll dp[4001][4001];

// aのb乗を求める.
ll modpow(ll a, ll b) {
	if (a > MOD) a %= MOD;
	if (b == 0LL) return 1LL;
	ll tmp = modpow(a, b / 2);
	if (b & 1LL)
		return tmp * tmp % MOD * a % MOD;
	return tmp * tmp % MOD;
}

// aの逆元を求める.
ll inverse(ll a) {
	return modpow(a, MOD - 2);
}

// kの階乗を計算する.(sgnを0以外に設定すると逆元を返す)
ll fact(ll k, int sgn = 0) {
	static vector<ll> fac(2, 1LL);
	static vector<ll> inv(2, 1LL);
	static vector<ll> finv(2, 1LL);
	static ll nx = 2LL;
	while (nx <= k) {
		fac.push_back(fac[nx - 1] * nx % MOD);
		inv.push_back(MOD - inv[MOD % nx] * (MOD / nx) % MOD);
		finv.push_back(finv[nx - 1] * inv[nx] % MOD);
		++nx;
	}
	if (sgn == 0)
		return fac[k];
	return finv[k];
}

// aCbを計算する.
ll comb(ll a, ll b) {
	if (b < 0 || b > a) return 0;
	return fact(a) * fact(b, 1) % MOD * fact(a - b, 1) % MOD;
}


signed main() {
	int n; cin >> n;
	vector<int> a(n), b(n);
	for (int i = 0; i < n; ++i)
		cin >> a[i] >> b[i];

	// dpの初期化
	for (int i = 0; i < n; ++i) {
		int x = -a[i] + 2000, y = -b[i] + 2000;
		++dp[x][y];
	}

	// dpの遷移
	for (int x = 0; x < 4001; ++x) {
		for (int y = 0; y < 4001; ++y) {
			if (x < 4000) // 右に遷移可能
				dp[x + 1][y] = (dp[x + 1][y] + dp[x][y]) % MOD;
			if (y < 4000) // 上に遷移可能
				dp[x][y + 1] = (dp[x][y + 1] + dp[x][y]) % MOD;
		}
	}

	// 答えの計算
	ll res = 0;
	for (int i = 0; i < n; ++i) {
		res += dp[a[i] + 2000][b[i] + 2000];
		res %= MOD;
	}
	for (int i = 0; i < n; ++i) { // 余分なものを除く
		ll rem = comb(2LL * a[i] + 2LL * b[i], 2LL * a[i]);
		res -= rem;
		res = (res + MOD) % MOD;
	}
	res *= inverse(2);
	res %= MOD;

	cout << res << endl;

	return 0;
}

