const int N = 2e5 + 5, M = 2e3 + 5, P = 1e9 + 7;
int fact[M << 2] = {1}, rev[M << 2] = {1};
int n, a[N], b[N], dp[M << 1][M << 1];

inline int pwr(int a, int b) {
	int ans = 1;
	for ( ; b; a = 1LL * a * a % P, b >>= 1)
		ans = b & 1? 1LL * ans * a % P: ans;
	return ans;
}

inline int C(int a, int b) {
	return 1LL * fact[a] * rev[b] % P * rev[a - b] % P;
}

inline void read_input() {
	cin >> n;
	for (int i = 0; i < n; i++)
		cin >> a[i] >> b[i];
}

inline void solve() {
	int ans = 0;
	for (int i = 0; i < n; i++)
		dp[M - a[i]][M - b[i]]++;
	for (int i = 1; i < M << 1; i++)
		for (int j = 1; j < M << 1; j++)
			(dp[i][j] += dp[i - 1][j] + dp[i][j - 1]) %= P;
	for (int i = 1; i < M << 1; i++)
		rev[i] = pwr(fact[i] = 1LL * fact[i - 1] * i % P, P - 2);
	for (int i = 0; i < n; i++)
		(ans += (dp[M + a[i]][M + b[i]] + P - C(a[i] + b[i] << 1, a[i] << 1)) % P) %= P;
	cout << 1LL * ans * rev[2] % P;
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	read_input(), solve();
	return 0;
}

