struct base {

    float a, b;

    base() : a(0), b(0) {}

    base(float a) : a(a), b(0) {}

    base(float a, float b) : a(a), b(b) {}

};

inline base operator + (const base& a, const base& b) {
    return base(a.a + b.a, a.b + b.b);
}

inline base operator - (const base& a, const base& b) {
    return base(a.a - b.a, a.b - b.b);
}

inline base operator * (const base& a, const base& b) {
    return base(a.a * b.a - a.b * b.b, a.a * b.b + b.a * a.b);
}

inline base operator / (const base& a, double b) {
    return base(a.a / b, a.b / b);
}

inline void fft(base* a, int n, bool fl) {
    for (int i = 1, j = 0; i < n; ++i) {
        int bit = n / 2;
        for (; j >= bit; bit /= 2) {
            j -= bit;
        }
        j += bit;
        if (i < j) {
            swap(a[i], a[j]);
        }
    }
    for (int len = 2; len <= n; len *= 2) {
        double ang = 2 * pi / len * (fl ? -1 : 1);
        base wlen(cos(ang), sin(ang));
        static base w[SZ / 2];
        w[0] = 1;
        for (int i = 1; i < len / 2; ++i) {
            w[i] = w[i - 1] * wlen;
        }
        for (int i = 0; i < n; i += len) {
            for (int j = 0; j < len / 2; ++j) {
                base u = a[i + j], v = a[i + j + len / 2] * w[j];
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
            }
        }
    }
    if (fl) {
        for (int i = 0; i < n; ++i) {
            a[i] = a[i] / n;
        }
    }
}

int a[N], b[N], f[2 * BASE], rf[2 * BASE];
base cnt[SZ];

inline int calc(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b % 2 != 0) {
            res = (1LL * res * a) % MOD;
        }
        a = (1LL * a * a) % MOD;
        b /= 2;
    }
    return res;
}

inline int cnk(int n, int k) {
    assert(0 <= k && k <= n);
    int res = (1LL * f[n] * rf[k]) % MOD;
    res = (1LL * res * rf[n - k]) % MOD;
    return res;
}

