typedef MyComplex< ld > cd;
typedef ve< cd > vcd;

// fft using merge
void
fft(cd *as, int n, ld mult = 1.)
{
    int k = 0;
    while ((1 << k) < n) {
        ++k;
    }

    vi rev(n / 2);
    rev[0] = 0;
    int high1 = -1;
    for (int i = 1; i < n; ++i) {
        if ((i & (i - 1)) == 0) {
            high1++;
        }
        int trev = rev[i ^ (1 << high1)] | (1 << (k - high1 - 1));
        if (trev > i) {
            swap(as[i], as[trev]);
        }
        if (i < n / 2) {
            rev[i] = trev;
        }
    }

    vcd roots(k);
    double alpha = 2 * M_PI / n * mult;
    roots[0] = cd(cos(alpha), sin(alpha));
    for (int i = 1; i < k; ++i) {
        roots[i] = roots[i - 1] * roots[i - 1];
    }

    for (int len = 1, it = k - 1; len < n; len <<= 1, --it) {
        cd mult1 = roots[it];
        for (int pdest = 0; pdest < n; pdest += len) {
            cd mult2 = cd(1., 0.);
            for (int i = 0; i < len; ++i, ++pdest) {
                cd val = mult2 * as[pdest + len];
                as[pdest + len] = as[pdest] - val;
                as[pdest] += val;
                mult2 = mult2 * mult1;
            }
        }
    }
}

