const int MAXN = 4096;

cd f[MAXN][MAXN];
int val[MAXN][MAXN];
cd tmp[MAXN];

struct Solution: Data {

    int inv(int x) {
        int res = 1, st = MOD - 2;
        while (st) {
            if (st & 1) {
                res = 1ll * res * x % MOD;
            }
            st /= 2;
            x = 1ll * x * x % MOD;
        }
        return res;
    }

    vi fact, rfact;

    Solution() {
        fact.resize(4 * MAXN);
        fact[0] = 1;
        rfact = fact;
        forn (i, 1, 4 * MAXN) {
            fact[i] = 1ll * fact[i - 1] * i % MOD;
            rfact[i] = inv(fact[i]);
        }
    }

    void convert(ld mult) {
        forn (j, MAXN) {
            forn (i, MAXN) {
                tmp[i] = f[i][j];
            }
            fft(tmp, MAXN, mult);
            forn (i, MAXN) {
                f[i][j] = tmp[i];
            }
        }
        forn (i, MAXN) {
            fft(f[i], MAXN, mult);
        }
    }

    int cc(int a, int b) {
        return 1ll * fact[a + b] * rfact[a] % MOD * rfact[b] % MOD;
    }

        void solve () {
        forn (i, MAXN) {
            forn (j, MAXN) {
                f[i][j] = cd(0., 0.);
            }
        }
        forn (i, n) {
            f[a[i]][b[i]] += cd(1., 0.);
        }
        convert(1.);
        forn (i, MAXN) {
            forn (j, MAXN) {
                f[i][j] *= f[i][j];
            }
        }
        convert(-1.);
        memset(val, 0, sizeof(val));
        forn (i, MAXN) {
            forn (j, MAXN) {
                val[i][j] = int(f[i][j].real() / ld(MAXN) / ld(MAXN) + 0.5);
            }
        }
        forn (i, n) {
            val[2 * a[i]][2 * b[i]]--;
        }
        forn (i, MAXN) {
            forn (j, MAXN) {
                if (val[i][j]) {
                    debug(i, j, val[i][j] / 2.);
                }
            }
        }
        ans = 0;
        forn (i, MAXN) {
            forn (j, MAXN) {
                if (val[i][j]) {
                    ans = (ans + 1ll * val[i][j] / 2 * cc(i, j)) % MOD;
                }
            }
        }
        }

        void clear () {
                *this = Solution();
        }
};

