/*
发现a[i]和b[i]很小,是可以O(n^2)的范围

C(x+y,x)可以看作是(0,0)到(x,y)的方案数,
如果我们要求(0,0)到(x,y)的方案数,
可以令d[i][j]表示(0,0)到(i,j)的方案数,一开始d[0][0]=1.
转移方程为d[i][j]=d[i-1][j]+d[i][j-1].

C(a[i]+a[j]+b[i]+b[j],a[i]+a[j])可以看作:
(0,0)到(a[i]+a[j],b[i]+b[j])的方案数.

枚举i和j是O(n^2)的,显然要优化,
尝试将i和j分开:
将坐标位移一下变为(-a[i],-b[i])到(a[j],b[j])的方案数.
这样i和j就分离了,然后就可以单独计算每个部分的贡献.

观察前面的dp方程,我们一开始令d[0][0]=1,
然后计算出的d[x][y]就是(0,0)到(x,y)的方案数,
那么我们令d[-a[i]][-b[i]]=1,
那么计算出的d[x][y]就是(-a[i],-b[i])到(x,y)的方案数.
这样的话,我们一开始只需要令所有的d[-a[i]][-b[i]]++,
那么计算出来的d[x][y]就是所有数对到达(x,y)的方案数.
因此最后只需要累加d[a[i]][b[i]]即可.
但是存在(-a[i],-b[i])到(a[i],b[i])的方案数,也就是自己和自己匹配,
而题目只需要计算i<j的,因此减掉自己和自己匹配的,方案数为C(2*(a[i]+b[i]),2*a[i]).
最后答案还要再除以2,因为是计算出的是无序的,题目要的是有序的.

参考:
https://www.luogu.com.cn/blog/Ebola-Emperor/solution-at1983
https://www.luogu.com.cn/blog/208529/solution-at1983
*/

#include <bits/stdc++.h>
using namespace std;
const int MAXV = 2005;
const int MAXN = 200005;
const long long int MOD = 1000000007;
int dp[2*MAXV][2*MAXV], a[MAXN], b[MAXN];
long long int fact[MAXN], invf[MAXN];
long long int ncr(int n, int r)
{
	if(n < r)
		return 0;
	long long int ans = (fact[n]*invf[r])%MOD;
	ans = (ans*invf[n-r])%MOD;
	return ans;
}
long long int power(long long int a, int b)
{
	if(!b)
		return 1;
	long long int ans = power(a, b/2);
	ans = (ans*ans)%MOD;
	if(b%2)
		ans = (ans*a)%MOD;
	return ans;
}
int main()
{
	fact[0] = invf[0] = 1;
	for (int i = 1; i < MAXN; ++i)
	{
		fact[i] = (fact[i-1]*i)%MOD;
		invf[i] = power(fact[i],MOD-2);
	}
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; ++i)
	{
		scanf("%d %d", &a[i], &b[i]);
		dp[MAXV - a[i]][MAXV - b[i]]++;
	}
	for (int i = 1; i < 2*MAXV; ++i)
	{
		for (int j = 1; j < 2*MAXV; ++j)
		{
			dp[i][j] = dp[i][j] + dp[i-1][j] + dp[i][j-1];
			while(dp[i][j] >= MOD)
				dp[i][j]-=MOD;
		}
	}
	long long int ans = 0;
	for (int i = 0; i < n; ++i)
	{
		ans = (ans + dp[MAXV + a[i]][MAXV + b[i]])%MOD;
		ans = (ans + MOD - ncr(2*(a[i] + b[i]),2*b[i]))%MOD;
	}
	ans = (ans*invf[2])%MOD;
	printf("%lld\n", ans);
	return 0;
}

