int hcnt[4010];

typedef long long ll;

ll modpow(ll a, ll n, ll mod) {
	ll ret = 1;
	while (n) {
		if (n % 2)
			ret = (ret * a) % mod;
		a = (a * a) % mod;
		n /= 2;
	}
	return ret;
}

ll modinv(ll r) {
	return modpow(r, MOD - 2, MOD);
}

void proc() {
	scanf("%d", &n);
	for (int i = 0; i < n; ++i) {
		scanf("%d %d", &a[i], &b[i]);
		hcnt[a[i] + b[i]] += 1;
	}

	comb[0][0] = 1;
	for (int i = 1; i <= 8000; ++i) {
		comb[i][0] = 1;
		if (i <= 4010) {
			comb[i][i] = 1;
		}
		for (int j = 1; j < i && j <= 4010; ++j) {
			comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
		}
	}

	long long ans = 0;
	for (int h0 = 2; h0 <= 4000; ++h0) {
		if (hcnt[h0] == 0) {
			continue;
		}

		for (int hj = 2; hj <= 4000; ++hj) {
			if (hcnt[hj] == 0) {
				continue;
			}

			long long cnt = 0;
			if (hj != h0) {
				cnt = (long long)hcnt[hj] * hcnt[h0] % MOD;
			}
			else {
				cnt = (long long)hcnt[hj] * hcnt[h0] % MOD;
				cnt = (((cnt - hcnt[hj]) % MOD) + MOD) % MOD;
			}

			ans = (ans + ((cnt * comb[hj + h0][h0]) % MOD)) % MOD;
		}
	}
	printf("%lld", (long long)ans * modinv(2) % MOD);
}

