            ans+=(conbination_cal(niku[i]+niku[j]+yasai[i]+yasai[j],min(niku[i]+niku[j],yasai[i]+yasai[j])));
            ans=ans%MOD;
        }
    }
    cout << ans;

    return 0;
}
long long int conbination_cal(long long int a,long long int b){
    long long int bunbo=1,bunshi=1;
    for(int i=1;i<=a;i++){
        bunshi*=i;
        bunshi=bunshi%MOD;
    }
    for(int j=1;j<=b;j++){
        bunbo*=j;
        bunbo=bunbo%MOD;
    }
    for(int k=1;k<=a-b;k++){
        bunbo*=k;
        bunbo=bunbo%MOD;
    }
    for(int i=0;i<MOD;i++){
        if((i*bunbo%MOD)==bunshi)return i;
    }
    return -1;
}

