const int MAXN = 2e5+1;
const int MAXM = 4002;
const int ZERO = 2001;
const int mo = 1e9+7;
int F[MAXM][MAXM];
int fac[MAXM<<1], env[MAXM<<1];
int x[MAXN], y[MAXN];
typedef long long LL;
int pow(int x, int y)
{
	int res = 1;
	while (y)
	{
		if(y&1) res = LL(res) * x % mo;
		x = LL(x) * x % mo;
		y >>= 1;
	}
	return res;
}
void init()
{
	fac[0] = env[0] = 1;
	for(int i=1; i<MAXM<<1; ++i)
	{
		fac[i] = LL(fac[i-1]) * i % mo;
		env[i] = pow(fac[i], mo-2);
	}
}
#define C(n,m) (LL(fac[(n)]) * env[(m)] % mo * env[(n)-(m)])
int main()
{
	init();
	int N, i, j;
	scanf("%d", &N);
	for(i=0; i<N; ++i)
	{
		scanf("%d%d", x+i, y+i);
		++F[ZERO-x[i]][ZERO-y[i]];
	}
	for(i=1; i<MAXM; ++i)
		for(j=1; j<MAXM; ++j)
			F[i][j] = (F[i][j] + F[i][j-1] + F[i-1][j]) % mo;
	int ans = 0;
	for(i=0; i<N; ++i)
	{
		ans = (ans + F[ZERO+x[i]][ZERO+y[i]]) % mo;
		ans = (ans - C((x[i]+y[i])<<1,x[i]<<1)) % mo;
	}
	ans = LL(ans) * pow(2, mo-2) % mo;
	printf("%d\n", (ans + mo) % mo);
}

