#include <bits/stdc++.h>

const int N = 200000 + 10, S = 4000 + 10, M = 1e9 + 7;

int dp[S][S], C[S][S];
int A[N], B[N];
int n;

void run() {
  std::cin >> n;
  for (int i = 0; i < n; ++i) {
    std::cin >> A[i] >> B[i];
    dp[-A[i] + 2000][-B[i] + 2000] += 1;
    dp[A[i] + 2000][B[i] + 2000] -= 1;
  }
  for (int i = 0; i < S; ++i) {
    for (int j = 0; j < S; ++j) {
      if (!i && !j) C[i][j] = 1;
      else {
        if (i) C[i][j] += C[i - 1][j];
        if (j) C[i][j] += C[i][j - 1];
        C[i][j] %= M;
      }
    }
  }
  int ret = 0;
  for (int i = 0; i < S; ++i) {
    for (int j = 0; j < S; ++j) {
      int now = 0;
      if (i) now += dp[i - 1][j];
      if (j) now += dp[i][j - 1];
      if (dp[i][j] < 0) {
        ret += 1ll * now * (-dp[i][j]) % M;
        dp[i][j] = now % M;
        ret %= M;
      }
      else dp[i][j] = (dp[i][j] + now % M) % M;
    }
  }
  for (int i = 0; i < n; ++i) {
    ret -= C[A[i] * 2][B[i] * 2];
    ret += M;
    ret %= M;
  }
  ret = ret * 500000004ll % M;
  std::cout << ret << std::endl;
}

int main() {
  run();
  return 0;
}

