ll fact[M+5],inv[M+5];
void Init(){
    fact[0]=1;
    for(ll i=1;i<M;i++)
        fact[i]=(1ll*fact[i-1]*i)%mod;
    inv[1]=1;
    for(ll i=2;i<M;i++)
        inv[i]=1ll*(mod-mod/i)*inv[mod%i]%mod;
    inv[0]=1;
    for(ll i=1;i<M;i++)
        inv[i]=1ll*inv[i]*inv[i-1]%mod;
}
ll C(ll x,ll y){
    return 1ll*fact[x]*inv[y]%mod*inv[x-y]%mod;
}
int main()
{
    //freopen("bbq4.in","r",stdin);
