		for(int j=MAXN-1; j>=1; j--) {
		table[i][j] %= MOD;
		table[i][j-1] += table[i][j];
		table[i-1][j] += table[i][j];
	}

	for(int i=-P; i<P; i++) {
		ans += table[P+i][P-i] * table[P-i][P+i] % MOD;
	}
	ans %= MOD;
	ans = mod_frac(ans, 2);
	cout << ans << endl;

	return 0;
}

