  auto fft2D = [&](bool inv = false) -> void {
    for (int i = 0; i < N; i += 2) {
      if (inv) {
        fft(c[i], true);
        fft(c[i + 1], true);
      } else {
        fftR2(c[i], c[i + 1]);
      }
    }
    for (int j = 0; j < N; ++j) for (int i = 0; i < j; ++i) {
      swap(c[i][j], c[j][i]);
    }
