const int N = 4096;
const int BITS = 12;

int bit_reversal[N];

void precompute_bit_reversal() {
    for (int i = 1; i < N; ++ i)
        bit_reversal[i] = (bit_reversal[i >> 1] >> 1) + (i & 1) * (1 << (BITS - 1));
}

//typedef complex <double> Point;
class Point {
public:
    double r, i;

    Point(double _r = 0, double _i = 0):
        r(_r), i(_i) {}

    Point operator+(const Point &arg) const {
        return Point(r + arg.r, i + arg.i);
    }
    Point operator-(const Point &arg) const {
        return Point(r - arg.r, i - arg.i);
    }
    Point operator*(const Point &arg) const {
        return Point(r * arg.r - i * arg.i, r * arg.i + i * arg.r);
    }
    Point operator/(const int &arg) const {
        return Point(r / arg, i / arg);
    }
};

const double PI = acos(-1);

void fft(Point v[N][N], bool reverse = false) {
    //Apply bit reversal
    for (int i = 0; i < N; ++ i)
        for (int j = 0; j < N; ++ j)
            if (i < bit_reversal[i] || (i == bit_reversal[i] && j < bit_reversal[j]))
                swap(v[i][j], v[bit_reversal[i]][bit_reversal[j]]);

    for (int len = 2; len <= N; len *= 2) {
        Point w = Point(cos(2 * PI / len), (1 - 2 * reverse) * sin(2 * PI / len));

        for (int i = 0; i < N; i += len)
            for (int j = 0; j < N; j += len) {
                Point wk = Point(1);
                for (int k = 0; k < len / 2; ++ k) {
                    Point wl = Point(1);
                    for (int l = 0; l < len / 2; ++ l) {
                        Point p00 = v[i + k][j + l];
                        Point p01 = wl * v[i + k][j + l + len / 2];
                        Point p10 = wk * v[i + k + len / 2][j + l];
                        Point p11 = wk * wl * v[i + k + len / 2][j + l + len / 2];

                        v[i + k][j + l]                     = p00 + p01 + p10 + p11;
                        v[i + k][j + l + len / 2]           = p00 - p01 + p10 - p11;
                        v[i + k + len / 2][j + l]           = p00 + p01 - p10 - p11;
                        v[i + k + len / 2][j + l + len / 2] = p00 - p01 - p10 + p11;

                        wl = wl * w;
                    }

                    wk = wk * w;
                }
            }
    }

    if (reverse)
        for (int i = 0; i < N; ++ i)
            for (int j = 0; j < N; ++ j)
                v[i][j] = v[i][j] / (N * N);
}

void copy(Point dest[N][N], lint source[N][N]) {
    for (int i = 0; i < N; ++ i)
        for (int j = 0; j < N; ++ j)
            dest[i][j] = Point(source[i][j]);
}

void copy(lint dest[N][N], Point source[N][N]) {
    for (int i = 0; i < N; ++ i)
        for (int j = 0; j < N; ++ j)
            dest[i][j] = source[i][j].r + 0.5;
}

