    copy(mat2, mat);

    fft(mat2);

    for (int i = 0; i < N; ++ i)
        for (int j = 0; j < N; ++ j)
            mat2[i][j] = mat2[i][j] * mat2[i][j];

    fft(mat2, true);

    copy(mat, mat2);
}

const int MOD = 1000000000 + 7;

int comb[2 * N][N];

void precalc_comb() {
    for (int i = 0; i < 2 * N; ++ i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i && j < N; ++ j) {
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
            if (comb[i][j] >= MOD)
                comb[i][j] -= MOD;
        }
    }
}

