const int MOD = 1000000007;

long long modPow(int a, int p){
	if(p == 0) return 1;
	if(p == 1) return a;
	long long res = modPow(a, p/2);
	res = res*res;
	res %= MOD;
	if(p%2 == 1) res = (res * a) % MOD;
	return res;
}

