        C[i][0] = 1;
        for(int j = 1; j <= i; j++) C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
    }
    for(int i = 1; i <= n; i++) {
        scanf("%d%d", &a, &b);
        ans += P - C[a + a + b + b][a + a];
