	for(int i = maxn - 2; i >= 0; i--) ifat[i] = mul(ifat[i + 1], i + 1);
}
int coef(int n, int k){
	if(n < k) return 0;
	return mul(fat[n], mul(ifat[k], ifat[n - k]));
}
