    for(int i=0; i<n; ++i){
        cin >> a[i] >> b[i];
        ++ cnt[MAX-a[i]][MAX-b[i]];
        ++ cnt[MAX+a[i]][MAX+b[i]];
    }

    long long ans = 0;
    vector<vector<int> > dp(2*MAX+2, vector<int>(2*MAX+2, 0));
    for(int y=0; y<=2*MAX; ++y){
        for(int x=0; x<=2*MAX; ++x){
            if(x < MAX){
                dp[y][x] += cnt[y][x];
                dp[y][x] %= MOD;
            }
            else{
                ans += dp[y][x] * (long long)cnt[y][x];
                ans %= MOD;
            }

            dp[y+1][x] += dp[y][x];
            dp[y+1][x] %= MOD;
            dp[y][x+1] += dp[y][x];
            dp[y][x+1] %= MOD;
        }
    }

    for(int i=0; i<n; ++i){
        ans += MOD - comb[2*(a[i]+b[i])][2*a[i]];
        ans %= MOD;
    }
    ans *= MOD_INV2;
    ans %= MOD;
    cout << ans << endl;

    return 0;
}

