inline int MOD(int x) {
	return x >= mod ? x - mod : x;
}
int qpow(int a, int b) {
	int as = 1;
	while(b) {
		if(b & 1) as = 1ll * as * a % mod;
		a = 1ll * a * a % mod;
		b >>= 1;
	}
	return as;
}
int a[200005], b[200005], CC[4005][4005];
int n, m;
int F[10005], fc[10005], iv[10005], G[10005];
