	return G[x + 3000];
}
int as;
int C(int n, int m) {
	return CC[n][m];
}
int CCC(int n, int m) {
	return 1ll * fc[n] * iv[m] % mod * iv[n - m] % mod;
}
void init() {
	CC[0][0] = 1;
	rep(i, 1, 4000) {
		CC[i][0] = CC[i][i] = 1;
		rop(j, 1, i) {
			CC[i][j] = MOD(CC[i - 1][j - 1] + CC[i - 1][j]);
		}
	}
	fc[0] = iv[0] = 1;
	rep(i, 1, 10000) fc[i] = 1ll * fc[i - 1] * i % mod;
	iv[10000] = qpow(fc[10000], mod - 2);
	per(i, 9999, 1) iv[i] = 1ll * iv[i + 1] * (i + 1) % mod;
}
