#include <bits/stdc++.h>

using namespace std;

typedef unsigned long long ull; //must be unsigned to prevent overflow

vector<ull> wws(1<<23);

/**
 * Tested on icpc.kattis.com/problems/tiles
 * Finite field fft
 * Size must be a power of 2 <= 2^30
 * Outputs must be < 3*2^30 + 1
 * Inverse transform will rescale correctly
 * Remember to pad N zeros at the end for convolution to work
 */
void fft(vector<ull>& arr, bool invert = false) {
  const ull P = 3 * (1ULL << 30) + 1;
  const ull ROOT = 5, INV_ROOT = 1932735284;
  const ull TWO_INV = 1610612737; // inverse of 2 (mod P)
  const int N = arr.size();
  for (int i = 1, j = 0; i < N; i++) {
    int bit = N >> 1;
    for (; j >= bit; bit >>= 1)
      j -= bit;
    j += bit;
    if (i < j) swap(arr[i], arr[j]);
  }
  for (int half = 1; half < N; half <<= 1) {
    ull wm = invert ? INV_ROOT : ROOT;
    wm = (((wm * wm) % P) * wm) % P;
    for (int ord = (P - 1) / 3; ord > 2 * half; ord >>= 1)
      wm = (wm * wm) % P;

  wws[0]=1;
  for(int i=1; i<half; i++)
    wws[i]=wws[i-1]*wm%P;

    for (int st = 0; st < N; st += 2 * half) {
      int ptr=0;
      for (int j = st; j < st + half; ++j) {
        ull temp = (wws[ptr++] * arr[j + half]);
        if(temp >= P)
            temp %= P;
        if(arr[j] < temp)
            arr[j + half] = arr[j] + P - temp;
        else
            arr[j + half] = arr[j] - temp;
        arr[j] = (arr[j] + temp);
        if(arr[j] >= P)
            arr[j] -= P;
      }
    }
  }
  if (invert) {
    ull size_inv = 1;
    for (int sz = 2; sz <= N; sz <<= 1)
      size_inv = (size_inv * TWO_INV) % P;
    for (ull& x : arr)
      x = (x * size_inv) % P;
  }
}

