		fac[i] = (fac[i - 1] * i) % M;
	inv[N - lg] = pw(fac[N - lg], M - 2);
	for(int i = N - lg - 1; i > -1; i--) 
		inv[i] = (inv[i + 1] * (i + 1)) % M;
}

int c(int x, int y) {
	return ((fac[x] * inv[y] % M) * inv[x - y]) % M;
}

int32_t main() {
	use_fast;
	prepro();
	int n, cnt = 0;
	cin >> n;
	for(int i =0; i < n; i++) {
		int x, y;
		cin >> x >> y;
		cnt -= c(2 * (x + y), 2 * x);
		cnt = (cnt % M + M) % M;
		is[-x + 2500][-y + 2500]++;
		it[x + 2500][y + 2500]++;
	}
	for(int i = 1; i <= 4550; i++) {
		for(int j = 1; j <= 4550; j++) {
			dp[i][j] = (dp[i - 1][j] + dp[i][j - 1] + is[i][j]) % M;		
			cnt = (cnt + dp[i][j] * it[i][j]) % M;
		}
	}
	cnt = (cnt * pw(2, M - 2)) % M;
	cout << cnt << endl;
	return 0;
}
