signed a[MAXN];
signed b[MAXN];
float ab[MAXSIZE];

int binpow(int a, int b, int mo) {
  int ans = 1;
  do {
    if (b & 1) ans = 1ll * ans * a % mo;
    a = 1ll * a * a % mo;
  } while (b >>= 1);
  return ans;
}

const int FACTSIZE = 10100;
int fact[FACTSIZE];
int revfact[FACTSIZE];

int ncr(int n, int r) {
  if (n < r) return 0;
  int rs = fact[n] * revfact[r];
  if (rs >= MOD) rs %= MOD;
  rs *= revfact[n - r];
  if (rs >= MOD) rs %= MOD;
  return rs;
}
void init() {
  fact[0] = 1, revfact[0] = 1;
  for (int i = 1; i < FACTSIZE; ++i) {
    fact[i] = fact[i - 1] * i % MOD;
    revfact[i] = binpow(fact[i], MOD - 2, MOD);
  }
}
signed ip[10000];
float w[(MAXSIZE / 4)];

void convolve2(float *a, signed n) {
  signed s = n + n - 1;  // 畳み込み結果のサイズ
  signed t = 1;          // FFT に使う配列のサイズ（2 の累乗）
  while (t < s) t *= 2;
  ip[0] = 0;
  cdft(2 * t, 1, a, ip, w);
  for (signed i = 0; i < t; i++) {
    signed addr = 2 * i;
    float tmpa = a[addr];
    a[addr] = a[addr] * a[addr] - a[addr + 1] * a[addr + 1];
    a[addr + 1] = 2 * tmpa * a[addr + 1];
  }
  cdft(2 * t, -1, a, ip, w);
  for (signed j = 0; j < t; j++) {
    a[j * 2] *= 1.0 / t;
    a[j] = a[j * 2];
  }
}

signed N;
signed main() {
  init();
  cin.tie(0), ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int N;
  cin >> N;

  signed maxV = 0;
  REP(i, N) {
    cin >> a[i] >> b[i];
    chmax(maxV, a[i]);
    chmax(maxV, b[i]);
  }
  maxV *= 2;
  maxV += 1;

  int maxAB = 0;
  REP(i, N) {
    int val = a[i] * maxV + b[i];
    ab[2 * val]++;
    chmax(maxAB, val);
  }
  maxAB++;
  convolve2(ab, maxAB);
  int ans = 0;
  int maxV2 = maxV * maxV;
  // DUMP(maxAB, maxV2);
  REP(i, maxV2) {
    int i0 = i / maxV;
    int i1 = i % maxV;
    int val = round(ab[i]);
    ans += val * ncr(i0 + i1, i0);
    ans %= MOD;
  }
