const int N = 200 * 1000 + 5, A = 2005;
const int mod = 1000 * 1000 * 1000 + 7;

long long dp[2 * A][2 * A];
long long gl[2 * A][2 * A];
long long fac[4 * A];
int po(int x, int y) {
	if (y == 0)
		return 1;
	long long ans = po(x, y / 2);
	ans *= ans;
	ans %= mod;
	if (y % 2 == 1) {
		ans *= x;
		ans %= mod;
	}
	return ans;
}
long long chs(int x, int y) {
	long long ans = fac[x];
	ans *= po(fac[y], mod - 2);
	ans %= mod;
	ans *= po(fac[x - y], mod - 2);
	ans %= mod;
	return ans;
}
int main() {
	fac[0] = 1;
	for (int i = 1; i < 2 * A; i++) {
		fac[i] = fac[i - 1] * i;
		fac[i] %= mod;
	}
	int n;
	cin >> n;
	long long ans = 0;
	for (int i = 1; i <= n; i++) {
		int x, y;
		cin >> x >> y;
		dp[A - x][A - y]++;
		gl[x + A][y + A]++;
		ans -= chs(2 * x + 2 * y, 2 * x);
		ans += mod;
		ans %= mod;
	}
	for (int i = 1; i < 2 * A; i++) {
		for (int j = 1; j < 2 * A; j++) {
			dp[i][j] += dp[i - 1][j];
			dp[i][j] %= mod;
			dp[i][j] += dp[i][j - 1];
			dp[i][j] %= mod;
			ans += 1ll * dp[i][j] * gl[i][j];
			ans %= mod;
		}
	}
	ans *= po(2, mod - 2);
	ans %= mod;
	cout << ans << endl;
	return 0;
}

