int dp[8001][8001];

int choose(int a, int b)
{
	if(a < b) return 0;
	if(dp[a][b] != -1) return dp[a][b];
	if(b == 0) return 1;
	if(b == 1) return a;
	dp[a][b] = (ll(choose(a - 1, b)) + ll(choose(a - 1, b - 1)))%MOD;
	return dp[a][b];
}

ll modpow(ll a, ll b)
{
	ll r = 1;
	while(b)
	{
		if(b&1) r = (r*a)%MOD;
		a = (a*a)%MOD;
		b>>=1;
	}
	return r;
}

