int64 power_mod(int64 a, int n) {
  int64 ret = 1;
  for (; n; n >>= 1) {
    if (n & 1) ret = ret * a % MOD;
    a = a * a % MOD;
  }
  return ret;
}

int64 inv_mod(int64 a) {
  return power_mod(a, MOD - 2);
}

int comb(int n, int m) {
  return (int64)F[n] * inv_mod(F[m]) % MOD * inv_mod(F[n - m]) % MOD;
