int dp[T][T];
int cnt[T][T];
int k[2 * T];
int n;
int mod = 1e9 + 7;

int binpow(int a, int p)
{
    if (p == 1)
        return a;
    int b = binpow(a, p / 2);
    b = (b * b) % mod;
    if (p % 2)
        b = (b * a) % mod;
    return b;
}

int divide(int a, int b)
{
    return (a * binpow(b, mod - 2)) % mod;
}

signed main()
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    k[0] = 1;
    for (int i = 1; i < T; i++)
        k[i] = (k[i - 1] * i) % mod;
    cin >> n;
    int ans = 0;
    for (int i = 0; i < n; i++)
    {
        int a, b;
        cin >> a >> b;
        cnt[a + T / 2][b + T / 2]++;
        cnt[-a + T / 2][-b + T / 2]++;
        ans -= divide(k[2 * (a + b)], (k[2 * a] * k[2 * b]) % mod);
        if (ans < 0)
            ans += mod;
    }
    for (int i = 0; i < T; i++)
    {
        dp[0][i] = 0;
        dp[i][0] = 0;
    }
    for (int i = 1; i < T; i++)
    {
        for (int e = 1; e < T; e++)
        {
            dp[i][e] = dp[i - 1][e] + dp[i][e - 1];
            if (dp[i][e] >= mod)
                dp[i][e] -= mod;
            if (i > T / 2 && e > T / 2)
                ans = (ans + dp[i][e] * cnt[i][e]) % mod;
            else
            {
                dp[i][e] += cnt[i][e];
                if (dp[i][e] >= mod)
                    dp[i][e] -= mod;
            }
        }
    }
    if (ans % 2)
        ans += mod;
    ans /= 2;
    cout << ans;
}

