const int ZERO = MAXM / 2;

int fpow(int x, int p)
{
	int ret = 1;
	for(; p; p >>= 1, x = (long long)x * x % MOD)
		if(p & 1)
			ret = (long long)ret * x % MOD;
	return ret;
}

int get_inv(int x)
{
	return fpow(x, MOD - 2);
}

int fac[2 * MAXM], inv[2 * MAXM];
int get_c(int n, int m)
{
	return (long long)fac[n] * inv[m] % MOD * inv[n - m] % MOD;
}

void init()
{
	fac[0] = 1;
	for(int i = 1; i < 2 * MAXM; i++)
		fac[i] = (long long)fac[i - 1] * i % MOD;
	for(int i = 0; i < 2 * MAXM; i++)
		inv[i] = get_inv(fac[i]);
}

int n, m;
int a[MAXN], b[MAXN];
int f[MAXM][MAXM];

int& dp(int x, int y)
{
	return f[x + ZERO][y + ZERO];
}

