		m = max(m, a[i]), m = max(m, b[i]);
	for(int i = 1; i <= n; i++)
		dp(-a[i], -b[i]) += 1;
	for(int i = -m; i <= m; i++)
		for(int j = -m; j <= m; j++)
			dp(i, j) = ((long long)dp(i, j) + dp(i, j - 1) + dp(i - 1, j)) % MOD;
	int ans = 0;
	for(int i = 1; i <= n; i++)
		ans = (ans + dp(a[i], b[i])) % MOD;
	// cerr << ans << endl;
	for(int i = 1; i <= n; i++)
		ans = (ans - get_c(2 * a[i] + 2 * b[i], 2 * a[i]) + MOD) % MOD;
	// cerr << ans << endl;
	ans = (long long)ans * get_inv(2) % MOD;

	cout << ans << endl;

	return 0;
}

