const int MAXN = 4096;

cd f[MAXN][MAXN];

int power(int x, int st, int mod) {
    int res = 1;
    while (st) {
        if (st & 1) {
            res = 1ll * res * x % mod;
        }
        st /= 2;
        x = 1ll * x * x % mod;
    }
    return res;
}


inline int inv(int x, int mod) {
    return power(x, mod - 2, mod);
}

const int FFT_MOD = 7340033;
const int ROOT_2_20 = 5;
int ROOT_2_12 = power(ROOT_2_20, 256, FFT_MOD);

void add(int &dst, int src) {
    dst += src;
    while (dst < 0) dst += FFT_MOD;
    while (dst >= FFT_MOD) dst -= FFT_MOD;
}

// fft using merge
void
global_fft(int mult = 1)
{
    int n = MAXN;
    int k = 12;

    vi rev(n / 2);
    rev[0] = 0;
    int high1 = -1;
    for (int i = 1; i < n; ++i) {
        if ((i & (i - 1)) == 0) {
            high1++;
        }
        int trev = rev[i ^ (1 << high1)] | (1 << (k - high1 - 1));
        if (trev > i) {
            forn (j, n) {
                swap(f[i][j], f[trev][j]);
            }
        }
        if (i < n / 2) {
            rev[i] = trev;
        }
    }

    vcd roots(k);
    roots[0] = ROOT_2_12;
    if (mult == -1) {
        roots[0] = inv(roots[0], FFT_MOD);
    }
    for (int i = 1; i < k; ++i) {
        roots[i] = 1ll * roots[i - 1] * roots[i - 1] % FFT_MOD;
    }

    for (int len = 1, it = k - 1; len < n; len <<= 1, --it) {
        cd mult1 = roots[it];
        for (int pdest = 0; pdest < n; pdest += len) {
            cd mult2 = 1;
            for (int i = 0; i < len; ++i, ++pdest) {
                forn (j, n) {
                    cd val = 1ll * mult2 * f[pdest + len][j] % FFT_MOD;
                    f[pdest + len][j] = f[pdest][j];
                    add(f[pdest + len][j], -val);
                    add(f[pdest][j], val);
                }
                mult2 = 1ll * mult2 * mult1 % FFT_MOD;
            }
        }
    }
}

// fft using merge
void
global_fft_tr(int mult = 1)
{
    int n = MAXN;
    int k = 12;

    vi rev(n / 2);
    rev[0] = 0;
    int high1 = -1;
    for (int i = 1; i < n; ++i) {
        if ((i & (i - 1)) == 0) {
            high1++;
        }
        int trev = rev[i ^ (1 << high1)] | (1 << (k - high1 - 1));
        if (trev > i) {
            forn (j, n) {
                swap(f[j][i], f[j][trev]);
            }
        }
        if (i < n / 2) {
            rev[i] = trev;
        }
    }

    vcd roots(k);
    roots[0] = ROOT_2_12;
    if (mult == -1) {
        roots[0] = inv(roots[0], FFT_MOD);
    }
    for (int i = 1; i < k; ++i) {
        roots[i] = 1ll * roots[i - 1] * roots[i - 1] % FFT_MOD;
    }

    forn (j, n) {
        for (int len = 1, it = k - 1; len < n; len <<= 1, --it) {
            cd mult1 = roots[it];
            for (int pdest = 0; pdest < n; pdest += len) {
                cd mult2 = 1;
                for (int i = 0; i < len; ++i, ++pdest) {
                    cd val = 1ll * mult2 * f[j][pdest + len] % FFT_MOD;
                    f[j][pdest + len] = f[j][pdest];
                    add(f[j][pdest + len], -val);
                    add(f[j][pdest], val);
                    mult2 = 1ll * mult2 * mult1 % FFT_MOD;
                }
            }
        }
    }
}

