const int MOD = 1e9 + 7;
const int N = 8000+50;
const int offset = 2000 + 10;

LL quick_inverse(LL n) {
	LL ret = 1;
	int exponent = MOD - 2;
	for (int i = exponent; i; i >>= 1, n = n * n % MOD) {
		if (i & 1) {
			ret = ret * n % MOD;
		}
	}
	return ret;
}

LL invf[N], factor[N];
void get_factorial_inverse(int n) {
	factor[0] = 1;
	for (int i = 1; i <= n; ++i) {
		factor[i] = i * factor[i - 1] % MOD;
	}
	invf[n] = quick_inverse(factor[n]);
	for (int i = n-1; i >= 0; --i) {
		invf[i] = invf[i + 1] * (i + 1) % MOD;
	}
}

int A[200010], B[200010];

LL Map[offset*2+10][offset*2+10];
bool vis[offset*2+10][offset*2+10];

LL calc_x(int n)
{
    LL ans = 0;
    int max_range = 0;
    for (int i=1; i<=n; i++)
    {
        Map[offset + A[i]][offset + B[i]]++;
        Map[offset - A[i]][offset - B[i]]++;
        max_range = max(max_range, A[i]);
        max_range = max(max_range, B[i]);
    }
    queue<pii> q;
    q.push(pii(offset + max_range, offset + max_range));
    vis[offset + max_range][offset + max_range] = true;
    while(!q.empty())
    {
        pii node = q.front(); q.pop();
        int x = node.first, y = node.second;
        if (x < offset && y < offset && Map[x][y])
        {
            LL times = Map[x][y];
            Map[x][y] = (Map[x+1][y] + Map[x][y+1]) % MOD;
            ans += (times * Map[x][y]) % MOD;
        }
        else
        {
            if (x < offset + max_range) Map[x][y] += Map[x+1][y];
            if (y < offset + max_range) Map[x][y] += Map[x][y+1];
            Map[x][y] %= MOD;
        }
        if (x > offset - max_range && !vis[x-1][y])
