long long int conbination_cal(long long int a,long long int b){
    long long int bunbo=1,bunshi=1;
    bool flag=false;
    for(int i=1;i<=b;i++){
        bunbo*=i;
        if(bunbo>MOD){
            flag=true;
            bunbo=bunbo%MOD;
        }
    }
    for(int i=a-b+1;i<=a;i++){
        bunshi*=i;
        if(bunshi>MOD){
            flag=true;
            bunshi=bunshi%MOD;
        }
    }
    if(!flag){
        return bunshi/bunbo;
    } else {
        for(int i=0;i<MOD;i++){
            if((i*bunbo%MOD)==bunshi){
                return i;
            }
        }
    }

    return -1;
}

