    for (int i=0;i<N;++i) cin >> A[i] >> B[i],C[i]=A[i]+B[i];

    mint ans=0;
    for (int i=0;i<N;++i) ans-=COM.C(2*C[i],2*A[i]);

    vector<mint> dp(2*MAX_A,0);
    vector<vector<int>> f(2*MAX_A);
