        for (int j:f[i]) dp[j]+=1;
        for (int j=2*MAX_A-2;j>=0;--j) dp[j+1]+=dp[j];
    }
    for (int i=1;i<2*MAX_A-1;++i) ans+=dp[i]*dp[2*MAX_A-i];

    cout << ans/2 << '\n';
