void fft2d(){
    rep(i,0,sz/2)fft(buf[i],sz);
    rep(i,0,sz/2)rep(j,i+1,sz)swap(buf[i][j],buf[j][i]);
    rep(i,0,sz)fft(buf[i],sz);
    rep(i,0,sz)rep(j,i+1,sz)swap(buf[i][j],buf[j][i]);
    rep(i,0,sz)rep(j,0,sz)buf[i][j]=buf[i][j]*buf[i][j];
    rep(i,0,sz)rep(j,i+1,sz)swap(buf[i][j],buf[j][i]);
    rep(i,0,sz)fft(buf[i],sz,1);
    rep(i,0,sz)rep(j,i+1,sz)swap(buf[i][j],buf[j][i]);
    rep(i,0,sz)fft(buf[i],sz,1);
}

