const int N = 3e3 + 13;
const ll mod = 1e9 + 7;

int n;
pair<int, int> p[N];
ll dp[N * 2][N * 2];
ll fact[N * 10];

ll bin_pow(ll x, ll y){
	ll res = 1;
	while(y){
		if(y & 1)	
			res = res * x % mod;
		x = x * x % mod;
		y >>= 1LL;
	}
	return res;
}

ll calc(ll x, ll y){
	ll res = fact[x + y] * bin_pow(fact[x] * fact[y] % mod, mod - 2) % mod;
	return res;	
}

int main () {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);

	fact[0] = 1;
	for(ll i = 1;i < N * 10;i++){
		ll x = fact[i - 1] * i % mod;
		fact[i] = x;
	}

	cin >> n;
	for(int i = 1;i <= n;i++){
		cin >> p[i].X >> p[i].Y;
		dp[p[i].X + N][p[i].Y + N] += 1;
	}

	for(int i = 2 * N - 2;i >= 1;i--){
		for(int j = 2 * N - 2;j >= 1;j--){
			dp[i][j - 1] = (dp[i][j - 1] + dp[i][j]) % mod;
			dp[i - 1][j] = (dp[i - 1][j] + dp[i][j]) % mod;
		}
	}
	ll res = 0;
	for(int i = 1;i <= n;i++){
		res = (res + dp[N - p[i].X][N - p[i].Y]) % mod;
		res = (res - calc(p[i].X * 2, p[i].Y * 2) + mod) % mod;
	}

	//cout << calc(p[1].X + p[2].X, p[2].Y + p[1].Y) << "\n";

	res = res * bin_pow(2, mod - 2) % mod;
	cout << res;
	return 0;
}

