ll dp[Q][Q] , fac[Q] , inv[Q] , bad;

inline ll power(ll a , ll b) {
    ll res = 1;
    while(b) {
        if(b & 1) {
            res = (res * a) % mod;
        }
        a = (a * a) % mod;
        b /= 2;
    }
    return res;
}

inline ll c(ll a , ll b) {
    ll res = (fac[a] * inv[b]) % mod;
    res = (res * inv[a - b]) % mod;
    return res; 
}

int main() {
    fac[0] = inv[0] = 1;
    for (int i = 1; i < Q; ++i) {
        fac[i] = (i * fac[i - 1]) % mod;
        inv[i] = power(fac[i] , mod - 2);
    }
