    // z.resize(unique(z.begin() , z.end()) - z.begin());
    for (auto u : vec) {
        int R = u.F + u.F;
        int C = R + u.S + u.S;
        bad += c(C , R);
    }
    for (int i = 0; i < n; ++i) {
        vec[i].F += N; vec[i].S += N;
        z[i].F += N; z[i].S += N;
    }

    for (auto u : z) {
        dp[u.F][u.S]++;
    }
    for (int i = 1; i < Q; ++i) {
        for (int j = 1; j < Q; ++j) {
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
            dp[i][j] = (dp[i][j] + dp[i][j - 1]) % mod;
        }
    }
