        // cout << dp[u.F][u.S] << '\n';
        ans = (ans + dp[u.F][u.S]) % mod;
    }
    ans -= bad;
    ans += mod; ans %= mod;
    if(ans % 2) {ans += mod;}
    ans /= 2;
    cout << ans << endl;
}

