ll bin_pow(ll x, ll y){
	ll res = 1;
	while(y){
		if(y & 1)	
			res = res * x % mod;
		x = x * x % mod;
		y >>= 1LL;
	}
	return res;
}

ll calc(ll x, ll y){
	ll res = fact[x + y] * bin_pow(fact[x] * fact[y] % mod, mod - 2) % mod;
	return res;	
