#define P	1000000007
template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
int a[MAXN], b[MAXN];
int cnt[MAXN][MAXN];
int key[MAXN][MAXN];
long long fac[MAXN * 2], inv[MAXN * 2];
long long power(long long x, long long y) {
	if (y == 0) return 1;
	long long tmp = power(x, y / 2);
	if (y % 2 == 0) return tmp * tmp % P;
	else return tmp * tmp % P * x % P;
}
long long getc(int x, int y) {
	return fac[x] * inv[y] % P * inv[x - y] % P;
}
int main() {
	int N = MAXN * 2 - 1;
	fac[0] = 1;
	for (int i = 1; i <= N; i++)
		fac[i] = fac[i - 1] * i % P;
	inv[N] = power(fac[N], P - 2);
	for (int i = N - 1; i >= 0; i--)
		inv[i] = inv[i + 1] * (i + 1) % P;
	int n; read(n);
	for (int i = 1; i <= n; i++) {
		read(a[i]), read(b[i]);
		key[a[i] + DELTA][b[i] + DELTA]++;
		cnt[DELTA - a[i]][DELTA - b[i]]++;
	}
	long long ans = 0;
	for (int i = 0; i <= LIMIT; i++)
	for (int j = 0; j <= LIMIT; j++) {
		ans = (ans + (long long) key[i][j] * cnt[i][j]) % P;
		cnt[i][j + 1] = (cnt[i][j + 1] + cnt[i][j]) % P;
		cnt[i + 1][j] = (cnt[i + 1][j] + cnt[i][j]) % P;
	}
	for (int i = 1; i <= n; i++)
		ans = (ans - getc(a[i] + a[i] + b[i] + b[i], a[i] + a[i])) % P;
	ans = (ans + P) % P;
	ans = ans * power(2, P - 2) % P;
	cout << ans << endl;
	return 0;
}

