		dp[i][0] += dp[i - 1][0];
		dp[i][0] %= MOD;
	}
	for (int j = 1; j <= 4000; j++) {
		dp[0][j] += dp[0][j - 1];
		dp[0][j] %= MOD;
	}
	for (int i = 1; i <= 4000; i++) {
		for (int j = 1; j <= 4000; j++) {
			dp[i][j] += dp[i][j - 1] + dp[i - 1][j];
			dp[i][j] %= MOD;
		}
	}
	ll ans = 0;
	for (int i = 0; i < n; i++) {
		ans += dp[2000 + A[i]][2000 + B[i]];
		ans %= MOD;
	}
