void solve(){
	int n;
	scanf("%d", &n);
	REP(i, 0, n){
		scanf("%d%d", &a[i], &b[i]);
	}
	REP(i, 0, MAXV){
		c[i][0] = c[i][i] = 1;
		REP(j, 1, i){
			c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
			if (c[i][j] >= MOD){
				c[i][j] -= MOD;
			}
		}
	}
	int offset = 2000;
