constexpr int MAX = 2000;

int dp[MAX*2+1][MAX*2+1];
int frac[MAX*4+1];
int a[MAX], b[MAX];

void get_fractorial(int n) {
    ll i;
    frac[0] = 1;
    REP (i,1,n) frac[i] = frac[i-1] * i % MOD;
}

ll modpow(ll x, int n) {
    ll ret = 1;
    while (n) {
        if (n % 2)
            ret = ret * x % MOD;
        x = x * x % MOD;
        n /= 2;
    }
    return ret;
}

ll modinv(int x) {
    return modpow(x,MOD-2);
}

int main(void) {
    int i, j, n;
    scanf("%d",&n);
    REP (i,n) {
        scanf("%d%d",&a[i],&b[i]);
        dp[a[i]+MAX][b[i]+MAX]++;
    }

    RREP (i,2*MAX,0) RREP (j,2*MAX,0) {
        if (i < 2*MAX) {
            dp[i][j] += dp[i+1][j];
            dp[i][j] %= MOD;
        }
        if (j < 2*MAX) {
            dp[i][j] += dp[i][j+1];
            dp[i][j] %= MOD;
        }
    }

    get_fractorial(MAX * 4);

    int ans = 0;
    REP (i,n) ans = (ans + dp[MAX-a[i]][MAX-b[i]]) % MOD;
    REP (i,n) ans = (ans - frac[(a[i]+b[i]) * 2] * modinv((ll) frac[a[i]*2] * frac[b[i]*2] % MOD) % MOD + MOD) % MOD;
    ans = ans * modinv(2) % MOD;
    printf("%d\n",ans);
    return 0;
}

