int bin_pow(int a, int n) {
    if(n == 0) return 1;
    int b = bin_pow(a, n / 2);
    b = (b * b) % mod;
    if(n % 2 == 1) b = (b * a) % mod;
    return b;
}

void solve() {
    loop(i, MAXN * 2) loop(j, MAXN * 2) dp[i][j] = ko[i][j] = 0;
    cin >> n;
    vec<paii> p(n);
    loop(i, n) {
        int a, b;
        cin >> a >> b;
        p[i] = {a, b};
        dp[MAXN - a][MAXN - b]++;
        ko[MAXN + a][MAXN + b]++;
    }
    int ans = 0;
    loop(a, 2 * MAXN) {
        loop(b, 2 * MAXN) {
            if(a != 0) dp[a][b] += dp[a - 1][b];
            if(b != 0) dp[a][b] += dp[a][b - 1];
            dp[a][b] %= mod;
            ans = (ans + ko[a][b] * dp[a][b]) % mod;
        }
    }
    vec<int> fact(MAXN * 2, 1);
    FOR(i, 1, MAXN * 2) fact[i] = (fact[i - 1] * i) % mod;
    loop(i, n) {
        int a = 2 * p[i].fr, b = 2 * p[i].sc;
        int t = (fact[a + b] * bin_pow(fact[a], mod - 2)) % mod;
        t = (t * bin_pow(fact[b], mod - 2)) % mod;
        ans = (ans + mod - t) % mod;
    }
    ans = (ans * bin_pow(2, mod - 2)) % mod;
    cout << ans << endl;
}

