const int q=D+D+1;

int d[q][q];
int fact[q], invFact[q];
int a[MAXN+1], b[MAXN+1];

inline int lgput(int a, int n){
    int r=1;
    while(n){
        if(n%2) r=1LL*a*r%MOD;
        n/=2;
        a=1LL*a*a%MOD;
    }
    return r;
}

inline int comb(int n, int k){
    return 1LL*fact[n]*invFact[n-k]%MOD*invFact[k]%MOD;
}

int main(){
    int n;
    scanf("%d", &n);

    for(int i=1; i<=n; i++)
        scanf("%d%d", &a[i], &b[i]);

    for(int i=1; i<=n; i++)
        d[D-a[i]][D-b[i]]++;

    for(int i=1; i<=D+D; i++){
        for(int j=1; j<=D+D; j++){
            d[i][j]+=d[i-1][j]+d[i][j-1];
            if(d[i][j]>=MOD) d[i][j]-=MOD;
        }
    }

    int ans=0;
    for(int i=1; i<=n; i++){
        ans+=d[D+a[i]][D+b[i]];
        if(ans>=MOD) ans-=MOD;
    }

    fact[0]=1;
    for(int i=1; i<q; i++)
        fact[i]=1LL*fact[i-1]*i%MOD;
    invFact[q-1]=lgput(fact[q-1], MOD-2);
    for(int i=q-2; i>=0; i--)
        invFact[i]=1LL*invFact[i+1]*(i+1)%MOD;

    for(int i=1; i<=n; i++){
        ans-=comb(2*a[i]+2*b[i], 2*a[i]);
        if(ans<0) ans+=MOD;
    }

    ans=1LL*ans*lgput(2, MOD-2)%MOD;

    printf("%d\n", ans);

    return 0;
}

