    while(y){
        if (y&1) ans=ans*x%P;
        x=x*x%P;
        y>>=1;
    }
    return ans%P;
}
void Get_fac(ll n){
    fac[1]=1;
    for(ll i=2; i<=n; i++)
        fac[i]=i*fac[i-1]%P;
}
void Get_inv(ll n){
    inv[n]=pow(fac[n],P-2);
    for (ll i=n-1; i>=0; i--)
        inv[i]=inv[i+1]*(i+1)%P;
}
ll C(ll x,ll y){
    return fac[x]*inv[y]%P*inv[x-y]%P;
}
