const long long MOD = 1000000007;

long long memo[MEMOS];

long long factMod(long long n) {
    if(n == 1 || n == 2) return n;
    if(memo[n] != 0) return memo[n];
    memo[n] = n * factMod(n-1) % MOD;
    return memo[n];
    // long long ans = 1;
    // for(long long i = 2; i <= n; i++) {
    //     ans *= i;
    //     ans %= MOD;
    // }
    // return ans;
}

long long Ccount(int A, int B) {
    long long ans = factMod(A+B);
    ans /= factMod(A) * factMod(B) % MOD;
    return ans;
}

