int call (int x, int y) {
  if (x == N or y == N) return 0;
  if (~dp[x][y]) return dp[x][y];
  dp[x][y] = call(x + 1, y) + call(x, y + 1);
  if (dp[x][y] >= MOD) dp[x][y] -= MOD;
  dp[x][y] += dest[x][y];
  if (dp[x][y] >= MOD) dp[x][y] -= MOD;
  return dp[x][y];
}

int bigMod (int a, int e) {
  if (e == -1) e = MOD - 2;
  int ret = 1;
  while (e) {
    if (e & 1) ret = (long long) ret * a % MOD;
    a = (long long) a * a % MOD, e >>= 1;
  }
  return ret;
}

