using Bbq = std::pair<int, int>;

int factorial(int n) {
  static std::map<int, int> memo;
  if (n < 2) {
    return 1;
  }
  if (memo.count(n) != 0) {
    return memo[n];
  }
  int res = n * factorial(n - 1);
  memo[n] = res;
  return res;
}

int ncomb(int n, int k) {
  return factorial(n) / (factorial(n - k) * factorial(k));
}

