#include <bits/stdc++.h>

using namespace std;

typedef unsigned long long ull; //must be unsigned to prevent overflow

/**
 * Tested on icpc.kattis.com/problems/tiles
 * Finite field fft
 * Size must be a power of 2 <= 2^30
 * Outputs must be < 3*2^30 + 1
 * Inverse transform will rescale correctly
 * Remember to pad N zeros at the end for convolution to work
 */
vector<ull> fft(vector<ull>& arr, bool invert = false) {
  const ull P = 3 * (1ULL << 30) + 1;
  const ull ROOT = 5, INV_ROOT = 1932735284;
  const ull TWO_INV = 1610612737; // inverse of 2 (mod P)
  const int N = arr.size();
  for (int i = 1, j = 0; i < N; i++) {
    int bit = N >> 1;
    for (; j >= bit; bit >>= 1)
      j -= bit;
    j += bit;
    if (i < j) swap(arr[i], arr[j]);
  }
  vector<ull> ws(N);
  for (int half = 1; half < N; half <<= 1) {
    ull wm = invert ? INV_ROOT : ROOT;
    wm = (((wm * wm) % P) * wm) % P;
    for (int ord = (P - 1) / 3; ord > 2 * half; ord >>= 1)
      wm = (wm * wm) % P;

  ws[0]=1;
  for(int i=1; i<half; i++)
    ws[i]=ws[i-1]*wm%P;

    for (int st = 0; st < N; st += 2 * half) {
      ull w = 1;
      int ptr=1;
      for (int j = st; j < st + half; ++j) {
        ull temp = (w * arr[j + half]);
        if(temp >= P)
            temp %= P;
        arr[j + half] = (arr[j] + P - temp);
        if(arr[j + half] >= P)
            arr[j + half] -= P;
        arr[j] = (arr[j] + temp);
        if(arr[j] >= P)
            arr[j] -= P;
        w = ws[ptr++];
      }
    }
  }
  if (invert) {
    ull size_inv = 1;
    for (int sz = 2; sz <= N; sz <<= 1)
      size_inv = (size_inv * TWO_INV) % P;
    for (ull& x : arr)
      x = (x * size_inv) % P;
  }
  return arr;
}

const int MOD=1000000007;
int N;
int A[200001];
int B[200001];
int C[8001][4001];
int sub[4000000];

int main()
{
    vector<ull> in(1<<22);
    scanf("%d", &N);
    for(int i=0; i<N; i++)
    {
        int a, b;
        scanf("%d%d", &a, &b);
        A[i]=a-1;
        B[i]=b-1;
        int key=(a-1)*2000+(b-1);
        sub[2*key]++;
        in[key]++;
    }
    pair<int, int> maxi=make_pair(0, 0);
    for(int i=0; i<(1<<22); i++)
        maxi=max(maxi, make_pair((int)in[i], i));
    int cnt=in[maxi.second];
    in[maxi.second]=0;
    vector<ull> f=fft(in);
    for(int i=0; i<(1<<22); i++)
        f[i]=1ULL*f[i]*f[i]%(3 * (1ULL << 30) + 1);
    vector<ull> res=fft(f, true);
    int a=maxi.second/2000, b=maxi.second%2000;
    for(int i=0; i<N; i++) if(A[i]!=a || B[i]!=b)
        res[(a+A[i])*2000+(b+B[i])]+=cnt*2;
    res[2*(a*2000+b)]+=1LL*cnt*cnt%MOD;
    for(int i=0; i<=8000; i++)
    {
        C[i][0]=1;
        for(int j=1; j<=min(i, 4000); j++)
        {
            C[i][j]=C[i-1][j]+C[i-1][j-1];
            if(C[i][j]>=MOD)
                C[i][j]-=MOD;
        }
    }
    int ans=0;
    const int INV2=(MOD+1)/2;
    for(int i=0; i<4000000; i++) if(res[i])
    {
        int n=i/2000+2;
        int k=i%2000+2;
        int m=1LL*(res[i]%MOD-sub[i]+MOD)%MOD*INV2%MOD;
        ans=(ans+1LL*C[n+k][k]*m)%MOD;
    }
    printf("%d\n", ans);
    return 0;
}

