            if(c[i][j] >= MOD)
                c[i][j] -= MOD;
        }
    }
    f[0] = 1;
    for(int i = 1; i < 2 * MAXP; i++)
        f[i] = (long long)f[i - 1] * i % MOD;
    inv[1] = 1;
