vector<Int> divisors_proper(Int n) {
    if(n == 1) return {};
    vector<Int> res(1, 1);

    Int d = 2;
    for(; d*d < n; ++d) {
        if(n % d == 0) {
            res.emplace_back(d);
            res.emplace_back(n/d);
        }
    }
    if(d*d == n)
        res.emplace_back(d);

    return res;
}

vector<Int> divisors(Int n) {
    vector<Int> res = divisors_proper(n);
    res.emplace_back(n);
    return res;
}

// 素因数分解
// (素因数,指数) のリストを返す
// n >= 1 でなければならない
// n == 1 の場合、空リストを返す
vector<pair<Int,Int>> factorize(Int n) {
    ASSERT(n >= 1);

    vector<pair<Int,Int>> res;

    for(Int p = 2; p*p <= n; ++p) {
        Int e = 0;
        while(n % p == 0) {
            ++e;
            n /= p;
        }
        if(e) res.emplace_back(p, e);
    }
    if(n > 1) res.emplace_back(n, 1);

    return res;
}

