void solve() {
    Int N = RD();

    vector<Int> A(N);
    vector<Int> C(N);
    REP(i, N) {
        Int a = RD();
        Int b = RD();
        A[i] = a;
        C[i] = a + b;
    }

    using Fac = Factorial<10000>;
    ModInt Y = 0;
    REP(i, N) {
        Y += Fac::comb(2*C[i], 2*A[i]);
    }
    DBG(Y);

    Int kmax = *ALL(max_element, C);
    Int bias = *ALL(max_element, A);
    Int dim = 0;
    REP(i, N) {
        chmax(dim, C[i]-A[i]+bias);
    }
    DBG(kmax, bias, dim);

    vector<vector<ModInt>> polys(kmax+1, vector<ModInt>(dim+1,0));
    REP(i, N) {
        ++polys[C[i]][bias-A[i]];
    }
    DBG(polys);

    vector<ModInt> cur(dim+1, 0);
    for(Int k = kmax; k >= 0; --k) {
        vector<ModInt> tmp(cur);
        REP(i, dim) {
            tmp[i+1] += cur[i];
        }

        REP(i, dim+1) {
            tmp[i] += polys[k][i];
        }

        cur = tmp;
        DBG(cur);
    }

    ModInt X = 0;
    REP(i, 2*bias+1) {
        if(i > dim) break;
        if(2*bias-i > dim) continue;
        DBG(i,2*bias-i);
        X += cur[i] * cur[2*bias-i];
    }
    DBG(X);

    auto ans = (X-Y) * ModInt(2).inv();

    PRINTLN(ans);
}

signed main() {
    Int T = 1; //RD();
    LOOP(T) {
        solve();
    }

    EXIT();
}

