template<typename T> struct TPoint2D {
  T X, Y;
  TPoint2D() : X(), Y() {}
  TPoint2D(const T& x, const T& y) : X(x), Y(y) {}
  TPoint2D(const TPoint2D<T>& p) : X(p.X), Y(p.Y) {}
  TPoint2D& operator=(const TPoint2D<T>& p) { X = p.X; Y = p.Y; return *this; }
  T operator&(const TPoint2D<T>& p) const { return X * p.X + Y * p.Y; }
  T operator^(const TPoint2D<T>& p) const { return X * p.Y - Y * p.X; }
  TPoint2D conj() const { return TPoint2D(X, -Y); }
  TPoint2D<T> operator*(const TPoint2D<T>& p) const { return TPoint2D<T>(*this & p.conj(), -*this ^ p.conj()); }
  TPoint2D<T> operator*(const T& p) const { return TPoint2D<T>(p * X, p * Y); }
  TPoint2D<T> operator-(void) const { return TPoint2D(-X, -Y); }
  TPoint2D<T> operator+(const TPoint2D<T>& p) const { return TPoint2D(X + p.X, Y + p.Y); }
  TPoint2D<T> operator-(const TPoint2D<T>& p) const { return *this + (-p); }
  T norm() const { return X * X + Y * Y; }
};

typedef TPoint2D<float> base;
const int N = (1 << 23);

void fft (base* a, bool invert) {
  int n = N;
  for (int i=1, j=0; i<n; ++i) {
    int bit = n >> 1;
    for (; j>=bit; bit>>=1)
      j -= bit;
    j += bit;
    if (i < j)
      swap (a[i], a[j]);
  }
  for (int len=2; len<=n; len<<=1) {
    double ang = 2*PI/len * (invert ? -1 : 1);
    base wlen (cos(ang), sin(ang));
    for (int i=0; i<n; i+=len) {
      base w (1, 0);
      for (int j=0; j<len/2; ++j) {
        base u = a[i+j], v = a[i+j+len/2] * w;
        a[i+j] = u + v;
        a[i+j+len/2] = u - v;
//        if (j % 64 == 0) w = base(cosl(ang*j), sinl(ang*j));
        w = w*wlen;
      }
    }
  }
  if (invert)
    for (int i=0; i<n; ++i)
      a[i] = a[i] * (1.0 / n);
}

ll mpow(ll x, ll n) {
  ll res = 1;
  while (n) {
    if (n & 1) res = res * x % mod;
    x = x * x % mod;
    n /= 2;
  }
  return res;
}

vl fac(10000, 1);
vl invfac(fac.size(), 1);

ll bin(int k, int n) {
  return fac[n] * invfac[k] % mod * invfac[n-k] % mod;
}

base a[N], c[N];

int main() {
  for (int i = 2; i < fac.size(); ++i) {
    fac[i] = fac[i-1] * i % mod;
    invfac[i] = mpow(fac[i], mod-2);
  }
  int n;
  scanf("%d", &n);
  vi A(n), B(n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d",&A[i],&B[i]);
    --A[i]; --B[i];
    if (A[i] < 1000) {
      a[A[i]*4000 + B[i]].X += 1;
    } else {
      c[(A[i]-1000)*4000 + B[i]].Y += 1;
    }
  }
  fft(a, 0);
  fft(c, 0);
  for (int i = 0; i < N; ++i) {
    auto s = a[i] + c[i];
    a[i] = a[i] * s;
    c[i] = c[i] * s;
  }
  fft(a, 1);
  fft(c, 1);
  for (int i = 0; i < n; ++i) {
    if (A[i] < 1000) a[2*A[i]*4000+2*B[i]].X -= 1;
    else c[2*(A[i]-1000)*4000+2*B[i]].X += 1;
  }
  ll res = 0;
  for (int i = 0; i < 2000*4000; ++i) {
    ll cnt = (ll)round(a[i].X / 2) % mod;
    if (cnt) {
      int a = 2 + i / 4000, b = 2 + i % 4000;
      res = (res + cnt * bin(a, a+b)) % mod;
    }
    cnt = (ll)round(c[i].X / 2) % mod;
    if (cnt) {
      int a = 2002 + i / 4000, b = 2 + i % 4000;
      res = (res - cnt * bin(a, a+b)) % mod;
    }
    cnt = (ll)round(a[i].Y / 2) % mod;
    if (cnt) {
      int a = 1002 + i / 4000, b = 2 + i % 4000;
      res = (res + cnt * bin(a, a+b)) % mod;
    }
  }
  printf("%lld\n", (res + mod) % mod);
  return 0;
}

