int power(int a, int b){
	if (b == 0)
		return 1;
	int ret = power(a, b / 2);
	ret = 1ll * ret * ret % mod;
	if (b & 1)
		ret = 1ll * ret * a % mod;
	return ret;
}

int Choose(int n, int r){
	return 1ll * fac[n] * rev[r] % mod * rev[n - r] % mod;
}

