		fac[i] = 1ll * fac[i - 1] * i % mod;
	rev[4 * B] = power(fac[4 * B], mod - 2);
	for (int i = 4 * B - 1; i >= 0; i--)
		rev[i] = 1ll * rev[i + 1] * (i + 1) % mod;

	for (int i = 0; i < n; i++)
		dp[-x[i] + B][-y[i] + B] ++;

	for (int i = 0; i <= 2 * B; i++){
		for (int j = 0; j <= 2 * B; j++){
