void init(int n)
{
	if(sz==n)return;
	sz=1;
	while(sz<n)sz<<=1;
	w[0]=point(1,0);
	complex<long double> e(0,2*PI/sz);
	complex<long double> unit=exp(e);
	lpoint tw(unit.real(),unit.imag());
	lpoint cur=lpoint(1,0);
	for(int i=1;i<=sz;i++) {
		cur=cur*tw;
		w[i]=point(cur.x,cur.y);
	}
