using R = double;
constexpr R pi = M_PI;
using C = complex<R>;
C& operator*=(C& l, const C& r) {
    return l = {real(l) * real(r) - imag(l) * imag(r), real(l) * imag(r) + imag(l) * real(r)};
}
void fft(vector<C>& a, bool inv = false) {
    int n = a.size();
    int j = 0;
    for (int i = 1; i < n; ++i) {
        int w = n >> 1;
        while (j >= w) j -= w, w >>= 1;
        j += w;
        if (i < j) swap(a[i], a[j]);
    }
    static vector<vector< C > >xi(30);
    for (int k = 0; 1 << k < n; ++k) if (xi[k].empty()) {
        xi[k].resize(1 << k);
        for (int i = 0; i < 1 << k; ++i) {
            xi[k][i] = polar<R>(1, i * pi / (1 << k));
        }
    }
    for (int k = 0; 1 << k < n; ++k) {
        const int w = 1 << k;
        for (int s = 0; s < n; s += 2 * w) {
            for (int i = s; i < s + w; ++i) {
                C p = a[i], q = a[i + w] * (inv ? conj(xi[k][i - s]) : xi[k][i - s]);
                a[i] = p + q, a[i + w] = p - q;
            }
        }
    }
}
template<class Z> void multiply(vector<Z>& a, const vector<Z>& b) {
    int n = 1 << __lg(2 * (a.size() + b.size() - 1) - 1);
    vector<C> c(n);
    for (int i = 0; i < n; ++i) {
        if (i < (int)a.size()) c[i].real(a[i]);
        if (i < (int)b.size()) c[i].imag(b[i]);
    }
    fft(c);
    for (int i = 0; i <= n / 2; ++i) {
        c[i] *= c[i];
        if (i & n / 2 - 1) c[n - i] *= c[n - i];
        c[i] = C(0, -0.25) * (c[i] - conj(c[n - i & n - 1]));
        if (i & n / 2 - 1) c[n - i] = conj(c[i]);
    }
    fft(c, true);
    a.resize(a.size() + b.size() - 1);
    for (int i = 0; i < (int)a.size(); ++i) {
        a[i] = real(c[i]) / n + 0.5;
    }
}


