#define INV2 500000004
#define AB_MAX 2000

typedef long long ll;



bool memoed[8001][4001];
int memo[8001][4001];
int comb(int n,int k){
	if(k == 0 || k == n) return 1;
	if(k > n-k)k = n-k;
	if(memoed[n][k]) return memo[n][k];
	memoed[n][k] = true;
	return memo[n][k] = (comb(n-1,k) + comb(n-1,k-1)) % MOD;
}



int n;
