	scanf("%d",&n);
	int maxa = 0;
	int maxb = 0;
	for(int i = 0;i < n;i++){
		scanf("%d %d", &a[i], &b[i]);
		maxa = max(maxa, a[i]);
		maxb = max(maxb, b[i]);
		DP(-a[i],-b[i])++;
	}
	for(int aa=-maxa;aa<=maxa;aa++)
	for(int bb=-maxb;bb<=maxb;bb++){
		if(bb < maxb){ DP(aa,bb+1) += DP(aa,bb); DP(aa,bb+1) %= MOD; }
		if(aa < maxa){ DP(aa+1,bb) += DP(aa,bb); DP(aa+1,bb) %= MOD; }
	}
	int ans = 0;
	for(int i = 0;i < n;i++){
		ans += DP(a[i],b[i]);
