ll power(ll a, ll n) {
    ll ans = 1;
    while (n > 0) {
        if (n % 2 == 1)
            ans = ans * a % MOD;
        a = a * a % MOD;
        n /= 2;
    }
    return ans;
}
inline ll binom(int a, int b) {
    return frac[a + b] * inv[a] % MOD * inv[b] % MOD;
}

