	for (int i = 1; i < 2 * K; i++)
		f[i] = mult(f[i - 1], i);
	rf[2 * K - 1] = rev(f[2 * K - 1]);
	for (int i = 2 * K - 1; i > 0; i--)
		rf[i - 1] = mult(rf[i], i);


	for (int i = 0; i < K; i++)
		C[i][0] = C[i][i] = 1;
	for (int i = 1; i < K; i++)
