const int mod=1e9+7;
int dp[4001][4001]={0,};
int ans[4001][4001]={0,};
int combi(int n,int r){
    if(r>4000)
        r=n-r;
    if(dp[n][r])
        return dp[n][r];
    if(r==0 || n==r)
        return 1;
    return dp[n][r]=(combi(n-1,r-1)+combi(n-1,r))%mod;
}
int main(){
    int n,answer=0;
    pair<int,int> p[200002];
    scanf("%d",&n);
    for(int i=0;i<n;i++){
        scanf("%d %d",&p[i].first,&p[i].second);
        ans[2001-p[i].first][2001-p[i].second]++;
    }
    for(int i=1;i<4001;i++)
        for(int j=1;j<4001;j++)
            ans[i][j]+=(ans[i-1][j]+ans[i][j-1])%mod;
    for(int i=0;i<n;i++){
        answer+=ans[2001+p[i].first][2001+p[i].second];
        answer-=combi((p[i].first+p[i].second)*2,2*p[i].first);
        answer%=mod;
        if(answer<0)
            answer+=mod;
    }
    printf("%d",answer/2);
}

