LL Pow(LL a, LL b) {
	LL ans = 1, base = a;
	while(b) {
		if(b & 1) ans = ans * base % MOD;
		base = base * base % MOD;
		b >>= 1;
	}
	return ans;
}

void pre() {
	fac[0] = facinv[0] = 1;
	for(int i = 1; i < Maxk; ++i) fac[i] = fac[i - 1] * i % MOD;
	facinv[Maxk - 1] = Pow(fac[Maxk - 1], MOD - 2);
	for(int i = Maxk - 2; i; --i) facinv[i] = facinv[i + 1] * (i + 1) % MOD;
}

LL C(LL a, LL b) {
	return fac[a] * facinv[b] % MOD * facinv[a - b] % MOD;
}

