int mod_pow(int x, int n){
	int ret = 1;
	while (n){
		if (n & 1) ret = 1LL * ret * x % mod;
		x = 1LL * x * x % mod;
		n >>= 1;
	}
	return ret;
}

int C(int x, int y){
	if (x < y) return 0;
	return 1LL * p[x] * inv[y] % mod * inv[x - y] % mod;
