            if (j>0) dp[i][j]=(dp[i][j]+dp[i][j-1])%mod;
        }
    ans=0;
    for (int i=1; i<=n; i++) {
        ans=(ans+dp[a[i]+p][b[i]+p])%mod; 
        ans=((ans-C(a[i]*2+b[i]*2,a[i]*2))%mod+mod)%mod;
    }
    printf("%d\n",1LL*ans*power(2,mod-2)%mod);
    return 0;
}

