inline int mul(int x,int y) {return (x*(ll)y)%MOD;}
void factinit() {
	int got=1;
	for (int x=0;x<=MAXFACT;x++) {
		fact[x]=got;
		got=mul(got,x+1);
	}
	got=mod_pow(got,MOD-2);
	for (int x=MAXFACT;x>=0;x--) {
		got=mul(got,x+1);
		invfact[x]=got;
	}
}
int binom(int n,int k) {
	return mul(fact[n],mul(invfact[k],invfact[n-k]));
}
