int bpow(int a, int b) {
	int res = 1;
	while (b) {
		if (b % 2 == 1) {
			res = (res * (long long)a) % MOD;
		}

		a = (a * (long long)a) % MOD;
		b /= 2;
	}
	return res;
}

bool cmp(pair<int, int> a, pair<int, int> b) {
	int s1 = a.first + a.second;
	int s2 = b.first + b.second;

	if (s1 == s2) return a.first < b.first;
	return s1 < s2;
}

