const int C = 2005;
const int mod = 1e9 + 7;
int dp[2*C][2*C];
int factorial[4*C];

int my_pow(int a, int b) {
	int r = 1;
	while(b) {
		if(b % 2) r = (ll) r * a % mod;
		a = (ll) a * a % mod;
		b /= 2;
	}
	return r;
}
int my_inv(int a) { return my_pow(a, mod - 2); }
int my_div(int a, int b) { return a * (ll) my_inv(b) % mod; }

int bin(int a, int b) { return my_div(factorial[a], (ll) factorial[b] * factorial[a-b] % mod); }

int main() {
