	}
	for(int i = 0; i < 2 * C - 1; ++i)
		for(int j = 0; j < 2 * C - 1; ++j) {
			dp[i][j] %= mod;
			dp[i+1][j] += dp[i][j];
			dp[i][j+1] += dp[i][j];
		}
	int answer = 0;
	for(pair<int,int> p : in) {
		answer = (answer + dp[C+p.first][C+p.second]) % mod;
	}
