const int A = 2000 + 5;

int n;
II a[N];
int gt[N], m[A][A];
int f[A][A];

void giaithua()
{
    gt[0] = 1;;
    for(int i = 1; i <= 4000; i++)
        gt[i] = (gt[i - 1] * i) % MOD;
}

int power(int a, int b)
{
    if(b == 0) return 1;
    if(b == 1) return a;
    int ans = power(a, b / 2);
    ans = (ans * ans) % MOD;
    if(b & 1) ans = (ans * a) % MOD;
    return ans;
}

void modulo()
{
    for(int i = 1; i <= 1000; i++)
    {
        for(int j = 1; j <= 1000; j++)
        {
            m[i][j] = power(gt[i + j], MOD - 2);
        }
    }
}

int tinh(int x, int y)
{
    int ans = 1;
    int val = gt[x + y];
    int val2 = gt[x];
    int val3 = gt[y];
    int m1 = power(val2, MOD - 2);
    int m2 = power(val3, MOD - 2);
    ans = (ans * val) % MOD;
    ans = (ans * m2) % MOD;
    ans = (ans * m1) % MOD;
    return ans;
}

void sub1()
{
    int res = 0;
    for(int i = 1; i < n; i++)
    {
        for(int j = i + 1; j <= n; j++)
        {
            int ans = tinh(a[i].fi + a[j].fi, a[i].se + a[j].se);
            res = (res + ans) % MOD;
        }
    }
    res %= MOD;
    cout << res;
}

void sub2()
{
    for(int i = 1; i <= n; i++)
    {
        int x = a[i].fi, y = a[i].se;
        f[1001 - x][1001 - y] += 1;
    }
    for(int i = 1; i < A; i++)
    {
        for(int j = 1; j < A; j++)
        {
            f[i][j] = (f[i - 1][j] + f[i][j - 1] + f[i][j]) % MOD;
        }
    }
    int res = 0;
    for(int i = 1; i <= n; i++)
    {
        int x = a[i].fi, y = a[i].se;
        res = (res + f[1001 + x][1001 + y]) % MOD;
        res = (res - tinh(x * 2, y * 2) + MOD * MOD) % MOD;
    }
    res = (res + MOD * MOD) % MOD;
    res = (res * power(2, MOD - 2)) % MOD;
    cout << res;

}

