inline void inc(int &x,int y) {x=(x+y)%mod;}

inline int qp(int a,int b) {
	int ret = 1;
	while (b) {
		if (b&1) ret = 1LL * ret * a % mod;
		b >>= 1, a = 1LL * a * a % mod;
	}
	return ret;
}

inline int C(int a,int b) {
	return 1LL * jc[a] * qp(jc[b], mod-2) % mod * qp(jc[a-b], mod-2) % mod;
}

