const ld pi = acos(-1.0);

struct base {
    ld re, im;
    base ( ) : re(0), im(0) {}
    base ( ld re, ld im) : re(re), im(im) { }
    base op + (const base& o) const { return base(re + o.re, im + o.im) ;}
    base op - (const base& o) const { return base(re - o.re, im - o.im) ;}
    base op - () const { return base(-re, -im) ;}
    base op * (const base& o) const {
        return base(re * o.re - im * o.im, re * o.im + im * o.re) ;
        ld t = (re+im)*(o.re-o.im);
        ld t0 = re * o.im;
        ld t1 = im * o.re;
        return base( t - t1 + t0, t0 + t1);
    }
    base op * (ld k) const { return base(re * k, im * k) ;}
    base conj() const { return base(re, -im); }
};

const int MAXN = (1<<25);
base w[MAXN / 2];
base f1[MAXN];
int rev[MAXN];

void build_rev(int n) {
    static int rn = -1;
    if( n == rn ) {
        return ;
    } else {
        rn = n;
        int j = 0;
        int lg_n = 0;
        while( (1<<lg_n) < n ) ++lg_n;
        forn(i, n) if(i) {
            int k = lg_n - 1;
            while( j >= 0 && ((j >> k) & 1) ) {
                j ^= (1 << k);
                --k;
            }
            if( k >= 0 )
                j ^= (1 << k);
            rev[i] = j;
        }
    }
}

void fft(base *a, int n) {
    build_rev(n);
    forn(i, n) if( rev[i] > i )
        swap(a[i], a[rev[i]]);
    for(int l = 2; l <= n; l += l) {
        if( l + l <= n && 0 ) {
            int ll = l / 2;
            l += l;
            ld angle = pi / (2*ll);
            for(int j = 0; j < 2*ll; ++j)
                if( j <= 1 || (j % 512 == 0 && j > 0) )
                    w[j] = base(cos(j * angle), sin(j * angle));
                else
                    w[j] = w[j-1] * w[1];
            for(int i = 0; i < n; i += l)
                forn(j, ll) {
                    base v = a[i + j + ll * 0];
                    base u = a[i + j + ll * 1] * w[2*j];
                    a[i + j + ll * 0] = v + u;
                    a[i + j + ll * 1] = v - u;
                    v = a[i + j + ll * 2];
                    u = a[i + j + ll * 3] * w[2*j];
                    a[i + j + ll * 2] = v + u;
                    a[i + j + ll * 3] = v - u;
                    v = a[i + j + ll * 0];
                    u = a[i + j + ll * 2] * w[j];
                    a[i + j + ll * 0] = v + u;
                    a[i + j + ll * 2] = v - u;
                    v = a[i + j + ll * 1];
                    u = a[i + j + ll * 3] * w[j + ll];
                    a[i + j + ll * 1] = v + u;
                    a[i + j + ll * 3] = v - u;
                }
        } else {
            int ll = l / 2;
            ld angle = pi / ll;
            for(int j = 0; j < ll; ++j)
                if( j <= 1 || j % 1024 == 0 )
                    w[j] = base(cos(j * angle), sin(j * angle));
                else
                    w[j] = w[j-1] * w[1];
            for(int i = 0; i < n; i += l) {
                forn(j, ll) {
                    base v = a[i + j], u = a[i + j + ll] * w[j];
                    a[i + j] = v + u;
                    a[i + j + ll] = v - u;
                }
            }
        }
    }
}

vi mul(const vi& a, const vi& b) {
    int k = 1;
    while( (1<<k) < (a.size() + b.size()) ) ++k;
    int n = (1<<k);
    forn(i, n) f1[i] = base(0,0);
    forn(i, a.size()) f1[i] = f1[i] + base(a[i], 0);
    forn(i, b.size()) f1[i] = f1[i] + base(0, b[i]);
    fft(f1, n);
    forn(i, 1 + n/2) {
        base p = f1[i] + f1[(n-i)%n].conj();
        base _q = f1[(n-i)%n] - f1[i].conj();
        base q(_q.im, _q.re);
        f1[i] = (p * q) * 0.25;
        if( i > 0 )
            f1[(n - i)] = f1[i].conj();
    }
    forn(i, n) f1[i] = f1[i].conj();
    fft(f1, n);
    vi r(n);
    forn(i, n) {
        r[i] = (i64) (f1[i].re / n + 0.5) % (int)(1e9 + 7);
    }
    return r;
}

const int N = 2001;
const int M = 1e9 + 7;

int C[N * 4][N * 2];
int cn = 0;

void sqr(const vi& a, vi& b) {
  const int n = a.size();
  b.assign(n * 2 - 1, 0);
  const int K = (1 << 15);
  b = mul(a, a);
}

void sqr3(const vi& a, vi& b) {
  const int n = a.size();
  b.assign(n * 2 - 1, 0);
  const int K = (1 << 15);
  vi a0(n), a1(n);
  forn(i, n) { a0[i] = a[i] % K; a1[i] = a[i] / K; }
  vi b0 = mul(a0, a0);
  vi b1 = mul(a0, a1);
  vi b2 = mul(a1, a1);
  b.assign(n * 2 - 1, 0);
  forn(i, n * 2 - 1) {
    i64 bb = 0;
    bb += b0[i] % M;
    bb += 2 * b1[i] % M * K % M;
    bb += b2[i] % M * K * K % M;
    b[i] = bb % M;
  }
}

void sqr2(const vi& a, vi& b) {
  const int n = a.size();
  b.assign(n * 2 - 1, 0);
  forn(i, n) forn(j, n)
    b[i + j] = (b[i + j] + a[i] * 1ll * a[j]) % M;
  forn(i, n)
    cerr << a[i] << ' '; cerr << '\n';
  forn(i, n * 2 - 1)
    cerr << b[i] << ' '; cerr << '\n';
}

void init(int n) {
  while (cn <= n) {
    C[cn][0] = C[cn][cn] = 1;
    fore(i, 1, cn - 1) C[cn][i] = (C[cn - 1][i-1] + C[cn - 1][i]) % M;
    // fore(i, 0, cn) cerr << C[cn][i] << ' '; cerr << '\n';
    cn++;
  }
}

void solve() {
  int q;
  // q = 200000;
  scanf("%d", &q);
  vpi Q(q);
  int n = 0;
  int m = 0;
  // forn(i, q) { Q[i].fi = 1 + rand() % 1000; Q[i].se = 1 + rand() % 1000; }
  forn(i, q) scanf("%d%d", &Q[i].fi, &Q[i].se);
  forn(i, q) uax(n, Q[i].fi + Q[i].se);
  forn(i, q) uax(m, Q[i].fi);
  n = n + 1;
  m = 2 * m + 1;
  vi a(n * m);
  forn(i, q) a[(Q[i].fi+Q[i].se) * m + Q[i].fi] += 1;
  while(a.size() > 1 && a.back() == 0) a.pop_back();
  vi b;
  sqr(a, b);
  int div2 = (M + 1) / 2;
  int ans = 0;
  forn(p, b.size()) if (b[p]) {
    int i = p / (m);
    int j = p % (m);
    int r = b[p];
    if (i % 2 == 0 && j % 2 == 0) {
      r = (M + r - a[m * (i / 2) + (j / 2)]) * 1ll * div2 % M;
    } else {
      r = r * 1ll * div2 % M;
    }
    init(i);
    // cerr << i << ' ' << j << ' ' << r << '*' << C[i][j] << '\n';
    ans = (ans + C[i][j] * 1ll * r) % M;
  }
  cout << ans << '\n';
}

