int bit_reversal[N];

void precompute_bit_reversal() {
    for (int i = 1; i < N; ++ i)
        bit_reversal[i] = (bit_reversal[i >> 1] >> 1) + (i & 1) * (1 << (BITS - 1));
}

//typedef complex <double> Point;
class Point {
public:
    double r, i;

    Point(double _r = 0, double _i = 0):
        r(_r), i(_i) {}

    Point operator+(const Point &arg) const {
        return Point(r + arg.r, i + arg.i);
    }
    Point operator-(const Point &arg) const {
        return Point(r - arg.r, i - arg.i);
    }
    Point operator*(const Point &arg) const {
        return Point(r * arg.r - i * arg.i, r * arg.i + i * arg.r);
    }
    Point operator/(const int &arg) const {
        return Point(r / arg, i / arg);
    }
};

const double PI = acos(-1);

Point wk[N];

void fft(Point v[N][N], bool reverse = false) {
    //Apply bit reversal
    for (int i = 0; i < N; ++ i)
        for (int j = 0; j < N; ++ j)
            if (i < bit_reversal[i] || (i == bit_reversal[i] && j < bit_reversal[j]))
                swap(v[i][j], v[bit_reversal[i]][bit_reversal[j]]);

    wk[0] = 1;
    for (int len = 2; len <= N; len *= 2) {
        Point w = Point(cos(2 * PI / len), (1 - 2 * reverse) * sin(2 * PI / len));
        wk[1] = w;

        for (int i = 1; i < len; ++ i)
            wk[i] = w * wk[i - 1];

        Point *vij;

        int i, j, k, l;
        for (i = 0, vij = &v[0][0]; i < N; i += len, vij += N * (len - 1))
            for (j = 0; j < N; j += len, vij += len) {
                Point *v00 = vij;
                Point *v01 = vij + len / 2;
                Point *v10 = vij + N * (len / 2);
                Point *v11 = vij + N * (len / 2) + len / 2;
                Point *wkk = &wk[0];
                Point *wkl = &wk[0];
                Point *wklk = &wk[0];

                for (k = 0; k < len / 2; ++ k, v00 += N - len / 2, v01 += N - len / 2, v10 += N - len / 2, v11 += N - len / 2, ++ wkk, wklk = wkk) {
                    for (l = 0, wkl = &wk[0]; l < len / 2; ++ l, ++ v00, ++ v01, ++ v10, ++ v11, ++ wkl, ++ wklk) {
                        Point p00 = *v00;
                        Point p01 = *wkl * *v01;
                        Point p10 = *wkk * *v10;
                        Point p11 = *wklk * *v11;

                        *v00 = p00 + p01 + p10 + p11;
                        *v01 = p00 - p01 + p10 - p11;
                        *v10 = p00 + p01 - p10 - p11;
                        *v11 = p00 - p01 - p10 + p11;
                    }
                }
            }
    }

    if (reverse)
        for (int i = 0; i < N; ++ i)
            for (int j = 0; j < N; ++ j)
                v[i][j] = v[i][j] / (N * N);
}

