    c[0][0]=1;
    for (int i=1;i<=V*2;i++) {
        c[i][0]=1;
        for (int j=1;j<=min(i,V);j++)
            c[i][j]=Sum(c[i-1][j],c[i-1][j-1]);
    }
}
