void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < 8005; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}
long long COM(int n, int k) {
    if (P[n][k]) return P[n][k]; 
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return P[n][k] = fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}
int main(){
	int N; cin >> N; COMinit(); 
	int A[200010], B[200010]; 
	for(int i = 0; i < N; i++) cin >> A[i] >> B[i];  
	long long X[4010] = {}; 
	for(int i = 0; i < N; i++){
		for(int j = -B[i]; j <= A[i]; j++){
			X[j+2000] += COM(A[i] + B[i], j + B[i]); 
			if(X[j+2000] >= MOD) X[j+2000] -= MOD; 
		}
