void giaithua()
{
    gt[0] = 1;;
    for(int i = 1; i < 2 * A; i++)
        gt[i] = (gt[i - 1] * i) % MOD;
}

int power(int a, int b)
{
    if(b == 0) return 1;
    if(b == 1) return a;
    int ans = power(a, b / 2);
    ans = (ans * ans) % MOD;
    if(b & 1) ans = (ans * a) % MOD;
    return ans;
}

void modulo()
{
    for(int i = 1; i < A; i++)
    {
        m[i] = power(gt[i], MOD - 2);
    }
