int tinh(int x, int y)
{
    int ans = 1;
    int val = gt[x + y];
    int m1 = m[x];
    int m2 = m[y];
    ans = (ans * val) % MOD;
    ans = (ans * m2) % MOD;
    ans = (ans * m1) % MOD;
    return ans;
}


