ll dp[2*MAXM][2*MAXM];

ll fact[2 * MAXM], rfact[2 * MAXM];

ll mod_pow(ll x, ll p, ll MOD) {
    ll a = 1;
    while (p) {
        if (p%2) a = a*x%MOD;
        x = x*x%MOD;
        p/=2;
    }
    return a;
}

// mod_inverse
ll mod_inverse(ll a, ll m) {
    return mod_pow(a, m-2, m);
}

ll nCr(int n, int r) {
	return fact[n] * rfact[r] % MOD * rfact[n - r]%MOD;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	fact[0] = rfact[0] = 1;
	for (int i = 1; i < 2 * MAXM; i++) {
		fact[i] = (fact[i - 1] * i) % MOD;
		rfact[i] = mod_inverse(fact[i], MOD);
	}
	int N;
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> A[i] >> B[i];
		dp[MAXM - A[i]][MAXM - B[i]] += 1;
	}
	for (int x = 0; x < 2 * MAXM-1; x++) for (int y = 0; y < 2 * MAXM-1; y++) if (dp[x][y]) {
		dp[x + 1][y] += dp[x][y];
		dp[x + 1][y] %= MOD;
		dp[x][y + 1] += dp[x][y];
		dp[x][y + 1] %= MOD;
	}
	ll ans = 0;
	for (int i = 0; i < N; i++) {
		(ans += dp[MAXM + A[i]][MAXM + B[i]]) %= MOD;
		(ans -= nCr(2 * A[i] + 2 * B[i], 2 * A[i])) %= MOD;
		if (ans < 0) ans += MOD;
	}
	(ans *= inv2) %= MOD;
	cout << ans << endl;
	return 0;
}

