ll factorial(int const& n, int const& k){
  ll mod = pow(10,9)+7;
  if(factdb[n][k]!=0) return factdb[n][k];
  ll result=1;
  for(int i=0;i<k;i++){
    result *= (ll)((n-i));
    result %= mod;
  }
  for(int i=0;i<k;i++){
    result /= (double)(k-i);
  }
  return factdb[n][k] = (ll)result;
}

ll combidb[5000][5000];
ll mod = pow(10,9)+7;

ll combination(int const& n, int const& k){
  if(combidb[n][k] != 0) return combidb[n][k];
  if(n==(k-1)) return combidb[n][k] = n;
  if(n==k) return combidb[n][k] = 1;
  if(k==0) return combidb[n][k] = 1;
  if(k==1) return combidb[n][k] = n;
  return combidb[n][k] = (combination(n-1,k)%mod + combination(n-1,k-1)%mod)%mod;
}

