void mkay(int &a)
{
	a %= mod;
}

int bpw(int a , int b)
{
	if(!b)
		return 1;

	int x = bpw(a , b / 2);

	x = 1LL * x * x % mod;
	if(b&1)
		x = 1LL * x * a % mod;

	return x;
}

int c(int s , int r)
{
	if(r < 0 || r > s)
		return 0;

	return (1LL * fac[s] * caf[r] % mod) * caf[s - r] % mod;
}

