const int N = 4005, M = 1e9+7, MX = 2e5+7;
int C[N][N];

int dp[N][N];
int st[N][N], en[N][N];

void pre() {
    for (int i=0; i<N; i++) C[i][0] = C[0][i] = 1;
    for (int i=1; i<N; i++)
        for (int j=1; j<N; j++)
            C[i][j] = (C[i-1][j] + C[i][j-1])%M;
}

int main() {
    pre();
    long long ans = 0;

    int n;
    cin>>n;

    for (int i=1; i<=n; i++) {
        int x, y;
        cin>>x>>y;
        ans -= C[x+x][y+y];

        st[N/2-x][N/2-y] += 1;
        en[N/2+x][N/2+y] += 1;
    }

    for (int i=1; i<N; i++) {
        for (int j=1; j<N; j++) {
            dp[i][j] = (dp[i][j-1] + dp[i-1][j] + st[i][j])%M;
            ans += en[i][j] * dp[i][j];
        }
    }
    ans = ans%M;
    while (ans < 0 && ans%2)    ans += M;
    cout<<ans/2<<endl;
}

