#include <bits/stdc++.h>

using namespace std;  

#define ll long long
#define N 200005  
#define M 6005  
#define mod 1000000007  

int n;
int A[N],B[N];
int ans;

int dp[M][M];  

int jc[2 * M - 5], ny[2 * M - 5];  

int read()
{
	int x = 0, f = 1;
	char ch = getchar();
	while (ch < '0' || ch > '9') {if (ch == '-') f = -1; ch = getchar();}
	while (ch >= '0' && ch <= '9') {x = x * 10 + ch - '0'; ch = getchar();}
	return x * f;
}

void exgcd(int a,int b,int &x,int &y)  
{  
    if (!b)
	{
		x = 1;
		y = 0;
		return;
	}  
    exgcd(b, a % b, y, x);  
    y -= a / b * x;  
}  

int NY(int a,int m)  
{  
    int x, y;  
    exgcd(a, m, x, y);  
    return (x % m + m) % m;  
} 

int C(int m,int n)  
{  
    return 1ll * jc[m] * ny[n] % mod * ny[m - n] % mod;  
}  
int main()  
{  
