int comb(int x,int y)
{
	if(x == 0 && y == 0) return 1;
	if(memo [x] [y]) return memo [x] [y];

	int res = 0;
	if(x - 1 >= 0) res += comb(x - 1,y);
	if(y - 1 >= 0) res += comb(x,y - 1);
	res %= MOD;
	return memo [x] [y] = res;
}

