void init(){ fac[0] = 1;
	for(int i = 1; i <= N; ++i) fac[i] = 1ll * fac[i - 1] * i % p;
	inv[N] = pow_mod(fac[N], p - 2);
	for(int i = N - 1; ~i; --i) inv[i] = 1ll * inv[i + 1] * (i + 1) % p;
}

int C(int n, int m){
	if(n < m) return 0;
	return 1ll * fac[n] * inv[m] % p * inv[n - m] % p;
}

