ll exgcd(ll a, ll b, ll& x, ll& y)
{
	ll d = a;
	if (b != 0) {
		d = exgcd(b, a % b, y, x);
		y -= (a / b) * x;
}
	else {
		x = 1; y = 0;
	}
	return d;
}

ll mod_inverse(ll a, ll m)
{
	ll x, y;
	exgcd(a, m, x, y);
	return (m + x % m) % m;
}

