int sz;
point w[mxn+1];
const ld PI=3.14159265358979323846264338327950288;
void init(int n)
{
	if(sz==n)return;
	sz=1;
	while(sz<n)sz<<=1;
	w[0]=point(1,0);
	complex<long double> e(0,2*PI/sz);
	complex<long double> unit=exp(e);
	point tw(unit.real(),unit.imag());
	point cur(1,0);
	for(int i=1;i<=sz;i++) {
		cur=cur*tw;
		w[i]=cur;
	}
}
void FFT(point a[])
{
	for(int i=0,j=0;i<sz;i++)
	{
		if(i>j)swap(a[i],a[j]);
		for(int l=sz>>1;(j^=l)<l;l>>=1);
	}
	int g=sz>>1;
	for(int l=1;l<sz;l<<=1)
	{
		int l2=l<<1;
		for(int i=0;i<sz;i+=l2)
		{
			int outer=0;
			for(int j=0;j<l;j++)
			{
				point t=a[i+j+l]*w[outer];
				auto aij=a[i+j];
				a[i+j+l]=aij-t;
				a[i+j]=aij+t;
				outer+=g;
			}
		}
		g>>=1;
	}
	//if(rev)for(int i=0;i<sz;i++)a[i]=a[i]/sz; // Output should divide by sz*sz
}
void FFTrev(point a[])
{
	for(int i=0,j=0;i<sz;i++)
	{
		if(i>j)swap(a[i],a[j]);
		for(int l=sz>>1;(j^=l)<l;l>>=1);
	}
	int g=sz>>1;
	for(int l=1;l<sz;l<<=1)
	{
		int l2=l<<1;
		for(int i=0;i<sz;i+=l2)
		{
			int outer=sz;
			for(int j=0;j<l;j++)
			{
				point t=a[i+j+l]*w[outer];
				auto aij=a[i+j];
				a[i+j+l]=aij-t;
				a[i+j]=aij+t;
				outer-=g;
			}
		}
		g>>=1;
	}
	//if(rev)for(int i=0;i<sz;i++)a[i]=a[i]/sz; // Output should divide by sz*sz
}

