int POW(int x, int t){
	int res = 1;
	while(t){
		if (t & 1) res = res * x % MOD;
		t >>= 1;
		x = x * x % MOD;
	}
	return res;
}

void calc(){
	fac[0] = 1;
	inv[0] = 1;
	for (int i = 1; i < 200010; i++){
		fac[i] = fac[i - 1] * 1ll * i % MOD;
		inv[i] = POW(fac[i], MOD - 2);
	}
}

int nCr(int x, int y){
	if (y > x || y < 0 || x < 0) return 0;
	int res = fac[x];
	res = res * 1ll * inv[y] % MOD;
	res = res * 1ll * inv[x - y] % MOD;
	return res;
}

