using namespace std;
const int up = 4010;
const int base = 2001;
const int P = 1e9 + 7;
const int inv2 = 5e8 + 4;
inline ll quickpow(ll x, int k) {
  ll res = 1;
  while (k) {
    if (k & 1)  res = res * x % P;
    x = x * x % P;
    k >>= 1;
  }
  return res;
}
int n;
int a[NN], b[NN];
int f[N][N];
int ed[N][N];
ll jie[NN], jieni[NN];
inline void init() {
  jie[0] = jieni[0] = 1;
  for (int i = 1; i <= 10000; ++i)  jie[i] = jie[i - 1] * i % P;
  jieni[10000] = quickpow(jie[10000], P - 2);
  for (int i = 9999; i; --i)  jieni[i] = jieni[i + 1] * (i + 1) % P;
}
inline ll get_c(int n, int m) {
  if (n < 0 || m < 0 || n - m < 0)  return 0;
  return jie[n] * jieni[m] % P * jieni[n - m] % P;
}

inline void work() {
  ll ans = 0;
  for (int i = 1; i <= up; ++i) {
    for (int j = 1; j <= up; ++j) {
      f[i][j] = (1ll * f[i][j] + f[i - 1][j] + f[i][j - 1]) % P;
//      if (i <= base + 3 && i >= base - 3 && j <= base + 3 && j >= base - 3) printf("f[%d][%d] = %d\n", i - base, j - base, f[i][j]);
      if (ed[i][j]) ans = (ans + 1ll * ed[i][j] * f[i][j]) % P;//, printf("ans += %d * %d\n", ed[i][j], f[i][j]);
    }
//    if (i <= base + 3 && i >= base - 3) puts("");
  }
//  printf("yuan : ans = %lld\n", ans);
  for (int i = 1; i <= n; ++i) {
    ans = (ans - get_c((a[i] + b[i]) << 1, a[i] << 1) + P) % P;
  }
//  printf("now ans = %lld\n", ans);
  ans = ans * inv2 % P;
  printf("%lld\n", (ans % P + P) % P);
}

int main() {
  read(n);
  for (int i = 1; i <= n; ++i)  read(a[i]), read(b[i]), ++f[base - a[i]][base - b[i]], ed[base + a[i]][base + b[i]]++;
  init();
  work();
  return 0;
}

