ll exp(ll a, ll b)
{
	if (!b) return 1;
	ll k = exp(a, b / 2);
	if (b & 1)
		return k * k % MOD * a % MOD;
	return k * k % MOD;
}

void init()
{
	fac[0] = invfac[0] = 1;
	for (int i = 1; i <= 8000; i++)
	{
		fac[i] = fac[i - 1] * i % MOD;
		invfac[i] = exp(fac[i], MOD - 2);
//		cout << fac[i] * invfac[i] % MOD << ' ';
	}
}

ll C(int n, int m)
{
	return fac[n] * invfac[m] % MOD * invfac[n - m] % MOD;
}

int main()
{
