void upd(int &x, int y){ x += y; if(x >= mod) x -= mod; }

int quick_mod(int x, int y){
	int res = 1; x %= mod;
	for(; y ; y >>= 1, x = 1LL * x * x % mod)
		if(y & 1) res = 1LL * res * x % mod;
	return res;
}

int C(int x, int y){ return x < y ? 0 : 1LL * fac[x] * inv[y] % mod * inv[x - y] % mod; }

int main(){
