inline int Pow (LL a, int b)
{
	LL ans = 1;
	while (b)
	{
		if (b & 1) (ans *= a) %= Mod;
		(a *= a) %= Mod;
		b >>= 1;
	}
	return ans;
}

inline int C (int n, int m)
{
	return ((LL)fac[n] * inv[m] % Mod * inv[n - m] % Mod);
