ll mod_pow(ll x, ll y){
    ll ret = 1;
    while(y) {
        if(y&1) ret = ret*x%MOD;
        x = x*x%MOD;
        y /= 2;
    }
    return ret;
}

ll conb(ll x, ll y) {
    ll X = 1, Y = 1;
    for(ll i = 1; i <= y; i++) {
        X = X * (x-i+1) % MOD;
        Y = Y * i % MOD;
    }
    return X * mod_pow(Y, MOD-2) % MOD;
}

