ll factorial(int const& n, int const& k){
  ll mod = pow(10,9)+7;
  if(factdb[n][k]!=0) return factdb[n][k];
  ll result=1;
  for(int i=0;i<k;i++){
    result *= (ll)((n-i));
    result %= mod;
  }
  for(int i=0;i<k;i++){
    result /= (double)(k-i);
  }
  return factdb[n][k] = (ll)result;
}

