#include <bits/stdc++.h>
#define LL long long
using namespace std;

const LL Mod = 1000000007;
const LL Maxn = 200010;
const LL MaxAlpha = 2010;
LL N, A[ Maxn ], B[ Maxn ];
LL F[ MaxAlpha << 1 ][ MaxAlpha << 1 ];
LL Fact[ MaxAlpha << 1 ], Inv[ MaxAlpha << 1 ];
LL Ans;

void Exgcd( LL a, LL b, LL &x, LL &y ) {
    if( b == 0 ) {
        x = 1; y = 0;
        return;
    }
    Exgcd( b, a % b, y, x );
    y -= a / b * x;
    return;
}

LL INV( LL a ) {
    LL x, y;
    Exgcd( a, Mod, x, y );
    if( x < 0 ) x += Mod;
    return x;
}

LL C( LL N, LL M ) {
    return Fact[ M ] * Inv[ N ] % Mod * Inv[ M - N ] % Mod;
}

int main() {
    scanf( "%lld", &N );
    for( LL i = 1; i <= N; ++i ) scanf( "%lld%lld", &A[ i ], &B[ i ] );
    for( LL i = 1; i <= N; ++i ) F[ MaxAlpha - A[ i ] ][ MaxAlpha - B[ i ] ] += 1;
    Fact[ 0 ] = 1;
    for( LL i = 1; i < MaxAlpha * 2; ++i ) Fact[ i ] = Fact[ i - 1 ] * i % Mod;
    Inv[ MaxAlpha * 2 - 1 ] = INV( Fact[ MaxAlpha * 2 - 1 ] );
    for( LL i = MaxAlpha * 2 - 2; i >= 0; --i ) Inv[ i ] = Inv[ i + 1 ] * ( i + 1 ) % Mod;
    for( LL i = 1; i < MaxAlpha * 2; ++i )
        for( LL j = 1; j < MaxAlpha * 2; ++j )
            F[ i ][ j ] = ( F[ i ][ j ] + F[ i - 1 ][ j ] + F[ i ][ j - 1 ] ) % Mod;
    for( LL i = 1; i <= N; ++i ) Ans = ( Ans + F[ MaxAlpha + A[ i ] ][ MaxAlpha + B[ i ] ] ) % Mod;
    for( LL i = 1; i <= N; ++i ) 
        Ans = ( ( Ans - C( 2 * A[ i ], 2 * A[ i ] + 2 * B[ i ] ) ) % Mod + Mod ) % Mod;
    Ans = Ans * INV( 2 ) % Mod;
    printf( "%lld\n", Ans );
    return 0;
}

