long long fac[M];

long long power(long long a, long long b) {
	if (b == 0)
		return 1;
	long long t = power(a, b / 2);
	t = (t * t) % mod;
	if (b % 2)
		t = (t * a) % mod;
	return t;
}

long long chs(long long a, long long b) {
	long long t = fac[b];
	t = (t * power(fac[a], mod - 2)) % mod;
	t = (t * power(fac[b - a], mod - 2)) % mod;
	return t;
}

