		cin >> a[i] >> b[i];
		dp[m - a[i]][m - b[i]]++;
		dp[m + a[i]][m + b[i]]--;
	}
	long long res = 0;
	for (int i = 1; i < N; i++) {
		for (int j = 1; j < N; j++) {
			if (dp[i][j] < 0) {
				res = (res + (-1 * dp[i][j]) * (dp[i - 1][j] + dp[i][j - 1])) % mod;
				dp[i][j] = 0;
