            dp[i + 1][j] += dp[i][j];
            dp[i][j + 1] += dp[i][j];
            if (dp[i + 1][j] >= md)
                dp[i + 1][j] %= md;
            if (dp[i][j + 1] >= md)
                dp[i][j + 1] %= md;
        }
    int ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += (dp[MAX + a[i]][MAX + b[i]] + (md - 1) * combination(2 * a[i], 2 * b[i] + 2 * a[i])) % md;
        if (ans >= md)
            ans %= md;
    }
    cout << ans * power(2, md - 2) % md;
    return 0;
}

