int sum(int a, int b) {
    a += b; if (a >= mod) a -= mod; return a;
}

int diff(int a, int b) {
    a -= b; if (a < 0) a += mod; return a;
}

int mul(int a, int b) {
    return (1LL * a * b) % mod;
}

int lgpow(int a, int b) {
    int res = 1;
    for (int i = 0; (1 << i) <= b; ++i) {
        if (b & (1 << i))
            res = mul(res, a);
        a = mul(a, a);
    }
    return res;
}

int f(int x, int y) {
    int res = fact[x+y];
    res = mul(res, ifact[x]);
    res = mul(res, ifact[y]);
    return res;
}

