        int x, y; cin >> x >> y;
        is1[x + N][y + N]++;
        is2[N + -x][N + -y]++;

        bad = (bad + c(2 * (x + y) , 2 * x)) % mod;

        dp[N + -x][N + -y]++;
    }

    for (int i = 1; i < Q; ++i) {
        for (int j = 1; j < Q; ++j) {
            dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
