void cou(int num)
{
	long long x=max(a[num],b[num]),y=min(a[num],b[num]);
	step[num]=1;
	for(int i=1;i<=y;i++)
	{
		step[num]=(step[num]*(x+i))%p;
		step[num]=(step[num]*inv[i])%p;
	}
}
long long cheng(long long a,long long b)
{
	long long now=a,ans=1;
	while(b)
	{
		if(b&1)
			ans=(now*ans)%p;
		b>>=1;
		now=(now*now)%p;
	}
	return ans;
}
void chuli()
{
	d[1]=1;
	for(int i=2;i<=N;i++)
		d[i]=(d[i-1]*i)%p;
	finv[N]=cheng(d[N],p-2);
	for(int i=N-1;i>=1;i--)
		finv[i]=(finv[i+1]*(i+1))%p;
	inv[1]=finv[1];
	for(int i=2;i<=N;i++)
	{
		inv[i]=(finv[i]*d[i-1])%p;
	//	printf("inv[%d]=%d\n",i,inv[i]);
	}
}
