#include <bits/stdc++.h>
using namespace std;
const long long mod=1000000007;
const long long MAXN=4010;
long long n,x[200010],y[200010];
long long dp[MAXN][MAXN];
long long fac[2*MAXN],inv[2*MAXN];
long long C(long long x,long long y){return fac[x]*inv[y]%mod*inv[x-y]%mod;}
long long fpm(long long x,long long y){
	long long res=1;
	while(y){
		if(y&1)res=res*x%mod;
		x=x*x%mod;
		y>>=1;
	}
	return res;
}
long long ans=0;
int main(){
	scanf("%lld",&n);
	for(register long long i=1;i<=n;i++) scanf("%lld%lld",&x[i],&y[i]);
	fac[0]=1;for(register long long i=1;i<=8000;i++)fac[i]=fac[i-1]*i%mod;
	inv[1]=1;for(register long long i=2;i<=8000;i++)inv[i]=(mod-mod/i)*inv[mod%i]%mod;
	inv[0]=1;for(register long long i=1;i<=8000;i++)inv[i]=inv[i-1]*inv[i]%mod;
	memset(dp,0,sizeof(dp));
	for(register long long i=1;i<=n;i++) dp[2005-x[i]][2005-y[i]]++;
	for(register long long i=-2005+1;i<=2005;i++){
		for(register long long j=-2005+1;j<=2005;j++){
			dp[2005+i][2005+j]=(dp[2005+i][2005+j]+dp[2005+i][2005+j-1]+dp[2005+i-1][2005+j])%mod;
		}
	}
	for(register long long i=1;i<=n;i++) ans=(ans+dp[2005+x[i]][2005+y[i]])%mod;
	for(register long long i=1;i<=n;i++) ans=((ans-C(2ll*x[i]+2ll*y[i],2ll*x[i]))%mod+mod)%mod;
	ans=ans*fpm(2,mod-2)%mod;
	printf("%lld\n",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int maxm = 4012;

int f[maxm][maxm];

int m;
int mod = 1e9+7;
int ans = 0;
int x,y;
int g[maxm*2][maxm];
int maxx,maxy;
bool flag[maxm][maxm];

struct self
{
    int x,y;
    self(const int &xx, const int &yy)
    {
        x=xx;
        y=yy;
    }
};
queue<self> q;

void calc()
{
    q.push(self(2000-maxx,2000-maxy));
    flag[2000-maxx][2000-maxy]=1;
    while(!q.empty())
    {
        self u=q.front();q.pop();
        int x,y;
        x=u.x;
        y=u.y+1;
        if(x<=maxx+2000 && y<=maxy+2000)
        {
            f[x][y]=(f[x][y]+f[u.x][u.y])%mod;
            if(!flag[x][y])
            {
                flag[x][y]=1;
                q.push(self(x,y));
            }
        }
        x=u.x+1;
        y=u.y;
        if(x<=maxx+2000 && y<=maxy+2000)
        {
            f[x][y]=(f[x][y]+f[u.x][u.y])%mod;
            if(!flag[x][y])
            {
                flag[x][y]=1;
                q.push(self(x,y));
            }
        }
    }
}

long long rev(long long a)
{
    if(a==1)return 1;
    return rev(mod%a)*(mod-mod/a)%mod;
}

struct node
{
    int x,y;
}s[200011];

int main()
{
    g[1][0]=g[1][1]=1;
    for(int i=2;i<=8000;i++)
    {
        g[i][0]=1;
        for(int j=1;j<=min(i,4000);j++)
            g[i][j]=(g[i-1][j]+g[i-1][j-1])%mod;
    }

    scanf("%d",&m);
    for(int i=1;i<=m;i++)
    {
        scanf("%d%d",&x,&y);
        s[i].x=x;s[i].y=y;
        f[2000-x][2000-y]++;
        maxx=max(maxx,x);
        maxy=max(maxy,y);
        ans=(ans+mod-g[x*2+y*2][x*2])%mod;
    }
    calc();
    for(int i=1;i<=m;i++)
    {
        ans=(ans+f[s[i].x+2000][s[i].y+2000])%mod;
    }
    cout<<ans*rev(2)%mod<<endl;
    return 0;
}

