using namespace std;
const int mod = 1e9 + 7;
const int N = 2e5 + 5;
const int i2 = (mod + 1) / 2;
int n;
int ai[N], bi[N];
int dp[4058][4058];
int C[4058][4058];
int main() {
	ios::sync_with_stdio(false);
	cin >> n;
	C[0][0] = 0; C[1][0] = C[1][1] = 1;
	for(int i = 2; i <= 4050; ++i)
	{
		C[i][0] = C[i][i] = 1;
		for(int j = 1; j <= i - 1; ++j)
			C[i][j] = (C[i-1][j] + C[i-1][j-1]) % mod;
	}
//	cout << C[6][3]<<endl;
	for(int i = 1; i <= n; ++i) 
	{
		cin >> ai[i] >> bi[i];
		dp[2002 - ai[i]][2002 - bi[i]]++;
	}
	for(int i = 1; i <= 4050; ++i) 
		for(int j = 1; j <= 4050; ++j) {
			(dp[i][j] = dp[i][j] + dp[i - 1][j] + dp[i][j - 1]) %= mod;
		}
	long long ans = 0;
	for(int i = 1; i <= n; ++i) {
		(ans += dp[2002 + ai[i]][2002 + bi[i]]) %= mod;
