		int x, y;
		buf = scanf("%d %d", &x, &y);

		inp.emplace_back(x, y);
		dp[mid-x][mid-y] ++;
		dp[mid+x][mid+y] --;
	}

	for (int i = 2; i < max_sum; i++) {
		for (int j = 2; j < max_sum; j++) {
			ll c = 0;
			if (dp[i][j] < 0) {
				c = -dp[i][j];
				dp[i][j] = 0;
			}
			dp[i][j] = (dp[i][j] + dp[i-1][j] + dp[i][j-1]) % mod;

			res = (res + c*dp[i][j]) % mod;

			int i2 = i-2, j2 = j-2;
			if (!i2 or !j2) {
				dp[i2][j2] = 1; 
