const int N = 200000 + 5;
const int KCZ = 1e9 + 7 , L = N - 5;

int n , A[N] , B[N];

LL fac[N] , inv[N];

LL mp(LL x , LL y = KCZ - 2)
{
    LL res = 1;
    while(y)
    {
        if(y & 1) res = res * x % KCZ;
        x = x * x % KCZ;
        y >>= 1;
    }
    return res;
}

void init()
{
    fac[0] = 1;
    rep(i , 1 , L)
        fac[i] = fac[i - 1] * i % KCZ;
    inv[0] = 1;
    inv[L] = mp(fac[L]);
    per(i , L - 1 , 1)
        inv[i] = inv[i + 1] * (i + 1) % KCZ;
}

int delta;

const int M = 4000 + 5;

LL f[M][M];

void add(LL &x , const LL &y)
{
    x += y ; if(x >= KCZ) x -= KCZ;
}

void sub(LL &x , const LL &y)
{
    x -= y ; if(x < 0) x += KCZ;
}

LL C(int n , int m)
{
    if(n < m) return 0;
    return fac[n] * inv[m] % KCZ * inv[n - m] % KCZ;
}

int main()
{
    read(n) , init();
    rep(i , 1 , n)
        read(A[i]) , read(B[i]);
    rep(i , 1 , n)
        chkmax(delta , max(A[i] , B[i]));
    rep(i , 1 , n)
        f[delta - A[i]][delta - B[i]]++; 
    rep(i , -delta , delta)
        rep(j , -delta , delta)
        {
            if(i >= -delta + 1)
                add(f[i + delta][j + delta] , f[i - 1 + delta][j + delta]);
            if(j >= -delta + 1)
                add(f[i + delta][j + delta] , f[i + delta][j - 1 + delta]);
        }
    LL Ans = 0;
    rep(i , 1 , n)
    {
        add(Ans , f[delta + A[i]][delta + B[i]]);
        sub(Ans , C(2 * (A[i] + B[i]) , 2 * A[i]));
    }
    Ans = Ans * mp(2) % KCZ;
    cout << Ans << endl;
    return 0;
}

