long long int kon(int k,int l){//lが小さい
	long long int su = 1;
	long long int se = 1;
    for (int i = k; i > l; i--)
    {
        su *= i;
	}
	 for (int i = 1; i <=k-l; i++)
    {
        se *= i;
	}

    return (long long int)su/se;
}

