void Exgcd( LL a, LL b, LL &x, LL &y ) {
    if( b == 0 ) {
        x = 1; y = 0; return;
    }
    Exgcd( b, a % b, y, x );
    y -= a / b * x;
    return;
}

LL inv( LL a ) {
    LL b = Mod;
    LL x, y;
    Exgcd( a, b, x, y );
    if( x < 0 ) return x + Mod; else return x;
}

LL C( LL n, LL m ) {
    return Fact[ m ] * Inv[ n ] % Mod * Inv[ m - n ] % Mod;
}

