typedef long long ll;

ll modpow(ll a, ll n, ll mod) {
	ll ret = 1;
	while (n) {
		if (n % 2)
			ret = (ret * a) % mod;
		a = (a * a) % mod;
		n /= 2;
	}
	return ret;
}

ll modinv(ll r) {
	return modpow(r, MOD - 2, MOD);
}

void proc() {
