			comb[i][i] = 1;
		}
		for (int j = 1; j < i; ++j) {
			if (j > 4000) {
				break;
			}
			comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD;
		}
	}

	long long ans = 0;
