    long double count=0;

    for (i=0;i<4200;i++){
        for (j=0;j<4200;j++){
            if(j==1){
                memo[i][j]=i;
            }
            else if (i==j){
                memo[i][j]=1;
            }
            else{
                memo[i][j]=0;
            }
        }
    }

