    int n;
    scanf("%d", &n);
    int *a;
    int *b;
    a = (int *)malloc(sizeof(int) * n);
    b = (int *)malloc(sizeof(int) * n);
    for (size_t i = 0; i < n; i++) {
        scanf("%d %d", &a[i],&b[i] );
    }
    long long int  ans = 0;
    for ( size_t i = 0; i < n; i++) {
        for (size_t k = i+1; k < n; k++) {
            int meet = a[i]+a[k];
            int veg = b[i] + b[k];
            ans += combi(meet+veg, meet)%(10000000+7);
        }
    }
    printf("%lld\n", ans);
    return 0;
}

