int Comb(int n,int r){
  int cmb,l;
  cmb=1;
  if(n<2*r){
    r=n-r;
  }
  for(l=1;l<=r;l++){
    cmb=(cmb*(n-l+1)/l)%1000000007;
  }
  return cmb;
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007
#define AB 2000
#define AB2 4001
#define N 200005

typedef struct set {
	int a;
	int b;
} set;

int main(){
	int i,j;
	int n;
	int a,b;
	long long int **dp;
	long long int **root;
	long long int res = 0;
	set s[N];
	dp = calloc(sizeof(long long int*),AB2);
	for(i = 0;i < AB2;i++){
		dp[i] = calloc(sizeof(long long int),AB2);
	}
	root = calloc(sizeof(long long int*),AB2);
	for(i = 0;i < AB2;i++){
		root[i] = calloc(sizeof(long long int),AB2);
	}
	scanf("%d",&n);
	for(i = 0;i < n;i++){
		scanf("%d %d",&a,&b);
		s[i].a = a;
		s[i].b = b;
		root[AB - a][AB - b]++;
	}
	for(i = 0;i < AB2;i++){
		dp[0][i] = dp[i][0] = 1;
	}
	for(i = 1;i < AB2;i++){
		for(j = 1;j < AB2;j++){
			dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD;
			root[i][j] += (root[i-1][j] + root[i][j-1]);
			root[i][j] %= MOD;
		}
	}
	for(i = 0;i < n;i++){
		res+=root[AB + s[i].a][AB + s[i].b];
		res-=dp[s[i].a*2][s[i].b*2];
		if(res<0){
			res+=MOD;
		}
		res%=MOD;
	}
	printf("%lld\n", res % 2 == 0 ? res / 2 : (res + MOD) / 2);
	return 0;
}

