	int n;
	int a,b;
	long long int **dp;
	long long int **root;
	long long int res = 0;
	set s[N];
	dp = calloc(sizeof(long long int*),AB2);
	for(i = 0;i < AB2;i++){
		dp[i] = calloc(sizeof(long long int),AB2);
	}
	root = calloc(sizeof(long long int*),AB2);
	for(i = 0;i < AB2;i++){
		root[i] = calloc(sizeof(long long int),AB2);
	}
	scanf("%d",&n);
	for(i = 0;i < n;i++){
		scanf("%d %d",&a,&b);
		s[i].a = a;
		s[i].b = b;
		root[AB - a][AB - b]++;
	}
	for(i = 0;i < AB2;i++){
		dp[0][i] = dp[i][0] = 1;
	}
	for(i = 1;i < AB2;i++){
		for(j = 1;j < AB2;j++){
			dp[i][j] = (dp[i-1][j] + dp[i][j-1]) % MOD;
			root[i][j] += (root[i-1][j] + root[i][j-1]);
			root[i][j] %= MOD;
		}
	}
