       int result=0;
       for(int i=0;i<N;i++){
           for(int j=i+1;j<N;j++){
               A=arr[i][0]+arr[j][0];
               B=arr[j][1]+arr[j][1];
               total=A+B;
               result=result+(factorial(total)/(factorial(A)*factorial(B)));              
           }
       }
        System.out.println(result);

    }
    public static int factorial(int a){
        int fact=1;
        for(int i=2;i<=a;i++)
                fact=fact*i;
        return fact;
    }
