                result += Cab(left[i]+left[j],right[i]+right[j]);
            }
        }
        System.out.println(result);
    }
    public static long Cab(long a, long b) {
        return jc(a+b)/(jc(a)*jc(b));
    }
    // 阶乘
    public static long jc(long n) {
        long result = 1;
        for (long i = 1; i <= n; i++) {
            result = i * result;
        }
        return result;
    }
}

