		}

		for (int a = -2000; a <= 2000; a++) {
			for (int b = -2000; b <= 2000; b++) {
				long x = dp[a+O][b+O] + dp[a-1+O][b+O] + dp[a+O][b-1+O];
				if (x >= MOD) x %= MOD;
				dp[a+O][b+O] = x;
				if (a >= 0 && b >= 0 && cnt[a][b] > 0) {
					ans += cnt[a][b] * x % MOD;
					if (ans >= MOD) ans %= MOD;
				}
			}
		}
