            }
        }
        System.out.println(result);
    }
    public static int Cab(int a, int b) {
        return jc(a+b)/(jc(a)*jc(b));
    }
    // 阶乘
    public static int jc(int n) {
        int result = 1;
        for (int i = 1; i <= n; i++) {
            result = i * result;
        }
        return result;
    }
}

