		int mod = 1000000007;
		int[][] fif = enumFIF(10000, mod);
		long ret = 0;
		for(int i = 0;i < n;i++){
			int x = ni(), y = ni();
			a[2001-x][2001-y]--;
			a[2001+x][2001+y]++;
			ret -= C(2*x+2*y, 2*x, mod, fif);
		}
		long[][] dp = new long[4005][4005];
		for(int i = 1;i < 4004;i++){
			for(int j = 1;j < 4004;j++){
				dp[i][j] = dp[i-1][j] + dp[i][j-1];
				if(dp[i][j] >= mod)dp[i][j] -= mod;
				if(a[i][j] < 0){
					dp[i][j] -= a[i][j];
					if(dp[i][j] >= mod)dp[i][j] -= mod;
				}else{
					ret += dp[i][j] * a[i][j];
					ret %= mod;
				}
			}
		}
		ret %= mod;
		if(ret < 0)ret += mod;
		ret = ret * invl(2, mod) % mod;
		out.println(ret);
	}

	public static long C(int n, int r, int mod, int[][] fif) {
		if (n < 0 || r < 0 || r > n)
			return 0;
		return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
	}


	public static int[][] enumFIF(int n, int mod) {
		int[] f = new int[n + 1];
		int[] invf = new int[n + 1];
		f[0] = 1;
		for (int i = 1; i <= n; i++) {
			f[i] = (int) ((long) f[i - 1] * i % mod);
		}
		long a = f[n];
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		invf[n] = (int) (p < 0 ? p + mod : p);
		for (int i = n - 1; i >= 0; i--) {
			invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
		}
		return new int[][] { f, invf };
	}


	public static long invl(long a, long mod) {
		long b = mod;
		long p = 1, q = 0;
		while (b > 0) {
			long c = a / b;
			long d;
			d = a;
			a = b;
			b = d % b;
			d = p;
			p = q;
			q = d - c * q;
		}
		return p < 0 ? p + mod : p;
	}


