import java.io.*;
import java.util.*;
public class Main
{
	final int zero=2001,maxn=2000;
	int n,a[],b[];
	long dp[][];
	final long mod=(long)(1e9+7);
	private void solve()throws IOException
	{
		fact();
		n=nextInt();
		a=new int[n+1];
		b=new int[n+1];
		dp=new long[zero+maxn+1][zero+maxn+1];
		for(int i=1;i<=n;i++)
		{
			a[i]=nextInt();
			b[i]=nextInt();
			dp[zero-a[i]][zero-b[i]]++;
		}
		for(int i=-maxn;i<=maxn;i++)
			for(int j=-maxn;j<=maxn;j++)
				dp[zero+i][zero+j]=(dp[zero+i][zero+j]+(dp[zero+i-1][zero+j])+(dp[zero+i][zero+j-1])%mod)%mod;
		long ans=0;
		for(int i=1;i<=n;i++)
			ans=(ans+dp[zero+a[i]][zero+b[i]])%mod;
		for(int i=1;i<=n;i++)
			ans=(ans-choose(2*a[i]+2*b[i],2*a[i])+mod)%mod;
		out.println((ans*modinv(2))%mod);
	}
	long choose(int n,int r)
	{
		return (((fact[n]*modinv(fact[r]))%mod)*modinv(fact[n-r]))%mod;
	}
	long fact[];
	void fact(){
		fact=new long[8000+1];
		fact[0]=1;
		for(int i=1;i<=8000;i++)
			fact[i]=(fact[i-1]*i)%mod;
	}
	long modinv(long x){
	    return modpow(x,mod-2);
	}
	long modpow(long a,long b){
	    long ret=1;
	    while(b!=0)
	    {
	        if(b%2==1)
	            ret=(ret*a)%mod;
	        a=(a*a)%mod;
	        b=b/2;
	    }
	    return ret;
	} 


	///////////////////////////////////////////////////////////

	public void run()throws IOException
	{
		br=new BufferedReader(new InputStreamReader(System.in));
		st=null;
		out=new PrintWriter(System.out);

		solve();

		br.close();
		out.close();
	}
	public static void main(String args[])throws IOException{
		new Main().run();
	}
	BufferedReader br;
	StringTokenizer st;
	PrintWriter out;
	String nextToken()throws IOException{
		while(st==null || !st.hasMoreTokens())
		st=new StringTokenizer(br.readLine());
		return st.nextToken();
	}
	String nextLine()throws IOException{
		return br.readLine();
	}
	int nextInt()throws IOException{
		return Integer.parseInt(nextToken());
	}
	long nextLong()throws IOException{
		return Long.parseLong(nextToken());
	}
	double nextDouble()throws IOException{
		return Double.parseDouble(nextToken());
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Main {
	public static void main(String[] args) throws IOException {
		new Main().run();

	}

	private static void run() throws IOException {
		BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

		int N = Integer.parseInt(reader.readLine());
		ArrayList<Set> list = new ArrayList<Set>();

		for (int i = 0; i < N; ++i) {
			String str = reader.readLine();

			int a = Integer.parseInt(str.substring(0, str.indexOf(" ")));
			int b = Integer.parseInt(str.substring(str.indexOf(" ") + 1, str.length()));

			list.add(new Set(a, b));
		}

		int sum = 0;
		for (int i = 0; i < N; ++i) {
			for (int j = i + 1; j < N; ++j) {

				int a = list.get(i).a + list.get(j).a;
				int b = list.get(i).b + list.get(j).b;
				int c = a + b;

				int max = Math.max(a, b);

				int lim = c - a + 1;
				int top = 1;
				int bottom = 1;
				while (c >= lim) {
					top *= c--;
				}
				while (max >= 1) {
					bottom *= max--;
				}

				sum += top / bottom;

			}
		}

		System.out.println(sum);

	}

	private static class Set {
		int a = 0;
		int b = 0;

		public Set(int a, int b) {
			this.a = a;
			this.b = b;
		}
	}

}

