				comb[i][i] = 1;
			for(int j=1; j<=Math.min(i, MAX*2); j++)
				comb[i][j] = (int)((comb[i-1][j-1]+comb[i-1][j])%MOD);
		}

		long sum = 0;
		for(int i=0; i<N; i++) {
			int A = sc.nextInt();
			int B = sc.nextInt();
			p[MAX+A][MAX+B]--;
			p[MAX-A][MAX-B]++;
			sum -= comb[A*2+B*2][A*2];
			if(sum<0)
				sum += MOD;
		}
		comb = null;

		long[][] dp = new long[MAX*2+1][MAX*2+1];
		for(int i=0; i<=MAX*2; i++) {
			for(int j=0; j<=MAX*2; j++) {
				dp[i][j] = ((i>0 ? dp[i-1][j] : 0) + (j>0 ? dp[i][j-1] : 0) + Math.max(p[i][j],0))%MOD;
				if(p[i][j]<0)
					sum = (sum -(p[i][j]*dp[i][j]))%MOD;
			}
		}

		if(sum%2==0)
			sum /= 2;
		else
			sum = (sum+MOD)/2;

		System.out.println(sum);

		sc.close();
	}
}

