	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const int Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int N;
		Tuple<int, int>[] t;
		void Read()
		{
			sc.Read(out N);
			t = sc.ReadManyLines<int, int>(N);
		}
		long[] fact;
		int MAX = 2001;
		void SolveOne()
		{
			fact = new long[2 * MAX + 1];
			fact[0] = 1;
			for (var i = 1; i <= 2 * MAX; i++) fact[i] = i * fact[i - 1] % Mod;
			var count = new int[2 * MAX + 1, 2 * MAX + 1];
			for (var i = 0; i < N; i++) count[MAX - t[i].Item1, MAX - t[i].Item2]++;
			for (var i = 0; i < 2 * MAX; i++)
				for (var j = 0; j < 2 * MAX; j++)
				{
					count[i, j + 1] = (int)((count[i, j + 1] + count[i, j]) % Mod);
					count[i + 1, j] = (int)((count[i + 1, j] + count[i, j]) % Mod);
				}
			var sum = 0L;
			for (var i = 0; i < N; i++) sum = (sum + count[MAX + t[i].Item1, MAX + t[i].Item2]) % Mod;
			for (var i = 0; i < N; i++) sum = (sum - Comb(2 * (t[i].Item1 + t[i].Item2), 2 * t[i].Item1)) % Mod;
			sum = (sum * Func.Inverse(2, Mod)) % Mod;
			if (sum < 0) sum += Mod;
			pr.WriteLine(sum);
		}
		long Comb(int i, int j) { return fact[i] * Func.Inverse(fact[j] * (long)fact[i - j], Mod) % Mod; }
	}
