class Program
{
  const ulong num = 1000000007;
  static ulong Sum(ulong[] nums)
  {
    ulong ret = 0;
    foreach(ulong n in nums)
    {
      ret = ret + n;
      if(ret > num)
        ret -= num;
    }
    return ret;
  }
  static ulong Kumiawase(int a, int b)
  {
    ulong ret = 1;
    foreach(ulong n in Enumerable.Range(1, a + b).Skip(b))
    {
      ret *= n;
      ret %= num;
    }
    foreach(ulong n in Enumerable.Range(2, a - 1))
      ret /= n;
    //Console.WriteLine(ret);
    return ret;
  }
  static void Main()
  {
    int n = int.Parse(Console.ReadLine());
    int[][] gu = 
      Enumerable.Range(0, n)
      	.Select(x => Console.ReadLine().Split().Select(int.Parse).ToArray()).ToArray();
    ulong result =
      Sum(Enumerable.Range(0, n - 1)
      	.Select(x =>
            Sum(Enumerable.Range(0, n)
                .Skip(x + 1)
                .Select(y => 
                    Kumiawase(gu[x][0] + gu[y][0], gu[x][1] + gu[y][1])).ToArray()
               )).ToArray());
    Console.WriteLine(result);
  }
}

