ulong[ulong] FACTS;

ulong factorial(ulong n, ulong mod) {
  if (n == 0) {
    return 1;
  } else if (n == 1) {
    return 1;
  }
  ulong m = 1;
  ulong _n = n;

  for (; n > 1; n--) {
    if (n in FACTS) {
			m *= FACTS[n];
			break;
		}
    m *= n % mod;
  }

  FACTS[_n] = m % mod;
  return m % mod;
}

