    foreach (j; n.iota) {
      if (i == j) continue;
      ulong k = ab[i].sum + ab[j].sum;
      answer += factorial(k, m) / 
        (factorial(ab[i][0] + ab[j][0], m) * factorial(ab[i][1] + ab[j][1], m));
    }
  }

  writeln(answer/2);
}

