        if (r.value==0 || r==n) return one;
        if (r.value<0 || n.value<r.value) return zero;
        if (r.value*2 > n.value) return memoize!comb(n, n-r);
        return memoize!comb(n-one, r-one) + memoize!comb(n-one, r);
    }
    static typeof(this) comb(T n, T r) {
        return comb(typeof(this)(n), typeof(this)(r));
    }
