ulong[][] choose(long n, long r)
{
  ulong[][] dp = new ulong[][](n+1, r+1);

  int i,j = 0;
  for (i=0;i<n;i++) {
    dp[i][0] = 1;
  }
  for (j=0;j<r;j++) {
    dp[0][j] = 0;
  }
  for (i=1;i<=n;i++) {
    for (j=1;j<=r;j++) {
      if (i==j) {
        dp[i][j] = 1;
      } else if (j>i) {
        dp[i][j] = 0;
      } else {
        dp[i][j] = dp[i-1][j-1] + dp[i-1][j];
        //writefln("nCr (n = %d, r = %d) = %d", i, j, dp[i][j]);
      }
    }
  }

  return dp;
}

