    let mut kits = Vec::new();
    for line in stdin.lock().lines().take(n).map(|x| x.unwrap()) {
        let mut split = line.split(' ').map(|x| x.parse::<usize>().unwrap());
        let (a, b) = (split.next().unwrap(), split.next().unwrap());
        kits.push((a, b));
    }
    let mut sum = 0;
    let mut bc = BinomialCoef::new(8000);
    for i in 0..n {
        for j in (i + 1)..n {
            let m = kits[i].0 + kits[j].0;
            let v = kits[i].1 + kits[j].1;
            // Sum up C(m + v, m).
            sum = (sum + bc.get(m + v, m)) % MOD;
        }
    }
    println!("{}", sum);
}

struct BinomialCoef {
    coef: Vec<Vec<u32>>,
}

impl BinomialCoef {
    fn new(max_n: usize) -> BinomialCoef {
        BinomialCoef {
            coef: (0..(max_n + 1)).map(|i| vec![0; i / 2 + 1]).collect() }
    }

    fn get(&mut self, n: usize, mut k: usize) -> u32 {
        if n - k < k {
            k = n - k;
        }
        if k == 0 {
            return 1;
        } else if self.coef[n][k] == 0 {
            self.coef[n][k] =
                (self.get(n - 1, k - 1) + self.get(n - 1, k)) % MOD;
        }
        self.coef[n][k]
    }
}

