mod scanner {
    use std;
    pub struct Scanner<R> {
        reader: R,
        buf: Vec<u8>,
    }
    #[allow(dead_code)]
    impl<R: std::io::BufRead> Scanner<R> {
        pub fn new(reader: R) -> Self {
            Scanner {
                reader: reader,
                buf: Vec::with_capacity(1024),
            }
        }
        fn read(&mut self, del: u8) {
            self.buf.clear();
            self.reader.read_until(del, &mut self.buf).ok();
            assert!(self.buf.pop().unwrap() == del);
        }
        pub fn next<T: std::str::FromStr>(&mut self, del: u8) -> T {
            self.read(del);
            std::str::from_utf8(&self.buf)
                .unwrap()
                .trim()
                .parse::<T>()
                .ok()
                .unwrap()
        }
        pub fn next_bytes(&mut self, del: u8) -> Vec<u8> {
            self.read(del);
            std::str::from_utf8(&self.buf)
                .unwrap()
                .trim()
                .bytes()
                .collect()
        }
    }
}
// ---------- end scanner(require delimiter) ----------

fn main() {
    let stdin = std::io::stdin();
    let mut sc = scanner::Scanner::new(stdin.lock());
    run(&mut sc);
}

fn run<R: std::io::BufRead>(sc: &mut scanner::Scanner<R>) {
    let n: usize = sc.next(b'\n');
    let m = 2000;
    let mut g = vec![vec![]; m + 1];
    for _ in 0..n {
        let a: usize = sc.next(b' ');
        let b: usize = sc.next(b'\n');
        g[a].push(b);
    }
    let mut dp = vec![ModInt::zero(); 2 * m + 1];
    for g in g.iter().rev() {
        for b in g.iter() {
            dp[m - *b] += ModInt::one();
        }
        let mut prev = ModInt::zero();
        for v in dp.iter_mut() {
            *v += prev;
            prev = *v;
        }
    }
    let mut ans = ModInt::zero();
    for g in g.iter().skip(1) {
        let mut prev = ModInt::zero();
        for v in dp.iter_mut() {
            *v += prev;
            prev = *v;
        }
        for b in g.iter() {
            ans += dp[m + *b];
        }
    }
    let pc = Precalc::new(2 * m);
    for (a, g) in g.iter().enumerate() {
        for b in g.iter() {
            ans -= pc.comb(2 * a + 2 * b, 2 * a);
        }
    }
    ans *= pc.inv(2);
    println!("{}", ans);
}

