            for i in (0 .. 2 * BIAS - 1).rev() {
                f[i + 1] += f[i];
                f[i + 1] %= MOD;
            }
            cur -= 1;
        }
        if a != 0 {
            f[b] += 1;
            f[b] %= MOD;
        }
    }
    // squaring
    let mut f2 = 0;
    for i in 1 .. 2 * BIAS {
        f2 += f[2 * BIAS - i] * f[i];
        f2 %= MOD;
    }
    let mut r = (f2 - dbl + MOD) % MOD;
    r *= (MOD + 1) / 2;
    r %= MOD;
    println!("{}", r);
}

