mod scanner {
    use std;
    pub struct Scanner<R> {
        reader: R,
        buf: Vec<u8>,
    }
    #[allow(dead_code)]
    impl<R: std::io::BufRead> Scanner<R> {
        pub fn new(reader: R) -> Self {
            Scanner {
                reader: reader,
                buf: Vec::with_capacity(1024),
            }
        }
        fn read(&mut self, del: u8) {
            self.buf.clear();
            self.reader.read_until(del, &mut self.buf).ok();
            assert!(self.buf.pop().unwrap() == del);
        }
        pub fn next<T: std::str::FromStr>(&mut self, del: u8) -> T {
            self.read(del);
            std::str::from_utf8(&self.buf)
                .unwrap()
                .trim()
                .parse::<T>()
                .ok()
                .unwrap()
        }
        pub fn next_bytes(&mut self, del: u8) -> Vec<u8> {
            self.read(del);
            std::str::from_utf8(&self.buf)
                .unwrap()
                .trim()
                .bytes()
                .collect()
        }
    }
}
// ---------- end scanner(require delimiter) ----------

fn main() {
    let stdin = std::io::stdin();
    let mut sc = scanner::Scanner::new(stdin.lock());
    run(&mut sc);
}

fn run<R: std::io::BufRead>(sc: &mut scanner::Scanner<R>) {
    let n: usize = sc.next(b'\n');
    let m = 2000;
    let mut g = vec![vec![]; m + 1];
    for _ in 0..n {
        let a: usize = sc.next(b' ');
        let b: usize = sc.next(b'\n');
        g[a].push(b);
    }
    let mut dp = vec![ModInt::zero(); 2 * m + 1];
    for g in g.iter().rev() {
        for b in g.iter() {
            dp[m - *b] += ModInt::one();
        }
        let mut prev = ModInt::zero();
        for v in dp.iter_mut() {
            *v += prev;
            prev = *v;
        }
    }
    let mut ans = ModInt::zero();
    for g in g.iter().skip(1) {
        let mut prev = ModInt::zero();
        for v in dp.iter_mut() {
            *v += prev;
            prev = *v;
        }
        for b in g.iter() {
            ans += dp[m + *b];
        }
    }
    let pc = Precalc::new(8 * m);
    for (a, g) in g.iter().enumerate() {
        for b in g.iter() {
            ans -= pc.comb(2 * a + 2 * b, 2 * a);
        }
    }
    ans *= pc.inv(2);
    println!("{}", ans);
}

use std::io::BufRead;

const MOD: u32 = 1000000007;

fn main() {
    let stdin = std::io::stdin();
    let line = stdin.lock().lines().next().unwrap().unwrap();
    let n = line.parse::<usize>().unwrap();
    let mut kits = Vec::new();
    for line in stdin.lock().lines().take(n).map(|x| x.unwrap()) {
        let mut split = line.split(' ').map(|x| x.parse::<usize>().unwrap());
        let (a, b) = (split.next().unwrap(), split.next().unwrap());
        kits.push((a, b));
    }
    let mut sum = 0;
    let mut bc = BinomialCoef::new(4000);
    for i in 0..n {
        for j in (i + 1)..n {
            let m = kits[i].0 + kits[j].0;
            let v = kits[i].1 + kits[j].1;
            // Sum up C(m + v, m).
            sum = (sum + bc.get(m + v, m)) % MOD;
        }
    }
    println!("{}", sum);
}

struct BinomialCoef {
    coef: Vec<Vec<u32>>,
}

impl BinomialCoef {
    fn new(max_n: usize) -> BinomialCoef {
        BinomialCoef {
            coef: (0..(max_n + 1)).map(|i| vec![0; i / 2 + 1]).collect() }
    }

    fn get(&mut self, n: usize, mut k: usize) -> u32 {
        if n - k < k {
            k = n - k;
        }
        if k == 0 || k == n {
            return 1;
        } else if self.coef[n][k] == 0 {
            self.coef[n][k] =
                (self.get(n - 1, k - 1) + self.get(n - 1, k)) % MOD;
        }
        self.coef[n][k]
    }
}
